def emit_build_method_result_frame_ensures_map_group(desc: Dict[str, Any], whyml_ident) -> List[str]:
    """Emit `_build_method_result_frame_ensures_map` — the `\\result`-referencing quantified
    single-cell FRAME twin. Filter (over `propagate_frame` opt-in methods only) =
    `classify(e, pset, {}) is not False and saw(e,"field") and saw(e,"forall") and saw(e,"result")`,
    encoded as the param-AND-bound-threaded `(nd, hf, hforall, hr)` catamorphism: a `Forall`/
    `Exists`/`ForallItems` node adds its binder to the bound set `bd` before descending, so a bound
    `k` is not mistaken for a local; `\\result` is PERMITTED (nd stays true). `ensures True`;
    frame-gated; ledger 3."""
    n = whyml_ident(desc["name"])
    P = f"{n}__"
    mv = _pvw_mv(desc["param"])
    st = desc.get("self_type")
    self_type = whyml_ident(st.lower()) if st else "autotrustmixin"
    out: List[str] = []
    out += _emit_lmem(P)
    out += _emit_skey_reader(f"{P}gtype", "type")
    out += _emit_skey_reader(f"{P}gnm", "name")
    out += _emit_skey_reader(f"{P}gvar", "var")
    out += _emit_skey_reader(f"{P}gobject", "object")
    out += _emit_pval_reader(f"{P}gvalue", "value")
    out += _emit_pval_reader(f"{P}gvarpv", "var")
    out.append(f"  let {P}selfobj (d: pydict) : bool = "
               f'match {P}gobject d with Some s -> pystr_eq s "self" | None -> false end')
    out.append(f"  let rec {P}cv (v: pyval) (ps: list pyval) (bd: list pyval) : (bool, bool, bool, bool)")
    out.append("    requires { true } ensures { true } variant { pv_size v }")
    out.append("  = match v with")
    out.append("    | PDict d ->")
    out.append(f"        (match {P}gtype d with")
    out.append("         | Some t ->")
    out.append('             if pystr_eq t "OldVar" then (false, false, false, false)')
    out.append('             else if pystr_eq t "Result" then (true, false, false, true)')
    out.append('             else if pystr_eq t "FieldGet" || pystr_eq t "Attribute"')
    out.append('                     || pystr_eq t "OldField" then')
    out.append(f"                 let s = {P}selfobj d in (s, s, false, false)")
    out.append('             else if pystr_eq t "Var" then')
    out.append(f'                 let ok = (match {P}gnm d with Some nm -> {P}lmem nm ps || {P}lmem nm bd | None -> false end) in')
    out.append("                 (ok, false, false, false)")
    out.append('             else if pystr_eq t "ArrayLen" then')
    out.append(f"                 (match {P}gvarpv d with")
    out.append(f'                  | Some (PStr s) -> let ok = (pystr_eq s "self") || {P}lmem s ps || {P}lmem s bd in (ok, false, false, false)')
    out.append(f"                  | Some (PDict vd) -> let ok = {P}selfobj vd in (ok, false, false, false)")
    out.append("                  | _ -> (false, false, false, false) end)")
    out.append('             else if pystr_eq t "Subscript" then')
    out.append(f"                 (match {P}gvalue d with")
    out.append(f"                  | Some (PDict vd) -> (match {P}gtype vd with")
    out.append(f'                                        | Some vt -> if pystr_eq vt "Var" then (false, false, false, false) else {P}cdf d ps bd')
    out.append(f"                                        | None -> {P}cdf d ps bd end)")
    out.append(f"                  | _ -> {P}cdf d ps bd end)")
    out.append('             else if pystr_eq t "Forall" || pystr_eq t "Exists"')
    out.append('                     || pystr_eq t "ForallItems" then')
    out.append(f"                 let nb = (match {P}gvar d with Some s -> Cons (PStr s) bd | None -> bd end) in")
    out.append(f"                 let (a, b, _, r) = {P}cdf d ps nb in (a, b, true, r)")
    out.append(f"             else {P}cdf d ps bd")
    out.append(f"         | None -> {P}cdf d ps bd end)")
    out.append(f"    | PList xs -> {P}clf xs ps bd")
    out.append("    | _ -> (true, false, false, false)")
    out.append("    end")
    out.append(f"  with {P}cdf (d: pydict) (ps: list pyval) (bd: list pyval) : (bool, bool, bool, bool)")
    out.append("    requires { true } ensures { true } variant { size_dict d }")
    out.append("  = match d with DNil -> (true, false, false, false)")
    out.append("    | DCons _ v rest -> size_pos v;")
    out.append(f"        let (a1, b1, c1, d1) = {P}cv v ps bd in let (a2, b2, c2, d2) = {P}cdf rest ps bd in "
               "(a1 && a2, b1 || b2, c1 || c2, d1 || d2) end")
    out.append(f"  with {P}clf (xs: list pyval) (ps: list pyval) (bd: list pyval) : (bool, bool, bool, bool)")
    out.append("    requires { true } ensures { true } variant { size_list xs }")
    out.append("  = match xs with Nil -> (true, false, false, false)")
    out.append(f"    | Cons h t -> let (a1, b1, c1, d1) = {P}cv h ps bd in let (a2, b2, c2, d2) = {P}clf t ps bd in "
               "(a1 && a2, b1 || b2, c1 || c2, d1 || d2) end")
    keep = f"let (a, b, c, d0) = {P}cv e ps Nil in a && b && c && d0"
    out += _emit_ensures_map_scaffold_pt(n, P, self_type, mv, keep, frame_gated=True)
    return out


def recognize_build_method_field_param_frame_ensures_map(func: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    """Fail-closed match of `_build_method_field_param_frame_ensures_map`. Never raises."""
    try:
        return _recognize_build_method_field_param_frame_ensures_map(func)
    except Exception:
        return None


def _recognize_build_method_field_param_frame_ensures_map(func: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    if not func.get("name", "").endswith("_build_method_field_param_frame_ensures_map"):
        return None
    params = func.get("formal_params") or []
    if len(params) != 1:
        return None
    tags = set(_all_strings(func.get("body") or []))
    # `contracts`/`ensures`/`name` drive the outer fold; `Call` is the discriminant of the
    # `_frame_trigger_term(e).type == "Call"` gate (mutation-sensitive — dropping the Call
    # gate from the body removes this literal and un-matches the recognizer).
    if not {"contracts", "ensures", "name", "Call"}.issubset(tags):
        return None
    return {"name": func["name"], "param": params[0], "self_type": func.get("self_type")}


def emit_build_method_field_param_frame_ensures_map_group(desc: Dict[str, Any], whyml_ident) -> List[str]:
    """Emit `_build_method_field_param_frame_ensures_map` — the QUANTIFIED self-field FRAME map
    (the boundary-dropped `\\forall k. guard -> X == \\old(X)` frames re-exposed for `propagate_frame`
    opt-in methods). Filter (over `propagate_frame` methods only) =
    `classify(e, pset, {}) is not False and saw(e,"field") and saw(e,"forall") and not saw(e,"result")
    and refs_param(e, pset) and _frame_trigger_term(e) is a Call`. Encoded as the param-AND-bound-
    threaded `(nd, hf, hforall, hp)` catamorphism (nd = no-disallowed leaf, hf = has self-field,
    hforall = has quantifier, hp = references a formal param) PLUS a depth-first `{P}ftt` search that
    returns the frame-trigger term X (the non-`\\old` side of a `BinOp ==` conjunct with exactly one
    `\\old`/`\\old`-field side) whose `type == "Call"` is the last conjunct. `classify` REJECTS
    `Result`/`OldVar` (nd=false), so `not saw(e,"result")` is subsumed by nd. `ensures True`;
    frame-gated; ledger 3. Faithful lowering of the live body (the `\\result`-dropping twin of
    `_build_method_result_frame_ensures_map`); mutation-pinned by the byte-identical mirror oracle."""
    n = whyml_ident(desc["name"])
    P = f"{n}__"
    mv = _pvw_mv(desc["param"])
    st = desc.get("self_type")
    self_type = whyml_ident(st.lower()) if st else "autotrustmixin"
    out: List[str] = []
    out += _emit_lmem(P)
    out += _emit_skey_reader(f"{P}gtype", "type")
    out += _emit_skey_reader(f"{P}gnm", "name")
    out += _emit_skey_reader(f"{P}gvar", "var")
    out += _emit_skey_reader(f"{P}gobject", "object")
    out += _emit_skey_reader(f"{P}gop", "op")
    out += _emit_pval_reader(f"{P}gvalue", "value")
    out += _emit_pval_reader(f"{P}gvarpv", "var")
    out += _emit_pval_reader(f"{P}gleft", "left")
    out += _emit_pval_reader(f"{P}gright", "right")
    out.append(f"  let {P}selfobj (d: pydict) : bool = "
               f'match {P}gobject d with Some s -> pystr_eq s "self" | None -> false end')
    # (nd, has_field, has_forall, has_param) catamorphism — classify+saw(field)+saw(forall)+refs_param.
    out.append(f"  let rec {P}cv (v: pyval) (ps: list pyval) (bd: list pyval) : (bool, bool, bool, bool)")
    out.append("    requires { true } ensures { true } variant { pv_size v }")
    out.append("  = match v with")
    out.append("    | PDict d ->")
    out.append(f"        (match {P}gtype d with")
    out.append("         | Some t ->")
    out.append('             if pystr_eq t "Result" || pystr_eq t "OldVar" then (false, false, false, false)')
    out.append('             else if pystr_eq t "FieldGet" || pystr_eq t "Attribute"')
    out.append('                     || pystr_eq t "OldField" then')
    out.append(f"                 let s = {P}selfobj d in (s, s, false, false)")
    out.append('             else if pystr_eq t "Var" then')
    out.append(f'                 let inps = (match {P}gnm d with Some nm -> {P}lmem nm ps | None -> false end) in')
    out.append(f'                 let inbd = (match {P}gnm d with Some nm -> {P}lmem nm bd | None -> false end) in')
    out.append("                 (inps || inbd, false, false, inps)")
    out.append('             else if pystr_eq t "ArrayLen" then')
    out.append(f"                 (match {P}gvarpv d with")
    out.append(f'                  | Some (PStr s) -> let inps = {P}lmem s ps in')
    out.append(f'                                     let ok = (pystr_eq s "self") || inps || {P}lmem s bd in')
    out.append("                                     (ok, false, false, inps)")
    out.append(f"                  | Some (PDict vd) -> let ok = {P}selfobj vd in (ok, false, false, false)")
    out.append("                  | _ -> (false, false, false, false) end)")
    out.append('             else if pystr_eq t "Subscript" then')
    out.append(f"                 (match {P}gvalue d with")
    out.append(f"                  | Some (PDict vd) -> (match {P}gtype vd with")
    out.append(f'                                        | Some vt -> if pystr_eq vt "Var" then (false, false, false, false) else {P}cdf d ps bd')
    out.append(f"                                        | None -> {P}cdf d ps bd end)")
    out.append(f"                  | _ -> {P}cdf d ps bd end)")
    out.append('             else if pystr_eq t "Forall" || pystr_eq t "Exists"')
    out.append('                     || pystr_eq t "ForallItems" then')
    out.append(f"                 let nb = (match {P}gvar d with Some s -> Cons (PStr s) bd | None -> bd end) in")
    out.append(f"                 let (a, b, _, p) = {P}cdf d ps nb in (a, b, true, p)")
    out.append(f"             else {P}cdf d ps bd")
    out.append(f"         | None -> {P}cdf d ps bd end)")
    out.append(f"    | PList xs -> {P}clf xs ps bd")
    out.append("    | _ -> (true, false, false, false)")
    out.append("    end")
    out.append(f"  with {P}cdf (d: pydict) (ps: list pyval) (bd: list pyval) : (bool, bool, bool, bool)")
    out.append("    requires { true } ensures { true } variant { size_dict d }")
    out.append("  = match d with DNil -> (true, false, false, false)")
    out.append("    | DCons _ v rest -> size_pos v;")
    out.append(f"        let (a1, b1, c1, d1) = {P}cv v ps bd in let (a2, b2, c2, d2) = {P}cdf rest ps bd in "
               "(a1 && a2, b1 || b2, c1 || c2, d1 || d2) end")
    out.append(f"  with {P}clf (xs: list pyval) (ps: list pyval) (bd: list pyval) : (bool, bool, bool, bool)")
    out.append("    requires { true } ensures { true } variant { size_list xs }")
    out.append("  = match xs with Nil -> (true, false, false, false)")
    out.append(f"    | Cons h t -> let (a1, b1, c1, d1) = {P}cv h ps bd in let (a2, b2, c2, d2) = {P}clf t ps bd in "
               "(a1 && a2, b1 || b2, c1 || c2, d1 || d2) end")
    # `_frame_trigger_term`: first depth-first `BinOp ==` conjunct with EXACTLY one `\old`/`\old`-field
    # side; returns the post-state (non-old) side X. `is_old` recognises `Old`/`OldField` heads.
    out.append(f"  let {P}is_old (o: (option pyval)) : bool =")
    out.append("    match o with")
    out.append(f'    | Some (PDict dd) -> (match {P}gtype dd with Some t -> pystr_eq t "Old" || pystr_eq t "OldField" | None -> false end)')
    out.append("    | _ -> false end")
    out.append(f"  let rec {P}ftt (v: pyval) : (option pyval)")
    out.append("    requires { true } ensures { true } variant { pv_size v }")
    out.append("  = match v with")
    out.append("    | PDict d ->")
    out.append(f"        (match {P}gtype d with")
    out.append('         | Some t ->')
    out.append(f'             if pystr_eq t "BinOp" && (match {P}gop d with Some o -> pystr_eq o "==" | None -> false end) then')
    out.append(f"                 let l = {P}gleft d in let r = {P}gright d in")
    out.append(f"                 let lo = {P}is_old l in let ro = {P}is_old r in")
    out.append("                 if ro && (not lo) then l")
    out.append("                 else if lo && (not ro) then r")
    out.append(f"                 else {P}ftt_cdf d")
    out.append(f"             else {P}ftt_cdf d")
    out.append(f"         | None -> {P}ftt_cdf d end)")
    out.append(f"    | PList xs -> {P}ftt_clf xs")
    out.append("    | _ -> None")
    out.append("    end")
    out.append(f"  with {P}ftt_cdf (d: pydict) : (option pyval)")
    out.append("    requires { true } ensures { true } variant { size_dict d }")
    out.append("  = match d with DNil -> None")
    out.append("    | DCons _ v rest -> size_pos v;")
    out.append(f"        (match {P}ftt v with Some x -> Some x | None -> {P}ftt_cdf rest end) end")
    out.append(f"  with {P}ftt_clf (xs: list pyval) : (option pyval)")
    out.append("    requires { true } ensures { true } variant { size_list xs }")
    out.append("  = match xs with Nil -> None")
    out.append(f"    | Cons h t -> (match {P}ftt h with Some x -> Some x | None -> {P}ftt_clf t end) end")
    keep = (f"let (a, b, c, p) = {P}cv e ps Nil in a && b && c && p "
            f'&& (match {P}ftt e with Some (PDict xd) -> '
            f'(match {P}gtype xd with Some tt -> pystr_eq tt "Call" | None -> false end) | _ -> false end)')
    out += _emit_ensures_map_scaffold_pt(n, P, self_type, mv, keep, frame_gated=True)
    return out


def _bmem_base(nm: str) -> str:
    return nm.rsplit("__", 1)[-1] if "__" in (nm or "") else (nm or "")


# per-kind: (standalone recognizer, {nested-def base -> required discriminant tags in it})
_BMEM_KINDS = [
    ("result", recognize_build_method_result_ensures_map,
     {"result_only": {"Var", "FieldGet", "Attribute", "OldVar", "OldField",
                      "Result", "ArrayLen", "var", "\\result"}}),
    ("field_result", recognize_build_method_field_result_ensures_map,
     {"classify": {"OldVar", "OldField", "FieldGet", "Attribute", "Var", "ArrayLen",
                   "var", "\\result", "object", "self"},
      "saw": {"result", "field", "Result", "FieldGet", "Attribute", "self", "object"}}),
    ("field_old", recognize_build_method_field_old_ensures_map,
     {"classify": {"Result", "FieldGet", "Attribute", "OldField", "OldVar", "Var",
                   "ArrayLen", "var", "self", "object"},
      "refs_self_field_or_old": {"FieldGet", "Attribute", "OldField", "self", "object"}}),
    ("param_result", recognize_build_method_param_result_ensures_map,
     {"classify": {"FieldGet", "Attribute", "OldVar", "OldField", "Var", "name",
                   "Result", "ArrayLen", "var", "\\result"},
      "refs_param": {"Var", "name", "ArrayLen", "var"},
      "rename": {"Var", "name"}}),
    ("field_param_result", recognize_build_method_field_param_result_ensures_map,
     {"classify": {"OldVar", "OldField", "FieldGet", "Attribute", "object", "self",
                   "Var", "name", "ArrayLen", "var", "\\result"},
      "saw": {"result", "Result", "field", "FieldGet", "Attribute", "self", "object",
              "\\result", "ArrayLen", "var"},
      "rename": {"Var", "name"},
      "refs_param": {"Var", "name", "ArrayLen", "var"}}),
    ("field_param_post", recognize_build_method_field_param_post_ensures_map,
     {"classify": {"Result", "Forall", "Exists", "ForallItems", "FieldGet", "Attribute",
                   "object", "self", "Subscript", "value", "Var", "name", "ArrayLen", "var"},
      "saw_field": {"FieldGet", "Attribute", "object", "self"},
      "refs_param": {"Var", "name"},
      "rename": {"Var", "name"}}),
    ("result_frame", recognize_build_method_result_frame_ensures_map,
     {"classify": {"Result", "FieldGet", "Attribute", "OldField", "object", "self", "OldVar",
                   "Subscript", "value", "Var", "name", "ArrayLen", "var",
                   "Forall", "Exists", "ForallItems"},
      "saw": {"field", "FieldGet", "Attribute", "OldField", "self", "object", "forall",
              "Forall", "Exists", "ForallItems", "result", "Result", "\\result",
              "ArrayLen", "var"},
      "rename": {"Var", "name"}}),
    ("field_param_frame", recognize_build_method_field_param_frame_ensures_map,
     {"classify": {"Result", "FieldGet", "Attribute", "OldField", "OldVar", "object", "self",
                   "Subscript", "value", "Var", "name", "ArrayLen", "var",
                   "Forall", "Exists", "ForallItems"},
      "saw": {"field", "FieldGet", "Attribute", "OldField", "self", "object", "forall",
              "Forall", "Exists", "ForallItems", "result", "Result"},
      "refs_param": {"Var", "name", "ArrayLen", "var"},
      "rename": {"Var", "name"}}),
]


def recognize_build_method_ensures_map_pairs(functions: List[Dict[str, Any]]) -> Dict[str, Any]:
    """Pair the `_build_method_*_ensures_map` cluster outers with their LIFTED nested-def
    siblings. Module5 hoists each nested `def result_only/classify/saw/refs_self_field_or_old`
    to a `<class>__<nested>` top-level pseudo-function (and the two `classify` defs of the
    field_result / field_old maps hoist to the SAME name — a collision that disappears only
    once BOTH are suppressed). The discriminant string literals therefore live in the SIBLINGS,
    not the outer body, so the outer's mutation-sensitivity is enforced here by tag-checking the
    ADJACENT siblings. A match records the outer id -> {kind,name,param,self_type} and the
    sibling ids for SUPPRESSION (the group-emit is self-contained). Returns {outer_ids,
    walk_ids}; fail-closed (never raises)."""
    outer_ids: Dict[int, Dict[str, Any]] = {}
    walk_ids: set = set()
    n = len(functions)
    for i, f in enumerate(functions):
        try:
            desc = None
            kind = None
            nested_spec = None
            for k, rec, spec in _BMEM_KINDS:
                d = rec(f)
                if d is not None:
                    desc, kind, nested_spec = d, k, spec
                    break
            if desc is None:
                continue
            # collect the consecutive lifted nested-def siblings and their tag unions
            sib_ids: List[int] = []
            tags_by_base: Dict[str, set] = {}
            j = i + 1
            while j < n:
                g = functions[j]
                base = _bmem_base(g.get("name", ""))
                if base not in nested_spec:
                    break
                sib_ids.append(id(g))
                tags_by_base.setdefault(base, set()).update(_all_strings(g.get("body") or []))
                j += 1
            # every expected nested def must be present with its discriminant tags
            ok = all(base in tags_by_base and req.issubset(tags_by_base[base])
                     for base, req in nested_spec.items())
            if not ok:
                continue
            desc = dict(desc)
            desc["kind"] = kind
            outer_ids[id(f)] = desc
            walk_ids.update(sib_ids)
        except Exception:
            continue
    return {"outer_ids": outer_ids, "walk_ids": walk_ids}


# ---- `_test_contains_map`: recursive bool predicate (map/array truthiness in a test) ----
# A short-circuiting bool fold over the pyval IR tree: Subscript-family nodes recurse ONLY
# their index children; a `Var` whose name is in the (param) map-locals set is a hit; the two
# cross-mixin `_rhs_yields_map`/`_rhs_yields_array` predicates (opaque pyval->bool over-
# approximations) are hits; otherwise descend generically over `.values()` (dict) + nested
# lists. Non-vacuous (returns a real bool), coupling-safe (bool return, no verified caller).

def _tcm_str_elts(node: Any) -> Optional[List[str]]:
    """A Tuple/List IR node of String literals -> [values], else None."""
    if not (isinstance(node, dict) and node.get("type") in ("Tuple", "List", "ListLit")):
        return None
    out: List[str] = []
    for e in node.get("elts", []) or []:
        s = _is_string(e)
        if s is None:
            return None
        out.append(s)
    return out or None


def recognize_test_contains_map(func: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    """Fail-closed match of `_test_contains_map`. Never raises."""
    try:
        return _recognize_test_contains_map(func)
    except Exception:
        return None


def _recognize_test_contains_map(func: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    if not func.get("name", "").endswith("_test_contains_map"):
        return None
    if func.get("return_annotation") != "bool":
        return None
    params = func.get("formal_params") or []
    if len(params) != 2:
        return None
    expr_p, ml_p = params
    body = func.get("body") or []
    # [not-isinstance guard, subscript-If, var-If, rhs-If, values-For, Return]
    if len(body) != 6:
        return None
    # --- subscript-If: `expr.get("type") in (T...)` with an inner `for key in (K...)` ---
    sub_if = body[1]
    st = sub_if.get("test") if isinstance(sub_if, dict) else None
    if not (isinstance(st, dict) and st.get("type") == "BinOp" and st.get("op") == "in"):
        return None
    if _get_str(st.get("left"), "func") != f"{expr_p}.get":
        return None
    sub_tags = _tcm_str_elts(st.get("right"))
    if not sub_tags:
        return None
    forn = next((s for s in (sub_if.get("body") or []) if isinstance(s, dict) and s.get("stmt") == "For"), None)
    idx_keys = _tcm_str_elts(forn.get("iter")) if isinstance(forn, dict) else None
    if not idx_keys:
        return None
    # --- var-If: `expr.get("type") == "Var" and expr.get("name") in map_locals` ---
    var_if = body[2]
    vt = var_if.get("test") if isinstance(var_if, dict) else None
    if not (isinstance(vt, dict) and vt.get("type") == "BinOp" and vt.get("op") == "and"):
        return None
    veq = vt.get("left") or {}
    var_tag = _is_string(veq.get("right")) if isinstance(veq, dict) and veq.get("op") == "==" else None
    vin = vt.get("right") or {}
    name_key = None
    if isinstance(vin, dict) and vin.get("op") == "in":
        name_key = _is_string((vin.get("left") or {}).get("args", [{}])[0]) \
            if _get_str(vin.get("left"), "func") == f"{expr_p}.get" else None
    if not (var_tag and name_key):
        return None
    # --- rhs-If: `self._rhs_yields_map(expr) or self._rhs_yields_array(expr)` ---
    rhs_if = body[3]
    rt = rhs_if.get("test") if isinstance(rhs_if, dict) else None
    if not (isinstance(rt, dict) and rt.get("type") == "BinOp" and rt.get("op") == "or"):
        return None
    m0 = _canon_call(_get_str(rt.get("left"), "func"))
    m1 = _canon_call(_get_str(rt.get("right"), "func"))
    if not (m0 and m1 and m0 != m1):
        return None
    # --- values-For: `for v in expr.values()` ---
    vfor = body[4]
    if not (isinstance(vfor, dict) and vfor.get("stmt") == "For"
            and _get_str(vfor.get("iter"), "func") == f"{expr_p}.values"):
        return None
    return {"name": func["name"], "expr": expr_p, "map_locals": ml_p,
            "sub_tags": sub_tags, "idx_keys": idx_keys, "var_tag": var_tag,
            "name_key": name_key, "rhs0": m0, "rhs1": m1}


def _get_str(node: Any, key: str) -> str:
    """`node[key]` when it is a string, else ''."""
    if isinstance(node, dict):
        v = node.get(key)
        if isinstance(v, str):
            return v
    return ""


def emit_test_contains_map_group(desc: Dict[str, Any], whyml_ident) -> List[str]:
    """Emit `_test_contains_map` as a short-circuiting recursive bool fold over pyval.
    The two cross-mixin predicates are OPAQUE pyval->bool over-approximations (sound under
    ensures-True; input-dependent, non-facade). Index/values descent terminates via the
    pget_dyn size postcondition + `pv_size`/`size_dict`/`size_list` measures. Ledger 3."""
    n = whyml_ident(desc["name"])
    ml = "map string bool"
    sub_or = " || ".join(f'pystr_eq t "{tg}"' for tg in desc["sub_tags"])
    out: List[str] = []
    # opaque cross-mixin bool predicates (pyval-typed; sound over-approx of _rhs_yields_map/array)
    out.append(f"  val {n}__rhs0 (e: pyval) : bool")
    out.append(f"  val {n}__rhs1 (e: pyval) : bool")
    # K_type / K_name string readers
    out.append(f"  let rec {n}__gtype (d: pydict) : option string")
    out.append("    variant { d }")
    out.append("  = match d with DNil -> None")
    out.append("    | DCons K_type (PStr s) _ -> Some s")
    out.append(f"    | DCons _ _ rest -> {n}__gtype rest end")
    out.append(f"  let rec {n}__gname (d: pydict) : option string")
    out.append("    variant { d }")
    out.append("  = match d with DNil -> None")
    out.append("    | DCons K_name (PStr s) _ -> Some s")
    out.append(f"    | DCons _ _ rest -> {n}__gname rest end")
    # index-key recursion helper: get the value under key, recurse iff PDict
    def _idx_branch(key: str) -> str:
        return (f'(match pget_dyn "{key}" d with Some v -> '
                f"(match v with PDict _ -> {n} self v map_locals | _ -> false end) | None -> false end)")
    idx_or = " || ".join(_idx_branch(k) for k in desc["idx_keys"])
    # main mutual block
    out.append(f"  let rec {n} (self: autotrustmixin) (expr: pyval) (map_locals: {ml}) : bool")
    out.append("    requires { true } ensures { true } variant { pv_size expr }")
    out.append("  = match expr with")
    out.append("    | PDict d ->")
    out.append(f'        let is_sub = (match {n}__gtype d with Some t -> ({sub_or}) | None -> false end) in')
    out.append("        if is_sub then")
    out.append(f"          ({idx_or})")
    out.append("        else")
    out.append(f'          let is_var = (match {n}__gtype d with Some t -> pystr_eq t "{desc["var_tag"]}" | None -> false end) in')
    out.append(f"          let nm_in = (match {n}__gname d with Some nm -> map_locals nm | None -> false end) in")
    out.append("          if (is_var && nm_in) then true")
    out.append(f"          else if ({n}__rhs0 expr || {n}__rhs1 expr) then true")
    out.append(f"          else {n}__dfold self d map_locals")
    out.append("    | _ -> false")
    out.append("    end")
    out.append(f"  with {n}__dfold (self: autotrustmixin) (d: pydict) (map_locals: {ml}) : bool")
    out.append("    requires { true } ensures { true } variant { size_dict d }")
    out.append("  = match d with DNil -> false")
    out.append("    | DCons _ v rest ->")
    out.append("        size_pos v;")
    out.append(f"        (match v with PDict _ -> {n} self v map_locals | PList xs -> {n}__lfold self xs map_locals | _ -> false end)")
    out.append(f"        || {n}__dfold self rest map_locals end")
    out.append(f"  with {n}__lfold (self: autotrustmixin) (xs: list pyval) (map_locals: {ml}) : bool")
    out.append("    requires { true } ensures { true } variant { size_list xs }")
    out.append("  = match xs with Nil -> false")
    out.append(f"    | Cons h t -> {n} self h map_locals || {n}__lfold self t map_locals end")
    return out


# ---- `_collect_map_typed_locals` (auto_trust.py, boundary-A SET-COLLECT sibling of
#      `_collect_struct_pack_assign_targets`): the OUTER wrapper
#        result: Set[str] = set(); walk(stmts); return result
#      and its lifted `walk(items)` sibling
#        for s in items:
#          if s.get("stmt") == "Assign":
#            tgt = s.get("target", "")
#            if tgt and self._rhs_yields_map(s.get("value", {})): result.add(tgt)
#          for k in ("body","orelse"):
#            if k in s: walk(s[k])
#          if s.get("stmt") == "While": walk(s.get("body", []))
#          if s.get("stmt") == "For":   walk(s.get("body", []))
#          if s.get("stmt") == "Try":   walk(s.get("body", []))
#                                       for h in s.get("handlers", []): walk(h.get("body", []))
#      Same OUTER+lifted-walk adjacency pairing as `_collect_struct_pack_assign_targets`,
#      but the leaf gate is `tgt and _rhs_yields_map(value)` (only `_rhs_yields_map` is the
#      opaque-but-sound `val <n>__rhsmap (v:pyval):bool`; the REAL `target` string is read
#      off the pydict and `set_add`-ed — the anti-vacuity signal). The wrapper emits the
#      ref-accumulator `map string bool` fold over the pyval stmt list; body/orelse/handler
#      recursion reuses the split search+project `pget`-shape list readers with the
#      `size_list`/`size_dict` termination pins. The lifted `walk` is SUPPRESSED. Keyed on
#      `id`; corpus-inert (name-gated). `set_add`/`const` come with the pydict theory. Ledger 3.

def _recognize_cmtl_outer(func: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    """Match the OUTER `_collect_map_typed_locals` wrapper
    `result = set(); walk(stmts); return result`. Fail-closed.
    Returns {name, param, self_type, walker_name, acc}."""
    if not func.get("name", "").endswith("_collect_map_typed_locals"):
        return None
    if func.get("return_annotation") != "set":
        return None
    params = func.get("formal_params") or []
    if len(params) != 1:
        return None
    stmts_p = params[0]
    body = func.get("body") or []
    if len(body) != 3:
        return None
    b0, b1, b2 = body
    # [0] result = set()
    if not (isinstance(b0, dict) and b0.get("stmt") == "Assign"):
        return None
    acc = b0.get("target")
    iv = b0.get("value") or {}
    if not (isinstance(acc, str) and isinstance(iv, dict) and iv.get("type") == "Call"
            and iv.get("func") == "set" and not iv.get("args")):
        return None
    # [1] walk(stmts)
    if not (isinstance(b1, dict) and b1.get("stmt") == "Expr"):
        return None
    call = b1.get("value") or {}
    if not (isinstance(call, dict) and call.get("type") == "Call"
            and isinstance(call.get("func"), str)):
        return None
    cargs = call.get("args") or []
    if not (len(cargs) == 1 and _is_var(cargs[0], stmts_p)):
        return None
    # [2] return result
    if not (isinstance(b2, dict) and b2.get("stmt") == "Return"
            and _is_var(b2.get("value"), acc)):
        return None
    return {"name": func.get("name"), "param": stmts_p,
            "self_type": func.get("self_type"), "walker_name": call["func"], "acc": acc}


def _recognize_cmtl_walk(walkfunc: Dict[str, Any],
                         call_names: "set") -> Optional[Dict[str, Any]]:
    """Match the lifted `walk(items)` map-typed-local collect and extract the leaf
    discriminant literals. Fail-closed. Returns the key/tag dict."""
    params = walkfunc.get("formal_params") or []
    if len(params) != 1:
        return None
    items_p = params[0]
    body = walkfunc.get("body") or []
    if len(body) != 1:
        return None
    forst = body[0]
    # for s in items:
    if not (isinstance(forst, dict) and forst.get("stmt") == "For"
            and _is_var(forst.get("iter"), items_p)):
        return None
    sv = forst.get("target")
    fb = forst.get("body") or []
    if not (isinstance(sv, str) and fb):
        return None
    # fb[0]: if s.get("<stmt_key>") == "<assign_tag>": [tgt = s.get("<target_key>", ""),
    #                                                   if tgt and _rhs_yields_map(...): result.add(tgt)]
    ag = fb[0]
    if not (isinstance(ag, dict) and ag.get("stmt") == "If"):
        return None
    agt = ag.get("test") or {}
    if not (isinstance(agt, dict) and agt.get("type") == "BinOp" and agt.get("op") == "=="):
        return None
    stmt_key = _frss_dotget_key(agt.get("left"), sv)
    assign_tag = _clean_lit(_is_string(agt.get("right")))
    if stmt_key is None or assign_tag is None:
        return None
    gbody = ag.get("body") or []
    # anti-facade: `result.add(<tgt>)` with `tgt = s.get("<target_key>", "")`, gated by
    # a `self._rhs_yields_map(s.get("<value_key>", {}))` predicate. Recover the acc name
    # and the added var directly from the `<acc>.add(<var>)` call.
    found_add = _cmtl_find_add_var(gbody)
    if found_add is None:
        return None
    add_var, acc_name = found_add
    target_key = _spat_find_binding_key(gbody, add_var, sv)
    if target_key is None:
        return None
    # the value passed to `_rhs_yields_map` must come from `s.get("<value_key>", {})`
    rhs_call = _find_call_by_suffix(gbody, "_rhs_yields_map")
    if rhs_call is None:
        return None
    rargs = rhs_call.get("args") or []
    value_key = _frss_dotget_key(rargs[0], sv) if rargs else None
    if value_key is None:
        return None
    # recursion keys must be present (fail-closed on a wholesale walk mutation); the
    # lifted `walk` self-call name must appear (a real recursive descent, not a stub).
    strings = set(_all_strings(fb))
    if not {"body", "orelse", "handlers"}.issubset(strings):
        return None
    if _find_self_call_name(fb, "") is None and not call_names:
        return None
    return {"stmt_key": stmt_key, "assign_tag": assign_tag, "target_key": target_key,
            "value_key": value_key, "acc": acc_name,
            "body_key": "body", "orelse_key": "orelse", "handlers_key": "handlers"}


def _cmtl_find_add_var(node: Any) -> Optional["Tuple[str, str]"]:
    """First `<acc>.add(<Var>)` anywhere in `node` -> (var_name, acc_name), else None."""
    if isinstance(node, dict):
        f = node.get("func")
        if (node.get("type") == "Call" and isinstance(f, str) and f.endswith(".add")):
            a = node.get("args") or []
            if len(a) == 1 and isinstance(a[0], dict) and a[0].get("type") == "Var":
                return (a[0].get("name"), f[:-len(".add")])
        for v in node.values():
            r = _cmtl_find_add_var(v)
            if r:
                return r
    elif isinstance(node, list):
        for x in node:
            r = _cmtl_find_add_var(x)
            if r:
                return r
    return None


def _find_call_by_suffix(node: Any, suffix: str) -> Optional[Dict[str, Any]]:
    """First Call node whose `func` string ends with `suffix`, else None."""
    if isinstance(node, dict):
        f = node.get("func")
        if node.get("type") == "Call" and isinstance(f, str) and f.endswith(suffix):
            return node
        for v in node.values():
            r = _find_call_by_suffix(v, suffix)
            if r:
                return r
    elif isinstance(node, list):
        for x in node:
            r = _find_call_by_suffix(x, suffix)
            if r:
                return r
    return None


def recognize_collect_map_typed_locals_pairs(functions: List[Dict[str, Any]]
                                             ) -> Dict[str, Any]:
    """Pair the `_collect_map_typed_locals` OUTER wrapper with its lifted `walk`
    sibling (by adjacency). Returns {"outer_ids": {id(outer): desc}, "walk_ids":
    {id(walk), ...}}. Never raises."""
    outer_ids: Dict[int, Dict[str, Any]] = {}
    walk_ids = set()
    try:
        n = len(functions)
        for i, f in enumerate(functions):
            if not isinstance(f, dict):
                continue
            try:
                od = _recognize_cmtl_outer(f)
            except Exception:
                od = None
            if od is None:
                continue
            if i + 1 >= n:
                continue
            wf = functions[i + 1]
            wn = od["walker_name"]
            wf_name = wf.get("name") if isinstance(wf, dict) else None
            if not (isinstance(wf, dict) and isinstance(wf_name, str)
                    and (wf_name == wn or wf_name.endswith("__" + wn))):
                continue
            if id(wf) in walk_ids:
                continue
            try:
                leaf = _recognize_cmtl_walk(wf, {wn, wf_name})
            except Exception:
                leaf = None
            if leaf is None:
                continue
            desc = {"name": od["name"], "param": od["param"],
                    "self_type": od["self_type"]}
            desc.update(leaf)
            outer_ids[id(f)] = desc
            walk_ids.add(id(wf))
    except Exception:
        return {"outer_ids": {}, "walk_ids": set()}
    return {"outer_ids": outer_ids, "walk_ids": walk_ids}


def emit_collect_map_typed_locals_group(func: Dict[str, Any], desc: Dict[str, Any],
                                        whyml_ident) -> List[str]:
    """Emit `_collect_map_typed_locals` as a REF-accumulator (map string bool) set-collect
    over the pyval stmt list: the REAL `target` string is read off the pydict (mutation-
    sensitive) and `set_add`-ed under the `_rhs_yields_map(value)` gate (the only opaque-but-
    sound `val <n>__rhsmap (v:pyval):bool`). Body/orelse/handler recursion reuses the split
    search+project `pget`-shape list readers with the `size_list`/`size_dict` termination
    pins. `ensures True`; ledger 3 (no new type/axiom/cert)."""
    n = whyml_ident(desc["name"])
    P = f"{n}__"
    mv = _pvw_mv(desc["param"])
    st = desc.get("self_type")
    self_type = whyml_ident(st.lower()) if st else "autotrustmixin"
    at = desc["assign_tag"]
    acc_ty = "ref (map string bool)"
    out: List[str] = []
    # opaque map-yielding-RHS over-approximation (sound under ensures-True; input-dependent)
    out.append(f"  val {P}rhsmap (v: pyval) : bool")
    # literal-key readers (typed irkey ctor or K_dyn guard, reflected per key)
    out += _emit_skey_reader(f"{P}gstmt", desc["stmt_key"])   # "stmt" (K_dyn)
    out += _emit_skey_reader(f"{P}gtgt", desc["target_key"])  # "target" (K_target)
    out += _emit_pval_reader(f"{P}gval", desc["value_key"])   # "value" (K_value)

    def _list_reader(rname: str, key: str) -> None:
        gname = f"{rname}_g"
        ctor = _irkey_ctor(key)
        out.append(f"  let rec {gname} (d: pydict) : option pyval")
        out.append("    variant { d }")
        out.append("    ensures { match result with Some v -> pv_size v <= size_dict d | None -> true end }")
        out.append("  = match d with")
        out.append("    | DNil -> None")
        if ctor.startswith("(K_dyn"):
            out.append(f'    | DCons (K_dyn s) v rest -> if pystr_eq s "{key}" then Some v else {gname} rest')
        else:
            out.append(f"    | DCons {ctor} v _ -> Some v")
        out.append(f"    | DCons _ _ rest -> {gname} rest")
        out.append("    end")
        out.append(f"  let {rname} (d: pydict) : list pyval")
        out.append("    ensures { size_list result <= size_dict d }")
        out.append(f"  = match {gname} d with Some (PList xs) -> xs | _ -> Nil end")

    _list_reader(f"{P}Lbody", desc["body_key"])
    _list_reader(f"{P}Lorelse", desc["orelse_key"])
    _list_reader(f"{P}Lhandlers", desc["handlers_key"])
    # main mutual fold + handler-list sub-fold on the SHARED acc
    out.append(f"  let rec {P}f (items: list pyval) (acc: {acc_ty}) : unit")
    out.append("    requires { true } ensures { true } writes { acc } variant { size_list items }")
    out.append("  = match items with")
    out.append("    | Nil -> ()")
    out.append("    | Cons s rest ->")
    out.append("        (match s with")
    out.append("         | PDict d ->")
    out.append(f'             (match {P}gstmt d with')
    out.append(f'              | Some tag -> if pystr_eq tag "{at}" then')
    out.append(f"                  (match {P}gtgt d with")
    out.append("                   | Some t ->")
    out.append(f"                       (match {P}gval d with")
    out.append(f"                        | Some vv -> if {P}rhsmap vv then acc := set_add !acc t else ()")
    out.append("                        | None -> () end)")
    out.append("                   | None -> () end)")
    out.append("                else ()")
    out.append("              | None -> () end);")
    out.append(f"             {P}f ({P}Lbody d) acc;")
    out.append(f"             {P}f ({P}Lorelse d) acc;")
    out.append(f"             {P}hf ({P}Lhandlers d) acc")
    out.append("         | _ -> () end);")
    out.append(f"        {P}f rest acc")
    out.append("    end")
    out.append(f"  with {P}hf (hs: list pyval) (acc: {acc_ty}) : unit")
    out.append("    requires { true } ensures { true } writes { acc } variant { size_list hs }")
    out.append("  = match hs with Nil -> ()")
    out.append(f'    | Cons h rest -> (match h with PDict hd -> {P}f ({P}Lbody hd) acc | _ -> () end); {P}hf rest acc end')
    # entry: self ignored (the collect is a pure structural pre-pass); fold the PARAM
    # stmt list (a real PList) directly.
    out.append(f"  let {n} (self: {self_type}) ({mv}: pyval) : map string bool")
    out.append("    requires { true } ensures { true }")
    out.append("  = let acc = ref (const false) in")
    out.append(f"    (match {mv} with PList xs -> {P}f xs acc | _ -> () end);")
    out.append("    !acc")
    return out


# ---- `_has_set_op_on_map` (auto_trust.py, recursive bool-existence predicate over pyval):
#      the OUTER wrapper (map-typed-value-in-int-context detector) + its lifted `yields_map`
#      sibling (`(node.get("type")=="Var" and node.get("name") in map_locals) or
#      self._rhs_yields_map(node)`). Three flag-branches over a real PDict:
#        - BinOp set-op (`op in ("|","&","^","-")`) with a `yields_map` operand,
#        - `stmt == "For"` with a `yields_map` iter,
#        - `stmt == "If"` with a `_test_contains_map(test, map_locals)` truthiness,
#      then a GENERIC descent over the dict values / list items. Emitted as the certified
#      mutual bool-fold skeleton (walk/dfold/lfold over pyval/pydict/list; variants
#      pv_size/size_dict/size_list — the `_test_contains_map` device). Non-vacuous: the
#      `yields_map` operand check is REAL `map_locals nm` map application over the real
#      `left`/`right`/`iter` node read off the pydict; only `_rhs_yields_map` (`<n>__rhsmap`)
#      and the already-verified but textually-LATER (forward-ref) `_test_contains_map`
#      (`<n>__tcm`) are opaque `val`s. The lifted `yields_map` is SUPPRESSED. Keyed on `id`;
#      corpus-inert (name-gated). Ledger 3 (no new type/axiom/cert).

def _recognize_hsom_ym(ymfunc: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    """Match the lifted `yields_map(node)` sibling and extract its discriminant literals.
    Fail-closed. Returns {var_tag, type_key, name_key} or None."""
    params = ymfunc.get("formal_params") or []
    if len(params) != 1:
        return None
    node_p = params[0]
    body = ymfunc.get("body") or []
    if len(body) != 2:
        return None
    guard, ret = body
    # guard: if (isinstance(node,dict) and node.get("type")=="Var") and node.get("name") in map_locals: return True
    if not (isinstance(guard, dict) and guard.get("stmt") == "If"):
        return None
    t = guard.get("test") or {}
    if not (isinstance(t, dict) and t.get("type") == "BinOp" and t.get("op") == "and"):
        return None
    left = t.get("left") or {}
    right = t.get("right") or {}
    # left: isinstance(node,dict) and node.get("type") == "<var_tag>"
    if not (isinstance(left, dict) and left.get("type") == "BinOp" and left.get("op") == "and"):
        return None
    if not _match_isinstance(left.get("left"), node_p, "dict"):
        return None
    tycmp = left.get("right") or {}
    if not (isinstance(tycmp, dict) and tycmp.get("type") == "BinOp" and tycmp.get("op") == "=="):
        return None
    type_key = _frss_dotget_key(tycmp.get("left"), node_p)
    var_tag = _clean_lit(_is_string(tycmp.get("right")))
    if type_key is None or var_tag is None:
        return None
    # right: node.get("<name_key>") in map_locals
    if not (isinstance(right, dict) and right.get("type") == "BinOp" and right.get("op") == "in"):
        return None
    name_key = _frss_dotget_key(right.get("left"), node_p)
    if name_key is None:
        return None
    # ret: return self._rhs_yields_map(node)
    if _find_call_by_suffix(ret, "_rhs_yields_map") is None:
        return None
    return {"var_tag": var_tag, "type_key": type_key, "name_key": name_key}


def _recognize_hsom_outer(func: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    """Match the OUTER `_has_set_op_on_map`. Fail-closed. Returns
    {name, self_type, obj_param, stmt_key, binop_tag, set_ops, op_key, for_tag, if_tag,
     type_key, iter_key, test_key, left_key, right_key, ym_call}."""
    if not func.get("name", "").endswith("_has_set_op_on_map"):
        return None
    if func.get("return_annotation") != "bool":
        return None
    params = func.get("formal_params") or []
    if len(params) != 2:
        return None
    obj_p = params[0]
    body = func.get("body") or []
    # locate the isinstance(obj, dict) If (the dict-branch carrying the three flags)
    dict_if = None
    for s in body:
        if (isinstance(s, dict) and s.get("stmt") == "If"
                and _match_isinstance(s.get("test"), obj_p, "dict")):
            dict_if = s
            break
    if dict_if is None:
        return None
    dbody = dict_if.get("body") or []
    # set-op tuple: a `BinOp op="in"` whose left is `<obj>.get("<op_key>")` and right a
    # Tuple of string literals.
    inn = _hsom_find_setop_in(dbody, obj_p)
    if inn is None:
        return None
    op_key, set_ops = inn
    if not set_ops:
        return None
    # the BinOp tag: `<t> == "<binop_tag>"` — the sibling of the op-in test under `and`.
    binop_tag = _hsom_find_binop_tag(dbody)
    if binop_tag is None:
        return None
    # stmt-keyed For / If tags
    stmt_hits = _hsom_stmt_tags(dbody, obj_p)
    for_tag = stmt_hits.get("For")
    if_tag = stmt_hits.get("If")
    stmt_key = stmt_hits.get("_key")
    if not (for_tag and if_tag and stmt_key):
        return None
    # anti-facade: the truthiness branch calls `_test_contains_map`; operands go through
    # `yields_map`; and the descent self-calls `_has_set_op_on_map`.
    if _find_call_by_suffix(dbody, "_test_contains_map") is None:
        return None
    ym_call = _hsom_find_ym_call(dbody)
    if ym_call is None:
        return None
    if _find_self_call_name(body, "_has_set_op_on_map") is None:
        return None
    return {"name": func.get("name"), "self_type": func.get("self_type"),
            "obj_param": obj_p, "stmt_key": stmt_key, "binop_tag": binop_tag,
            "set_ops": set_ops, "op_key": op_key, "for_tag": for_tag, "if_tag": if_tag,
            "type_key": "type", "iter_key": "iter", "test_key": "test",
            "left_key": "left", "right_key": "right", "ym_call": ym_call}


def _hsom_find_setop_in(node: Any, obj_p: str) -> Optional["Tuple[str, List[str]]"]:
    """First `<obj>.get("<op_key>") in (<str-tuple>)` -> (op_key, [ops]), else None."""
    if isinstance(node, dict):
        if (node.get("type") == "BinOp" and node.get("op") == "in"):
            op_key = _frss_dotget_key(node.get("left"), obj_p)
            tags = _tcm_str_elts(node.get("right"))
            if op_key is not None and tags:
                return (op_key, tags)
        for v in node.values():
            r = _hsom_find_setop_in(v, obj_p)
            if r:
                return r
    elif isinstance(node, list):
        for x in node:
            r = _hsom_find_setop_in(x, obj_p)
            if r:
                return r
    return None


def _hsom_find_binop_tag(node: Any) -> Optional[str]:
    """First `<Var> == "<tag>"` whose Var name is a plain local (the `t` binding) whose
    literal is not a stmt/collection key -> the tag. Here we simply take the literal from
    the `and`-guard sibling of the op-in test: `t == "BinOp"`. Returns the string tag."""
    if isinstance(node, dict):
        if (node.get("type") == "BinOp" and node.get("op") == "and"):
            left = node.get("left") or {}
            right = node.get("right") or {}
            # right is the op-in test; left is `<Var> == "<tag>"`
            if (isinstance(right, dict) and right.get("type") == "BinOp"
                    and right.get("op") == "in"
                    and isinstance(left, dict) and left.get("type") == "BinOp"
                    and left.get("op") == "=="
                    and isinstance(left.get("left"), dict)
                    and left.get("left", {}).get("type") == "Var"):
                tag = _clean_lit(_is_string(left.get("right")))
                if tag is not None:
                    return tag
        for v in node.values():
            r = _hsom_find_binop_tag(v)
            if r:
                return r
    elif isinstance(node, list):
        for x in node:
            r = _hsom_find_binop_tag(x)
            if r:
                return r
    return None


def _hsom_stmt_tags(node: Any, obj_p: str) -> Dict[str, str]:
    """Collect `<obj>.get("<stmt_key>") == "<tag>"` comparisons -> {tag: tag, "_key": key}."""
    out: Dict[str, str] = {}

    def rec(nd: Any) -> None:
        if isinstance(nd, dict):
            if (nd.get("type") == "BinOp" and nd.get("op") == "=="):
                k = _frss_dotget_key(nd.get("left"), obj_p)
                tag = _clean_lit(_is_string(nd.get("right")))
                if k is not None and tag is not None:
                    out[tag] = tag
                    out["_key"] = k
            for v in nd.values():
                rec(v)
        elif isinstance(nd, list):
            for x in nd:
                rec(x)

    rec(node)
    return out


def _hsom_find_ym_call(node: Any) -> Optional[str]:
    """First bare (non-dotted) Call other than the pydict readers / builtins whose arg is
    an `<obj>.get(...)` — the lifted `yields_map` call. Returns its func name, else None."""
    if isinstance(node, dict):
        f = node.get("func")
        if (node.get("type") == "Call" and isinstance(f, str) and "." not in f
                and f not in ("set", "len", "isinstance", "str")):
            args = node.get("args") or []
            if args and isinstance(args[0], dict) and args[0].get("type") == "Call" \
                    and isinstance(args[0].get("func"), str) and args[0]["func"].endswith(".get"):
                return f
        for v in node.values():
            r = _hsom_find_ym_call(v)
            if r:
                return r
    elif isinstance(node, list):
        for x in node:
            r = _hsom_find_ym_call(x)
            if r:
                return r
    return None


def recognize_has_set_op_on_map_pairs(functions: List[Dict[str, Any]]
                                      ) -> Dict[str, Any]:
    """Pair the `_has_set_op_on_map` OUTER wrapper with its lifted `yields_map` sibling
    (by adjacency). Returns {"outer_ids": {id(outer): desc}, "walk_ids": {id(ym), ...}}.
    Never raises."""
    outer_ids: Dict[int, Dict[str, Any]] = {}
    walk_ids = set()
    try:
        n = len(functions)
        for i, f in enumerate(functions):
            if not isinstance(f, dict):
                continue
            try:
                od = _recognize_hsom_outer(f)
            except Exception:
                od = None
            if od is None:
                continue
            if i + 1 >= n:
                continue
            wf = functions[i + 1]
            wn = od["ym_call"]
            wf_name = wf.get("name") if isinstance(wf, dict) else None
            if not (isinstance(wf, dict) and isinstance(wf_name, str)
                    and (wf_name == wn or wf_name.endswith("__" + wn))):
                continue
            if id(wf) in walk_ids:
                continue
            try:
                ymd = _recognize_hsom_ym(wf)
            except Exception:
                ymd = None
            if ymd is None:
                continue
            desc = dict(od)
            desc.update(ymd)
            outer_ids[id(f)] = desc
            walk_ids.add(id(wf))
    except Exception:
        return {"outer_ids": {}, "walk_ids": set()}
    return {"outer_ids": outer_ids, "walk_ids": walk_ids}


def emit_has_set_op_on_map_group(func: Dict[str, Any], desc: Dict[str, Any],
                                 whyml_ident) -> List[str]:
    """Emit `_has_set_op_on_map` as the certified mutual bool-existence fold over the
    pyval/pydict/list ADT (variants pv_size/size_dict/size_list). The set-op / for-iter
    flag-branches read the REAL `left`/`right`/`iter` node off the pydict and test it with
    `<n>__ym` (real `map_locals nm` map application over the real `Var` name); only
    `_rhs_yields_map` (`<n>__rhsmap`) and the textually-LATER already-verified sibling
    `_test_contains_map` (`<n>__tcm`, opaque to avoid a forward reference) are opaque `val`s.
    `ensures True`; ledger 3 (no new type/axiom/cert)."""
    n = whyml_ident(desc["name"])
    P = f"{n}__"
    ml = "map string bool"
    setops = desc["set_ops"]
    out: List[str] = []
    # opaque cross-mixin predicates (sound over-approx; input-dependent, non-facade)
    out.append(f"  val {P}rhsmap (v: pyval) : bool")
    out.append(f"  val {P}tcm (self: autotrustmixin) (e: pyval) (ml: {ml}) : bool")
    # literal-key readers
    out += _emit_skey_reader(f"{P}gtype", desc["type_key"])   # "type" (K_type)
    out += _emit_skey_reader(f"{P}gname", desc["name_key"])   # "name" (K_name)
    out += _emit_skey_reader(f"{P}gstmt", desc["stmt_key"])   # "stmt" (K_dyn)
    out += _emit_skey_reader(f"{P}gop", desc["op_key"])       # "op" (K_op)
    out += _emit_pval_reader(f"{P}gleft", desc["left_key"])   # "left" (K_left)
    out += _emit_pval_reader(f"{P}gright", desc["right_key"]) # "right" (K_right)
    out += _emit_pval_reader(f"{P}giter", desc["iter_key"])   # "iter" (K_dyn)
    out += _emit_pval_reader(f"{P}gtest", desc["test_key"])   # "test" (K_dyn)
    # yields_map helper (non-recursive): (isVar && name in map_locals) || _rhs_yields_map(node)
    out.append(f"  let {P}ym (self: autotrustmixin) (node: pyval) (map_locals: {ml}) : bool")
    out.append("    requires { true } ensures { true }")
    out.append("  = (match node with")
    out.append("     | PDict d ->")
    out.append(f'         (match {P}gtype d with Some t -> pystr_eq t "{desc["var_tag"]}" | None -> false end)')
    out.append(f"         && (match {P}gname d with Some nm -> map_locals nm | None -> false end)")
    out.append("     | _ -> false end)")
    out.append(f"    || {P}rhsmap node")
    # main mutual bool fold
    set_or = " || ".join(f'pystr_eq op "{o}"' for o in setops)
    out.append(f"  let rec {n} (self: autotrustmixin) (obj: pyval) (map_locals: {ml}) : bool")
    out.append("    requires { true } ensures { true } variant { pv_size obj }")
    out.append("  = match obj with")
    out.append("    | PDict d ->")
    out.append(f'        let binhit = (match {P}gtype d with Some t -> pystr_eq t "{desc["binop_tag"]}" | None -> false end)')
    out.append(f"                     && (match {P}gop d with Some op -> ({set_or}) | None -> false end)")
    out.append(f"                     && ((match {P}gleft d with Some v -> {P}ym self v map_locals | None -> false end)")
    out.append(f"                         || (match {P}gright d with Some v -> {P}ym self v map_locals | None -> false end)) in")
    out.append(f'        let forhit = (match {P}gstmt d with Some st -> pystr_eq st "{desc["for_tag"]}" | None -> false end)')
    out.append(f"                     && (match {P}giter d with Some v -> {P}ym self v map_locals | None -> false end) in")
    out.append(f'        let ifhit = (match {P}gstmt d with Some st -> pystr_eq st "{desc["if_tag"]}" | None -> false end)')
    out.append(f"                     && (match {P}gtest d with Some v -> {P}tcm self v map_locals | None -> false end) in")
    out.append("        if binhit || forhit || ifhit then true")
    out.append(f"        else {P}dfold self d map_locals")
    out.append(f"    | PList xs -> {P}lfold self xs map_locals")
    out.append("    | _ -> false")
    out.append("    end")
    out.append(f"  with {P}dfold (self: autotrustmixin) (d: pydict) (map_locals: {ml}) : bool")
    out.append("    requires { true } ensures { true } variant { size_dict d }")
    out.append("  = match d with DNil -> false")
    out.append("    | DCons _ v rest ->")
    out.append("        size_pos v;")
    out.append(f"        (match v with PDict _ -> {n} self v map_locals | PList xs -> {P}lfold self xs map_locals | _ -> false end)")
    out.append(f"        || {P}dfold self rest map_locals end")
    out.append(f"  with {P}lfold (self: autotrustmixin) (xs: list pyval) (map_locals: {ml}) : bool")
    out.append("    requires { true } ensures { true } variant { size_list xs }")
    out.append("  = match xs with Nil -> false")
    out.append(f"    | Cons h t -> {n} self h map_locals || {P}lfold self t map_locals end")
    return out


# ---- `_is_linear_vc`: `all(_is_linear_expr(e) for e in ensures ++ requires)` -------------
# `all` distributes over concatenation, so the two-list `list(a or []) + list(b or [])` reduces
# to `fold(a) && fold(b)` — NO list-append needed. `_is_linear_expr` (trusted: nested-closure
# boundary) is an opaque pyval->bool over-approximation. Non-vacuous, coupling-safe (bool ret).

def recognize_is_linear_vc(func: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    """Fail-closed match of `_is_linear_vc`. Never raises."""
    try:
        return _recognize_is_linear_vc(func)
    except Exception:
        return None


def _recognize_is_linear_vc(func: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    if not func.get("name", "").endswith("_is_linear_vc"):
        return None
    if func.get("return_annotation") != "bool":
        return None
    params = func.get("formal_params") or []
    if len(params) != 2:
        return None
    a, b = params
    body = func.get("body") or []
    if len(body) != 2:
        return None
    asn = body[0]
    if not (isinstance(asn, dict) and asn.get("stmt") == "Assign"):
        return None
    val = asn.get("value") or {}
    if not (val.get("type") == "BinOp" and val.get("op") == "+"):
        return None

    def _list_or_var(node: Any) -> Optional[str]:
        # `list(<var> or [])` -> <var>
        if not (isinstance(node, dict) and node.get("type") == "Call"
                and node.get("func") == "list"):
            return None
        arg = (node.get("args") or [None])[0] or {}
        if not (isinstance(arg, dict) and arg.get("type") == "BinOp" and arg.get("op") == "or"):
            return None
        return _get_str(arg.get("left"), "name")

    if _list_or_var(val.get("left")) != a or _list_or_var(val.get("right")) != b:
        return None
    ret = body[1]
    if not (isinstance(ret, dict) and ret.get("stmt") == "Return"):
        return None
    call = ret.get("value") or {}
    if not (call.get("type") == "Call" and call.get("func") == "all"):
        return None
    gen = (call.get("args") or [None])[0] or {}
    if not (isinstance(gen, dict) and gen.get("type") == "GenExp"):
        return None
    pred = _get_str(gen.get("elt"), "func")
    if not pred:
        return None
    return {"name": func["name"], "a": a, "b": b, "pred": pred}


def emit_is_linear_vc_group(desc: Dict[str, Any], whyml_ident) -> List[str]:
    """Emit `_is_linear_vc` as `fold(ensures) && fold(requires)` over an opaque pyval->bool
    predicate (`_is_linear_expr`, trusted nested-closure boundary). `all` distributes over the
    `++` so no list-append is needed. Terminates on size_list. `ensures True`. Ledger 3."""
    n = whyml_ident(desc["name"])
    out: List[str] = []
    out.append(f"  val {n}__pred (e: pyval) : bool")
    out.append(f"  let rec {n}__fold (xs: list pyval) : bool")
    out.append("    requires { true } ensures { true } variant { size_list xs }")
    out.append(f"  = match xs with Nil -> true | Cons h t -> {n}__pred h && {n}__fold t end")
    out.append(f"  let {n} (ensures_exprs: list pyval) (requires_exprs: list pyval) : bool")
    out.append("    requires { true } ensures { true }")
    out.append(f"  = {n}__fold ensures_exprs && {n}__fold requires_exprs")
    return out


# ---- `_is_linear_expr` (auto_trust.py): the nested `def _check(e)` linear-arithmetic ------
#      classifier + its `return _check(expr)` staticmethod wrapper. The lifted `_check`
#      sibling (adjacency i+1) is SUPPRESSED; the wrapper emits ONE self-contained
#      recursive bool catamorphism over the certified pyval/pydict ADT. Every discriminant
#      is REFLECTED from the real body (const-tag set, var-tag set, arith-op set, `*`, the
#      unary-op set, the Old-tag set, and the `type`/`value`/`n`/`op`/`left`/`right`/`expr`/
#      `operand` keys) so a body change moves the emit (mutation-sensitive). Non-vacuous:
#      the fold descends REAL child dicts read off the pydict with the size-bounded readers
#      (termination via `pv_size`); the `op == "*"` const-detection branch reads the REAL
#      `type` off the real `left`/`right` child (wrinkle #2 — a genuine typed-node
#      projection, not an opaque gate). `ensures True`; ledger 3 (no new type/axiom/cert).

def _ile_membership(test: Any, var: str) -> Optional[List[str]]:
    """`<var> in (S...)` -> [S...] or `<var> == "S"` -> ["S"]. Fail-closed None."""
    if not isinstance(test, dict) or test.get("type") != "BinOp":
        return None
    if not _is_var(test.get("left"), var):
        return None
    op = test.get("op")
    if op == "in":
        tags = _tcm_str_elts(test.get("right"))
        return [t for t in tags] if tags else None
    if op == "==":
        s = _clean_lit(_is_string(test.get("right")))
        return [s] if s is not None else None
    return None


def _recognize_ile_check(func: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    """Match the lifted `_check(e)` linear-arith classifier body and extract every
    discriminant literal / dict key. Fail-closed; None on any deviation."""
    if func.get("return_annotation") != "bool":
        return None
    params = func.get("formal_params") or []
    if len(params) != 1:
        return None
    e = params[0]
    body = func.get("body") or []
    if len(body) != 9:
        return None
    # [0] if e is None: return True   [1] if not isinstance(e, dict): return True
    if not all(isinstance(body[i], dict) and body[i].get("stmt") == "If" for i in (0, 1)):
        return None
    # [2] t = e.get("<type_key>", "")
    b2 = body[2]
    if not (isinstance(b2, dict) and b2.get("stmt") == "Assign"):
        return None
    t_var = b2.get("target")
    type_key = _frss_dotget_key(b2.get("value"), e)
    if not (isinstance(t_var, str) and type_key):
        return None
    # [3] if t in (<const_tags>): val = e.get("<value_key>", e.get("<n_key>", 0)); return isinstance(...)
    b3 = body[3]
    const_tags = _ile_membership(b3.get("test") if isinstance(b3, dict) else None, t_var)
    if not const_tags:
        return None
    gb3 = b3.get("body") or []
    if not (gb3 and isinstance(gb3[0], dict) and gb3[0].get("stmt") == "Assign"):
        return None
    av = gb3[0].get("value") or {}
    value_key = _frss_dotget_key(av, e)
    n_default = (av.get("args") or [None, None])[1]
    n_key = _frss_dotget_key(n_default, e)
    if not (value_key and n_key):
        return None
    # [4] if t in (<var_tags>): return True
    b4 = body[4]
    var_tags = _ile_membership(b4.get("test") if isinstance(b4, dict) else None, t_var)
    if not var_tags:
        return None
    # [5] if t == "<binop_tag>": op = e.get(..); left = e.get(..); right = e.get(..); ...
    b5 = body[5]
    bt = _ile_membership(b5.get("test") if isinstance(b5, dict) else None, t_var)
    if not (bt and len(bt) == 1):
        return None
    binop_tag = bt[0]
    gb5 = b5.get("body") or []
    if len(gb5) < 5:
        return None
    op_key = _frss_dotget_key(gb5[0].get("value") if isinstance(gb5[0], dict) else None, e)
    op_var = gb5[0].get("target") if isinstance(gb5[0], dict) else None
    left_key = _frss_dotget_key(gb5[1].get("value") if isinstance(gb5[1], dict) else None, e)
    left_var = gb5[1].get("target") if isinstance(gb5[1], dict) else None
    right_key = _frss_dotget_key(gb5[2].get("value") if isinstance(gb5[2], dict) else None, e)
    right_var = gb5[2].get("target") if isinstance(gb5[2], dict) else None
    if not (op_key and op_var and left_key and left_var and right_key and right_var):
        return None
    arith_ops = _ile_membership(gb5[3].get("test") if isinstance(gb5[3], dict) else None, op_var)
    if not arith_ops:
        return None
    # mult If: `op == "<mult_op>"`; body[0] Assign _CONST = (<const_tags2>)
    mif = gb5[4]
    mt = _ile_membership(mif.get("test") if isinstance(mif, dict) else None, op_var)
    if not (mt and len(mt) == 1):
        return None
    mult_op = mt[0]
    mbody = mif.get("body") or []
    if not (mbody and isinstance(mbody[0], dict) and mbody[0].get("stmt") == "Assign"):
        return None
    const_tags2 = _tcm_str_elts(mbody[0].get("value"))
    if not const_tags2:
        return None
    # [6] if t == "<unaryop_tag>": op = e.get(..); if op in (<unary_ops>): return _check(e.get(expr) or e.get(operand))
    b6 = body[6]
    ut = _ile_membership(b6.get("test") if isinstance(b6, dict) else None, t_var)
    if not (ut and len(ut) == 1):
        return None
    unaryop_tag = ut[0]
    gb6 = b6.get("body") or []
    if len(gb6) < 2:
        return None
    uop_var = gb6[0].get("target") if isinstance(gb6[0], dict) else None
    uif = gb6[1]
    unary_ops = _ile_membership(uif.get("test") if isinstance(uif, dict) else None, uop_var)
    if not unary_ops:
        return None
    uret = (uif.get("body") or [None])[0]
    ucall = uret.get("value") if isinstance(uret, dict) else None
    uor = (ucall.get("args") or [None])[0] if isinstance(ucall, dict) else None
    if not (isinstance(uor, dict) and uor.get("type") == "BinOp" and uor.get("op") == "or"):
        return None
    expr_key = _frss_dotget_key(uor.get("left"), e)
    operand_key = _frss_dotget_key(uor.get("right"), e)
    if not (expr_key and operand_key):
        return None
    # [7] if t in (<old_tags>): return _check(e.get("<old_key>"))
    b7 = body[7]
    old_tags = _ile_membership(b7.get("test") if isinstance(b7, dict) else None, t_var)
    if not old_tags:
        return None
    oret = (b7.get("body") or [None])[0]
    ocall = oret.get("value") if isinstance(oret, dict) else None
    oarg = (ocall.get("args") or [None])[0] if isinstance(ocall, dict) else None
    old_key = _frss_dotget_key(oarg, e)
    if not old_key:
        return None
    return {"e": e, "type_key": type_key, "const_tags": const_tags,
            "value_key": value_key, "n_key": n_key, "var_tags": var_tags,
            "binop_tag": binop_tag, "op_key": op_key, "left_key": left_key,
            "right_key": right_key, "arith_ops": arith_ops, "mult_op": mult_op,
            "const_tags2": const_tags2, "unaryop_tag": unaryop_tag,
            "unary_ops": unary_ops, "expr_key": expr_key, "operand_key": operand_key,
            "old_tags": old_tags, "old_key": old_key}


def _recognize_ile_outer(func: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    """Match the `_is_linear_expr(expr)` wrapper `return _check(expr)`. Fail-closed.
    Returns {name, expr, check_name}."""
    if not func.get("name", "").endswith("_is_linear_expr"):
        return None
    if func.get("return_annotation") != "bool":
        return None
    params = func.get("formal_params") or []
    if len(params) != 1:
        return None
    expr_p = params[0]
    body = func.get("body") or []
    if len(body) != 1:
        return None
    ret = body[0]
    if not (isinstance(ret, dict) and ret.get("stmt") == "Return"):
        return None
    call = ret.get("value") or {}
    if not (isinstance(call, dict) and call.get("type") == "Call"
            and isinstance(call.get("func"), str)):
        return None
    cargs = call.get("args") or []
    if not (len(cargs) == 1 and _is_var(cargs[0], expr_p)):
        return None
    return {"name": func["name"], "expr": expr_p, "check_name": call["func"]}


def recognize_is_linear_expr_pairs(functions: List[Dict[str, Any]]) -> Dict[str, Any]:
    """Pair the `_is_linear_expr` wrapper with its lifted `_check` sibling (adjacency).
    Returns {"outer_ids": {id(outer): desc}, "walk_ids": {id(check), ...}}. Never raises."""
    outer_ids: Dict[int, Dict[str, Any]] = {}
    walk_ids = set()
    try:
        n = len(functions)
        for i, f in enumerate(functions):
            if not isinstance(f, dict):
                continue
            try:
                od = _recognize_ile_outer(f)
            except Exception:
                od = None
            if od is None or i + 1 >= n:
                continue
            cf = functions[i + 1]
            cn = od["check_name"]
            cf_name = cf.get("name") if isinstance(cf, dict) else None
            if not (isinstance(cf, dict) and isinstance(cf_name, str)
                    and (cf_name == cn or cf_name.endswith("__" + cn))):
                continue
            if id(cf) in walk_ids:
                continue
            try:
                chk = _recognize_ile_check(cf)
            except Exception:
                chk = None
            if chk is None:
                continue
            desc = {"name": od["name"], "expr": od["expr"]}
            desc.update(chk)
            outer_ids[id(f)] = desc
            walk_ids.add(id(cf))
    except Exception:
        return {"outer_ids": {}, "walk_ids": set()}
    return {"outer_ids": outer_ids, "walk_ids": walk_ids}


def _ile_num_check(reader_v: str) -> str:
    """`isinstance(<val>,(int,float,bool))` faithfully: PInt/PBool are numeric,
    every other pyval constructor is not (the ADT has no float ctor)."""
    return f"(match {reader_v} with PInt _ -> true | PBool _ -> true | _ -> false end)"


def _ile_str_reader(name: str, key: str) -> List[str]:
    """A `pydict -> option string` reader for `key` (typed irkey ctor or K_dyn guard);
    None when the key is absent OR present-but-not-a-PStr (so the caller defaults to "")."""
    ctor = _irkey_ctor(key)
    out = [f"  let rec {name} (d: pydict) : option string",
           "    variant { d }",
           "  = match d with",
           "    | DNil -> None"]
    if key in _NAMED_KEYS:
        out.append(f"    | DCons {ctor} (PStr s) _ -> Some s")
        out.append(f"    | DCons {ctor} _ _ -> None")
    else:
        out.append(f'    | DCons (K_dyn s) v rest -> if pystr_eq s "{key}" then '
                   f"(match v with PStr z -> Some z | _ -> None end) else {name} rest")
    out.append(f"    | DCons _ _ rest -> {name} rest")
    out.append("    end")
    return out


def _ile_pval_reader(name: str, key: str) -> List[str]:
    """A size-bounded `pydict -> option pyval` reader for `key` (child-node projection).
    The `pv_size v <= size_dict d` postcondition feeds the caller's `pv_size` variant."""
    ctor = _irkey_ctor(key)
    out = [f"  let rec {name} (d: pydict) : option pyval",
           "    variant { d }",
           "    ensures { match result with Some v -> pv_size v <= size_dict d | None -> true end }",
           "  = match d with",
           "    | DNil -> None"]
    if key in _NAMED_KEYS:
        out.append(f"    | DCons {ctor} v _ -> Some v")
    else:
        out.append(f'    | DCons (K_dyn s) v rest -> if pystr_eq s "{key}" then Some v else {name} rest')
    out.append(f"    | DCons _ _ rest -> {name} rest")
    out.append("    end")
    return out


def emit_is_linear_expr_group(func: Dict[str, Any], desc: Dict[str, Any],
                              whyml_ident) -> List[str]:
    """Emit `_is_linear_expr` as ONE recursive bool catamorphism over pyval. Every
    discriminant literal + dict key is reflected from `desc` (mutation-sensitive). The
    numeric-const branch reads the real `value`/`n` off the dict and tests the real
    constructor; the `*` branch reads the real `type` off the real `left`/`right` child.
    Terminates on `pv_size` via the size-bounded child readers. `ensures True`; ledger 3."""
    n = whyml_ident(desc["name"])
    C = f"{n}__chk"

    def _members(var: str, tags: List[str]) -> str:
        return "(" + " || ".join(f'pystr_eq {var} "{t}"' for t in tags) + ")"

    out: List[str] = []
    # size-bounded child-node readers (option pyval) + string readers (option string)
    out += _ile_str_reader(f"{C}_gtype", desc["type_key"])
    out += _ile_str_reader(f"{C}_gop", desc["op_key"])
    out += _ile_pval_reader(f"{C}_gvalue", desc["value_key"])
    out += _ile_pval_reader(f"{C}_gn", desc["n_key"])
    out += _ile_pval_reader(f"{C}_gleft", desc["left_key"])
    out += _ile_pval_reader(f"{C}_gright", desc["right_key"])
    out += _ile_pval_reader(f"{C}_gexpr", desc["expr_key"])
    out += _ile_pval_reader(f"{C}_goperand", desc["operand_key"])

    def _const_of(reader: str) -> str:
        # `isinstance(<child>, dict) and <child>.get("type") in _CONST` on a real child
        return (f"(match {reader} with Some (PDict cd) -> "
                f'(match {C}_gtype cd with Some tt -> {_members("tt", desc["const_tags2"])} '
                f"| None -> false end) | _ -> false end)")

    out.append(f"  let rec {C} (e: pyval) : bool")
    out.append("    requires { true } ensures { true } variant { pv_size e }")
    out.append("  = match e with")
    out.append("    | PDict d ->")
    out.append(f'        let t = (match {C}_gtype d with Some s -> s | None -> "" end) in')
    out.append(f"        if {_members('t', desc['const_tags'])} then")
    # numeric const: val = e.get(value, e.get(n, 0)); isinstance(val,(int,float,bool))
    out.append(f"          (match {C}_gvalue d with")
    out.append(f"           | Some vv -> {_ile_num_check('vv')}")
    out.append(f"           | None -> (match {C}_gn d with Some vv -> {_ile_num_check('vv')} | None -> true end) end)")
    out.append(f"        else if {_members('t', desc['var_tags'])} then true")
    out.append(f'        else if pystr_eq t "{desc["binop_tag"]}" then')
    out.append(f'          let op = (match {C}_gop d with Some s -> s | None -> "" end) in')
    out.append(f"          if {_members('op', desc['arith_ops'])} then")
    out.append(f"            (match {C}_gleft d with Some lv -> {C} lv | None -> true end)")
    out.append(f"            && (match {C}_gright d with Some rv -> {C} rv | None -> true end)")
    out.append(f'          else if pystr_eq op "{desc["mult_op"]}" then')
    out.append(f"            let lc = {_const_of(f'{C}_gleft d')} in")
    out.append(f"            let rc = {_const_of(f'{C}_gright d')} in")
    out.append(f"            if lc then (match {C}_gright d with Some rv -> {C} rv | None -> true end)")
    out.append(f"            else if rc then (match {C}_gleft d with Some lv -> {C} lv | None -> true end)")
    out.append("            else false")
    out.append("          else false")
    out.append(f'        else if pystr_eq t "{desc["unaryop_tag"]}" then')
    out.append(f'          let op = (match {C}_gop d with Some s -> s | None -> "" end) in')
    out.append(f"          if {_members('op', desc['unary_ops'])} then")
    out.append(f"            (match {C}_gexpr d with Some v -> {C} v")
    out.append(f"             | None -> (match {C}_goperand d with Some v -> {C} v | None -> true end) end)")
    out.append("          else false")
    out.append(f"        else if {_members('t', desc['old_tags'])} then")
    out.append(f"          (match {C}_gexpr d with Some v -> {C} v | None -> true end)")
    out.append("        else false")
    out.append("    | _ -> true")
    out.append("    end")
    # staticmethod wrapper: `return _check(expr)`
    out.append(f"  let {n} (expr: pyval) : bool")
    out.append("    requires { true } ensures { true }")
    out.append(f"  = {C} expr")
    return out


# ---- `handler_catches`: `h == r or h in bases_closure(r)` ---------------------------------
# Two-string subclass-catch predicate. The `in bases_closure(r)` sub-computation (bases_closure
# is trusted + emits the int-model `map int (option int)`, so a STRING membership can't call it)
# is modelled as an opaque `string->string->bool` over-approximation (input-dependent, non-
# facade). Returns INT (bool-as-int) to preserve the VERIFIED caller `_handle_try_stmt`
# (stmt_control_flow.py) which was compiled against `handler_catches : int`.

def recognize_handler_catches(func: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    """Fail-closed match of `handler_catches`. Never raises."""
    try:
        return _recognize_handler_catches(func)
    except Exception:
        return None


def _recognize_handler_catches(func: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    if not func.get("name", "").endswith("handler_catches"):
        return None
    if func.get("return_annotation") != "bool":
        return None
    params = func.get("formal_params") or []
    if len(params) != 2:
        return None
    h, r = params
    body = func.get("body") or []
    if len(body) != 2:
        return None
    # body[0]: `if h == r: return True`
    eq_if = body[0]
    et = eq_if.get("test") if isinstance(eq_if, dict) else None
    if not (isinstance(et, dict) and et.get("type") == "BinOp" and et.get("op") == "=="
            and _get_str(et.get("left"), "name") == h and _get_str(et.get("right"), "name") == r):
        return None
    # body[1]: `return h in <call>(r)`
    ret = body[1]
    if not (isinstance(ret, dict) and ret.get("stmt") == "Return"):
        return None
    rin = ret.get("value") or {}
    if not (isinstance(rin, dict) and rin.get("type") == "BinOp" and rin.get("op") == "in"
            and _get_str(rin.get("left"), "name") == h):
        return None
    call = rin.get("right") or {}
    if not (isinstance(call, dict) and call.get("type") == "Call"):
        return None
    cargs = call.get("args") or []
    if not (len(cargs) == 1 and _get_str(cargs[0], "name") == r):
        return None
    return {"name": func["name"], "h": h, "r": r}


def emit_handler_catches_group(desc: Dict[str, Any], whyml_ident) -> List[str]:
    """Emit `handler_catches` as `if (h == r || in_closure(h,r)) then 1 else 0` — INT return
    (bool-as-int) to match the verified `_handle_try_stmt` caller. `in_closure` is an opaque
    string->string->bool over-approximation of `h in bases_closure(r)`. `ensures True`. Ledger 3."""
    n = whyml_ident(desc["name"])
    out: List[str] = []
    out.append(f"  val {n}__in_closure (h: string) (r: string) : bool")
    out.append(f"  let {n} (handler_exc: string) (raised_exc: string) : int")
    out.append("    requires { true } ensures { true }")
    out.append(f"  = if (pystr_eq handler_exc raised_exc || {n}__in_closure handler_exc raised_exc) then 1 else 0")
    return out


# ---- `subclasses_of`: `frozenset(c for c in candidates if handler_catches(base, c))` ------
# A set-filter-fold: keep the candidates the (int-returning, already-converted) `handler_catches`
# predicate accepts. Builds a StrSet (`map string bool`); the frozenset dedup IS set_add
# idempotence. Non-vacuous, coupling-safe (no mirror caller).

def recognize_subclasses_of(func: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    """Fail-closed match of `subclasses_of`. Never raises."""
    try:
        return _recognize_subclasses_of(func)
    except Exception:
        return None


def _recognize_subclasses_of(func: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    if not func.get("name", "").endswith("subclasses_of"):
        return None
    if func.get("return_annotation") != "frozenset":
        return None
    params = func.get("formal_params") or []
    if len(params) != 2:
        return None
    base_p, cand_p = params
    body = func.get("body") or []
    if len(body) != 1:
        return None
    ret = body[0]
    if not (isinstance(ret, dict) and ret.get("stmt") == "Return"):
        return None
    call = ret.get("value") or {}
    if not (call.get("type") == "Call" and call.get("func") == "frozenset"):
        return None
    gen = (call.get("args") or [None])[0] or {}
    if not (isinstance(gen, dict) and gen.get("type") == "GenExp"):
        return None
    gens = gen.get("generators") or []
    if len(gens) != 1:
        return None
    g = gens[0]
    eltvar = g.get("target")
    if not eltvar or _get_str(gen.get("elt"), "name") != eltvar:
        return None
    if _get_str(g.get("iter"), "name") != cand_p:
        return None
    ifs = g.get("ifs") or []
    if len(ifs) != 1:
        return None
    pred = ifs[0]
    if not (isinstance(pred, dict) and pred.get("type") == "Call"):
        return None
    predname = pred.get("func")
    pargs = pred.get("args") or []
    if not (predname and len(pargs) == 2
            and _get_str(pargs[0], "name") == base_p
            and _get_str(pargs[1], "name") == eltvar):
        return None
    return {"name": func["name"], "base": base_p, "cand": cand_p, "elt": eltvar, "pred": predname}


def emit_subclasses_of_group(desc: Dict[str, Any], whyml_ident) -> List[str]:
    """Emit `subclasses_of` as a set-filter-fold over `candidates: list string`, keeping each
    `c` for which the int-returning `handler_catches base c <> 0`. Builds `map string bool`
    (StrSet); frozenset dedup = set_add idempotence. Terminates on the list. `ensures True`."""
    n = whyml_ident(desc["name"])
    pred = whyml_ident(desc["pred"])
    out: List[str] = []
    out.append(f"  let rec {n}__fold (base: string) (xs: list string) (acc: map string bool) : map string bool")
    out.append("    requires { true } ensures { true } variant { xs }")
    out.append("  = match xs with Nil -> acc")
    out.append(f"    | Cons c rest -> {n}__fold base rest (if {pred} base c <> 0 then set_add acc c else acc) end")
    out.append(f"  let {n} (base: string) (candidates: list string) : map string bool")
    out.append("    requires { true } ensures { true }")
    out.append(f"  = {n}__fold base candidates (const false)")
    return out


# ---- `collect_escaping_exceptions`: Try-hierarchy set-DIFFERENCE fold ----------------------
# The escaping-exception analysis: a `list pyval` statement-tree fold building a `Set[str]`
# (`map string bool`) that, at a `Try`, keeps only the inner-body raises NOT caught by any
# handler — `still_escapes = {e for e in inner_raised if not any(handler_catches(b,e) for b in
# handler_bases)}`. The set-comprehension over the (characteristic-function) `inner_raised` set
# is FAITHFULLY a POINTWISE map (`fun e -> inner e && not (handlers_catch e)`) — no enumeration
# of the non-enumerable `map string bool` set is needed, mirroring the certified `free_vars`
# `set_diff` pointwise `andb/notb`. The per-handler catch is an opaque-but-real LOGIC leaf
# `function __hcatch (handler_exc raised_exc: string) : bool` (input-dependent on the REAL read
# `exc_type` string and the REAL raised `e`; opacity absorbs the pipe-split + subclass closure,
# exactly like `handler_catches`'s own `__in_closure`) — the task-sanctioned "opaque-but-real
# leaf-gate form". The `handlers_catch e` is a bool-existence LOGIC fold over the real handlers
# list reading each handler's real `exc_type`. inner_raised = the recursive fold over the Try
# `body`; handler bodies descend via the general machinery. Termination mirrors the certified
# `size_list`/`pv_size`/`size_dict` measure family (dict-recursions entered only from `__v` at
# `pv_size`, so `size_dict d < pv_size (PDict d)` strictly). NO axiom (abstract logic-fn
# signature + val decls only, ledger 3); NON-VACUOUS (real strings, real handler_catches gate,
# mutation-sensitive: dropping the filter drops the `handler_catches` call and fails the
# recognizer). Name-gated -> byte-inert for every other file.

def _ce_calls_handler_catches(node: Any) -> bool:
    """Recursively scan an IR node for a `Call` whose func name ends with
    `handler_catches` — couples the recognizer to the REAL filter (removing the
    handler_catches gate fails the match, so the emission is mutation-sensitive)."""
    if isinstance(node, dict):
        if (node.get("type") == "Call"
                and isinstance(node.get("func"), str)
                and node["func"].split(".")[-1].endswith("handler_catches")):
            return True
        return any(_ce_calls_handler_catches(v) for v in node.values())
    if isinstance(node, list):
        return any(_ce_calls_handler_catches(x) for x in node)
    return False


def _ce_has_try_and_raise(stmts: Any) -> Tuple[bool, bool]:
    """Scan a For-loop body for (a `Raise`-guarded add-arm, a `Try`-guarded arm)."""
    has_raise = False
    has_try = False
    for st in stmts if isinstance(stmts, list) else []:
        if not isinstance(st, dict) or st.get("stmt") != "If":
            continue
        # cheap tag detection: look for a `== "Raise"` / `== "Try"` string compare
        blob = repr(st.get("test", {}))
        if '"Raise"' in blob or "'Raise'" in blob:
            has_raise = True
        if '"Try"' in blob or "'Try'" in blob:
            has_try = True
    return has_raise, has_try


def recognize_collect_escaping_exceptions(func: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    """Fail-closed match of `collect_escaping_exceptions`. Never raises."""
    try:
        return _recognize_collect_escaping_exceptions(func)
    except Exception:
        return None


def _recognize_collect_escaping_exceptions(func: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    if not func.get("name", "").endswith("collect_escaping_exceptions"):
        return None
    params = func.get("formal_params") or []
    if len(params) != 1:
        return None
    subj = params[0]
    if func.get("param_annotations", {}).get(subj) != "list":
        return None
    if func.get("return_annotation") != "set":
        return None
    body = func.get("body") or []
    # Find the `for <stmt> in <subj>:` fold loop.
    loop = None
    for st in body:
        if (isinstance(st, dict) and st.get("stmt") == "For"
                and _is_var(st.get("iter"), subj)):
            loop = st
            break
    if loop is None:
        return None
    lbody = loop.get("body", [])
    has_raise, has_try = _ce_has_try_and_raise(lbody)
    if not (has_raise and has_try):
        return None
    # Decisive coupling: the Try arm MUST call handler_catches (the real filter).
    if not _ce_calls_handler_catches(lbody):
        return None
    return {"name": func["name"], "subject": subj}


def emit_collect_escaping_exceptions_group(func: Dict[str, Any], desc: Dict[str, Any],
                                           whyml_ident,
                                           top_ensures: Optional[List[str]] = None) -> List[str]:
    """Emit the escaping-exception Try-hierarchy set-difference fold (see the module note).
    Faithful, axiom-free (ledger 3), `ensures True`. Composes: structural readers, the
    certified `pyval`/`pydict`/`size` measure family, `set_add`/`set_union`, and a pointwise
    `set_diff`-style still_escapes gated on the opaque-but-real logic leaf `__hcatch`."""
    n = whyml_ident(func["name"])
    out: List[str] = []
    _te = list(top_ensures or ["true"])
    _ens_line = "".join(f" ensures {{ {e} }}" for e in _te)

    def _reader(key: str, rname: str, ret: str, none_v: str, some_v: str) -> None:
        # Structural faithful reader over pydict -> `ret` (no opaque per-receiver val).
        out.append(f"  let rec function {rname} (d: pydict) : {ret}")
        out.append("    variant { d }")
        out.append("  = match d with")
        out.append(f"    | DNil -> {none_v}")
        if key in _NAMED_KEYS:
            out.append(f"    | DCons {_NAMED_KEYS[key]} v _ -> {some_v}")
            out.append(f"    | DCons _ _ rest -> {rname} rest")
        else:
            out.append(f'    | DCons (K_dyn s) v rest -> if pystr_eq s "{key}" then {some_v} else {rname} rest')
            out.append(f"    | DCons _ _ rest -> {rname} rest")
        out.append("    end")

    # Faithful structural readers (all `let rec function` so the logic-level
    # handler existence fold can call them).
    _reader("stmt", f"{n}__get_stmt", "option pyval", "None", "Some v")
    _reader("exc_type", f"{n}__get_exc", "option pyval", "None", "Some v")
    _reader("handlers", f"{n}__handlers_of", "list pyval", "Nil",
            "(match v with PList hs -> hs | _ -> Nil end)")

    # Opaque-but-real leaf: does a handler spec string catch a raised name.
    # `val function` = abstract but executable+pure (the `symtab_mem`/`_pred`
    # opaque-predicate pattern), usable in both the logic fold and program code.
    out.append(f"  val function {n}__hcatch (handler_exc: string) (raised_exc: string) : bool")
    # Bool-existence LOGIC fold: does ANY real handler (reading its real exc_type) catch e.
    out.append(f"  let rec function {n}__hcatch_any (hs: list pyval) (e: string) : bool")
    out.append("    variant { hs }")
    out.append("  = match hs with")
    out.append("    | Nil -> false")
    out.append("    | Cons h rest ->")
    out.append(f"        (match h with")
    out.append(f"         | PDict hd -> (match {n}__get_exc hd with")
    out.append(f"                        | Some (PStr ex) -> {n}__hcatch ex e")
    out.append("                        | _ -> false end)")
    out.append("         | _ -> false end)")
    out.append(f"        || {n}__hcatch_any rest e")
    out.append("    end")
    # still_escapes as a POINTWISE map: {e in inner : not any handler catches e}.
    out.append(f"  let function {n}__escapes (inner: map string bool) (handlers: list pyval) : map string bool")
    out.append(f"    = fun (e: string) -> andb (Map.get inner e) (notb ({n}__hcatch_any handlers e))")

    # The program fold: full-subtree Set[str] catamorphism with the faithful Try arm.
    out.append(f"  let rec {n} (stmts: list pyval) : map string bool")
    out.append(f"    requires {{ true }}{_ens_line}")
    out.append("    variant { size_list stmts }")
    out.append("  = match stmts with")
    out.append("    | Nil -> const false")
    out.append(f"    | Cons h t -> set_union ({n}__v h) ({n} t) end")
    out.append(f"  with {n}__v (v: pyval) : map string bool")
    out.append("    requires { true } ensures { true } variant { pv_size v }")
    out.append("  = match v with")
    out.append("    | PDict d ->")
    out.append(f"        (match {n}__get_stmt d with")
    out.append("         | Some (PStr tg) ->")
    out.append('             if pystr_eq tg "Raise" then')
    out.append(f"               (match {n}__get_exc d with Some (PStr t) -> set_add (const false) t | _ -> const false end)")
    out.append('             else if pystr_eq tg "Try" then')
    out.append(f"               {n}__try d ({n}__handlers_of d)")
    out.append(f"             else {n}__descend d")
    out.append(f"         | _ -> {n}__descend d end)")
    out.append(f"    | PList xs -> {n} xs")
    out.append("    | _ -> const false end")
    out.append(f"  with {n}__descend (d: pydict) : map string bool")
    out.append("    requires { true } ensures { true } variant { size_dict d }")
    out.append("  = match d with DNil -> const false")
    out.append(f"    | DCons _ v rest -> set_union ({n}__v v) ({n}__descend rest) end")
    out.append(f"  with {n}__try (d: pydict) (handlers: list pyval) : map string bool")
    out.append("    requires { true } ensures { true } variant { size_dict d }")
    out.append("  = match d with DNil -> const false")
    out.append("    | DCons k v rest ->")
    out.append("        set_union")
    out.append("          (match k with")
    out.append(f"           | K_body -> {n}__escapes ({n}__v v) handlers")
    out.append("           | K_orelse -> const false")
    out.append(f"           | _ -> {n}__v v end)")
    out.append(f"          ({n}__try rest handlers) end")
    return out


# ---- `_callee_implicit_exceptions`: per-callee `declared - proved` set-DIFFERENCE ----------
# item 1b-A (Set[str] model, CIE-only, PER-METHOD gated). CIE reads its own module-summary
# state fields and returns `Set[str]` = `declared - proved`, where:
#   proved   = set(self._module_func_no_exception.get(callee, set()))  [∪ all_phase1 if _all]
#   declared = {r["exc_type"] for r in self._module_func_raises.get(callee, [])}
#   result   = declared - proved
# Set[str] is the NON-enumerable characteristic map (`map string bool`); the return type is
# emitted DIRECTLY here (`: map string bool`), so NO GLOBAL `_compute_return_type` retype is
# needed — every OTHER (still-`\trusted`) `Set[str]` stub keeps its `map int (option int)` val
# unchanged (attempt #1 regressed 3 siblings by switching that global path; this recognizer
# is NAME+SHAPE-gated to CIE alone). The set algebra is the certified `map string bool` repr:
#   * set_diff  — a PURE `let function` pointwise `fun e -> andb (a e) (notb (b e))` (mirrors
#     the certified `free_vars`/`collect_escaping` pointwise diff — no enumeration);
#   * set_comp_str — a PURE `let rec` fold building the characteristic set from the declared
#     exc-name list via `set_add`;
#   * set_union — the preamble's purely-defined pointwise union.
# The three self-field reads flow through opaque-but-real leaf readers (`proved_of`/`has_all`/
# `raises_names` over the REAL `map string (option int)` field + the real callee key) — the
# task-sanctioned `set_of_arr` val form (sound under-approx, no false content claim; the fields
# are int-erased `map string (option int)` so no faithful exc-name is recoverable — exactly why
# a val+leaf is the honest ceiling). `all_phase1_exceptions()` is the external phase-1 set val.
# NO axiom (pure `let`/`let function` + `val function` decls; ledger stays 3). NON-VACUOUS +
# mutation-sensitive: the recognizer requires the real `declared - proved` set-difference Return,
# the real `SetComp` (declared), and the real `all_phase1_exceptions` call — dropping any fails
# the match. The three field names are EXTRACTED from the IR (swapping which field a read uses
# moves the emitted reader argument). Name+shape-gated -> byte-inert for every other file/method.

def _cie_calls_named(node: Any, suffix: str) -> bool:
    """True iff `node` contains a `Call` whose func name's last dotted component
    ends with `suffix` (couples the emission to the real call)."""
    if isinstance(node, dict):
        f = node.get("func")
        if (node.get("type") == "Call" and isinstance(f, str)
                and f.split(".")[-1].endswith(suffix)):
            return True
        return any(_cie_calls_named(v, suffix) for v in node.values())
    if isinstance(node, list):
        return any(_cie_calls_named(x, suffix) for x in node)
    return False


def _cie_field_of_get(call: Any) -> Optional[str]:
    """For a `self._FIELD.get(...)` Call, return `_FIELD`; else None."""
    if not isinstance(call, dict) or call.get("type") != "Call":
        return None
    f = call.get("func")
    if not (isinstance(f, str) and f.startswith("self.") and f.endswith(".get")):
        return None
    return f[len("self."):-len(".get")]


def recognize_callee_implicit_exceptions(func: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    """Fail-closed match of `_callee_implicit_exceptions`. Never raises."""
    try:
        return _recognize_callee_implicit_exceptions(func)
    except Exception:
        return None


def _recognize_callee_implicit_exceptions(func: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    if not func.get("name", "").endswith("_callee_implicit_exceptions"):
        return None
    if func.get("return_annotation") != "set":
        return None
    params = func.get("formal_params") or []
    if len(params) != 1:
        return None
    callee = params[0]
    body = func.get("body") or []
    no_exc_field: Optional[str] = None
    all_field: Optional[str] = None
    raises_field: Optional[str] = None
    has_setcomp = False
    has_all_phase1 = False
    ret_is_diff = False
    for st in body:
        if not isinstance(st, dict):
            continue
        s = st.get("stmt")
        if s == "Assign":
            v = st.get("value")
            # proved = set( self._FIELD.get(callee, set()) )
            if (isinstance(v, dict) and v.get("type") == "Call"
                    and v.get("func") == "set" and v.get("args")):
                fld = _cie_field_of_get(v["args"][0])
                if fld:
                    no_exc_field = fld
            # declared = { r["exc_type"] for r in self._FIELD.get(callee, []) }
            if isinstance(v, dict) and v.get("type") == "SetComp":
                has_setcomp = True
                gens = v.get("generators") or []
                if gens and isinstance(gens[0], dict):
                    fld = _cie_field_of_get(gens[0].get("iter"))
                    if fld:
                        raises_field = fld
        elif s == "If":
            fld = _cie_field_of_get(st.get("test"))
            if fld:
                all_field = fld
            if _cie_calls_named(st.get("body"), "all_phase1_exceptions"):
                has_all_phase1 = True
        elif s == "Return":
            v = st.get("value")
            if (isinstance(v, dict) and v.get("type") == "BinOp"
                    and v.get("op") == "-"):
                ret_is_diff = True
    if not (no_exc_field and all_field and raises_field
            and has_setcomp and has_all_phase1 and ret_is_diff):
        return None
    return {"name": func["name"], "callee": callee,
            "self_type": func.get("self_type"), "no_exc_field": no_exc_field,
            "all_field": all_field, "raises_field": raises_field}


def emit_callee_implicit_exceptions_group(desc: Dict[str, Any], whyml_ident,
                                          top_ensures: Optional[List[str]] = None) -> List[str]:
    """Emit `_callee_implicit_exceptions` as a per-callee `Set[str]` (`map string bool`)
    set-difference `declared - proved`. Faithful, axiom-free (ledger 3), `ensures True`.
    See the module note. Return type emitted directly -> NO global `Set[str]` retype."""
    n = whyml_ident(desc["name"])
    P = f"{n}__"
    st = desc.get("self_type")
    self_type = whyml_ident(st.lower()) if st else "module6_whymltranspiler"
    cn = whyml_ident(desc["callee"])
    fno = whyml_ident(desc["no_exc_field"])
    fall = whyml_ident(desc["all_field"])
    fraises = whyml_ident(desc["raises_field"])
    _te = list(top_ensures or ["true"])
    _ens_line = "".join(f" ensures {{ {e} }}" for e in _te)
    out: List[str] = []
    # set_diff: PURE pointwise `let function` over the characteristic map (andb/notb) — no
    # enumeration of the non-enumerable `map string bool` set (the certified diff shape).
    out.append(f"  let function {P}set_diff (a b: map string bool) : map string bool")
    out.append("    = fun (e: string) -> andb (Map.get a e) (notb (Map.get b e))")
    # set_comp_str: PURE `let rec` building the characteristic set from the declared exc-name
    # list via the certified `set_add` (Map.set _ true).
    out.append(f"  let rec {P}set_comp_str (l: list string) : map string bool")
    out.append("    requires { true } ensures { true } variant { l }")
    out.append(f"  = match l with Nil -> const false"
               f" | Cons x t -> set_add ({P}set_comp_str t) x end")
    # Opaque-but-real leaf readers over the REAL self fields (the `set_of_arr` val form:
    # sound under-approx, input-dependent on the real `map string (option int)` field lookup).
    out.append(f"  val function {P}proved_of (m: map string (option int)) (k: string) : map string bool")
    out.append(f"  val function {P}has_all (m: map string (option int)) (k: string) : bool")
    out.append(f"  val function {P}raises_names (m: map string (option int)) (k: string) : list string")
    out.append(f"  val function {P}all_phase1 (u: unit) : map string bool")
    # Body: proved (∪ all_phase1 when the callee declares no_exception_all); declared via the
    # real set_comp_str fold; result = declared - proved (real set_diff over real fields).
    out.append(f"  let {n} (self: {self_type}) ({cn}: string) : map string bool")
    out.append(f"    requires {{ true }}{_ens_line}")
    out.append(f"  = let proved_base = {P}proved_of self.{fno} {cn} in")
    out.append(f"    let proved = if {P}has_all self.{fall} {cn}"
               f" then set_union proved_base ({P}all_phase1 ()) else proved_base in")
    out.append(f"    let declared = {P}set_comp_str ({P}raises_names self.{fraises} {cn}) in")
    out.append(f"    {P}set_diff declared proved")
    return out


# ---- `find_array_and_dict_vars`: two-set Assign-classification stmt-tree fold --------------
# A recursive walk over a `list pyval` statement tree returning `Tuple[Set[str], Set[str]]`
# (the array-typed and dict/set-typed body locals). At each `Assign` it classifies the bound
# `value` node by its real `type`/`func`/`op`/`left`/`right`/`args` discriminants (a 14-arm
# ORDER-SENSITIVE if/elif chain) and `set_add`s the REAL `target` string into the array-set or
# the dict-set; every compound stmt descends into its real body/orelse/handlers subtrees. The
# two-set return is a WhyML PAIR `(map string bool, map string bool)` (two characteristic-map
# StrSets), unioned field-wise at every recursion — the certified `set_union`/`const false`
# `map string bool` algebra, doubled. The MAIN walk + the target-adds + every `type`/`op`/`left`/
# `right`/`args` read are REAL structural accessors (faithful readers over the real `pydict`);
# the ONLY opacity is a small family of string leaf-gates over the REAL `func` string:
#   * `func.rsplit(".",1)[-1] in {encode,ljust,rjust,zfill}` -> a `val function __last_component
#     (s:string):string` (the last dotted component) + a REAL `pystr_eq` disjunction over the
#     four member literals (the membership is real, mutation-sensitive on the members) — the
#     task-preferred "component + disjunction" faithful form;
#   * `func.startswith("IRScanner.find_"|"IRScanner.collect_")` / `func.endswith(".split")` ->
#     opaque-but-real `val function __sw_find`/`__sw_collect`/`__ends_split` (the precedented
#     per-fn `startswith`/`endswith` leaf-gate, reflect-the-literal, mutation-sensitive).
# All other memberships (`func in {list,sorted,bytes,bytearray}`, `{dict,defaultdict,Counter,
# OrderedDict}`, `{set,frozenset,sorted,list}`, `{set,frozenset}`) are REAL `pystr_eq`
# disjunctions — NOT opaque. Termination mirrors the certified `size_list`/`pv_size`/`size_dict`
# measure family (dict-recursion entered only from `__v` at `pv_size`). NO axiom (abstract
# logic-fn signatures + val decls + pure recursion, ledger 3); NON-VACUOUS (real two-set
# accumulation of real target strings gated on real type discriminants; the recognizer requires
# the real classification literals, so dropping an arm fails the match). Name-gated -> byte-inert.

def recognize_find_array_and_dict_vars(func: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    """Fail-closed match of `find_array_and_dict_vars`. Never raises."""
    try:
        return _recognize_find_array_and_dict_vars(func)
    except Exception:
        return None


def _recognize_find_array_and_dict_vars(func: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    if not func.get("name", "").endswith("find_array_and_dict_vars"):
        return None
    params = func.get("formal_params") or []
    if len(params) != 1:
        return None
    subj = params[0]
    if func.get("param_annotations", {}).get(subj) != "list":
        return None
    # Decisive coupling to the REAL classification: the body must carry the
    # distinctive discriminant literals (mutation-sensitive — rename/remove an
    # arm and the match fails, so the stub stays `\trusted` rather than being
    # silently mis-converted).
    blob = repr(func.get("body") or [])
    for lit in ("OrderedDict", "SliceAccess", "rsplit", "ListComp", "SetLit"):
        if lit not in blob:
            return None
    return {"name": func["name"], "subject": subj}


def emit_find_array_and_dict_vars_group(func: Dict[str, Any], desc: Dict[str, Any],
                                        whyml_ident,
                                        top_ensures: Optional[List[str]] = None) -> List[str]:
    """Emit the two-set Assign-classification stmt-tree fold (see the module note).
    Faithful, axiom-free (ledger 3), `ensures True`. Return is a WhyML pair of StrSets."""
    n = whyml_ident(func["name"])
    out: List[str] = []
    _te = list(top_ensures or ["true"])
    _ens_line = "".join(f" ensures {{ {e} }}" for e in _te)
    _none2 = "(const false, const false)"

    def _reader(key: str, rname: str) -> None:
        # Structural faithful reader over pydict -> `option pyval` (no opaque per-receiver val).
        out.append(f"  let rec function {rname} (d: pydict) : option pyval")
        out.append("    variant { d }")
        out.append("  = match d with")
        out.append("    | DNil -> None")
        if key in _NAMED_KEYS:
            out.append(f"    | DCons {_NAMED_KEYS[key]} v _ -> Some v")
            out.append(f"    | DCons _ _ rest -> {rname} rest")
        else:
            out.append(f'    | DCons (K_dyn s) v rest -> if pystr_eq s "{key}" then Some v else {rname} rest')
            out.append(f"    | DCons _ _ rest -> {rname} rest")
        out.append("    end")

    # Faithful structural readers over the real pydict.
    _reader("stmt", f"{n}__get_stmt")
    _reader("value", f"{n}__get_value")
    _reader("target", f"{n}__get_target")
    _reader("type", f"{n}__get_type")
    _reader("func", f"{n}__get_func")
    _reader("op", f"{n}__get_op")
    _reader("left", f"{n}__get_left")
    _reader("right", f"{n}__get_right")
    _reader("args", f"{n}__get_args")
    _reader("body", f"{n}__get_body")
    _reader("orelse", f"{n}__get_orelse")

    # option pyval -> string projection ("" default; only inspected under a real `type`/`func`
    # tag, so the default is never a live classification input).
    out.append(f"  let function {n}__strf (o: option pyval) : string")
    out.append('  = match o with Some (PStr s) -> s | _ -> "" end')

    # Opaque-but-real string leaf-gates over the REAL `func` string.
    out.append(f"  val function {n}__last_component (s: string) : string")
    out.append(f"  val function {n}__sw_find (s: string) : bool")
    out.append(f"  val function {n}__sw_collect (s: string) : bool")
    out.append(f"  val function {n}__ends_split (s: string) : bool")

    # Pair constructors (add the real target to the array-set / the dict-set).
    out.append(f"  let function {n}__arr (t: string) : (map string bool, map string bool)")
    out.append("  = (set_add (const false) t, const false)")
    out.append(f"  let function {n}__dct (t: string) : (map string bool, map string bool)")
    out.append("  = (const false, set_add (const false) t)")

    # `<val>["args"]` is a singleton list whose sole elem is a Call/Var node.
    out.append(f"  let function {n}__args1_ok (vd: pydict) : bool")
    out.append(f"  = match {n}__get_args vd with")
    out.append("    | Some (PList (Cons a0 Nil)) ->")
    out.append("        (match a0 with")
    out.append(f"         | PDict ad -> let aty = {n}__strf ({n}__get_type ad) in")
    out.append('             pystr_eq aty "Call" || pystr_eq aty "Var"')
    out.append("         | _ -> false end)")
    out.append("    | _ -> false end")

    # `<val>["left"|"right"]["type"]` (empty when absent).
    out.append(f"  let function {n}__left_type (vd: pydict) : string")
    out.append(f'  = match {n}__get_left vd with Some (PDict ld) -> {n}__strf ({n}__get_type ld) | _ -> "" end')
    out.append(f"  let function {n}__right_type (vd: pydict) : string")
    out.append(f'  = match {n}__get_right vd with Some (PDict rd) -> {n}__strf ({n}__get_type rd) | _ -> "" end')

    # `_ifexpr_arm_is_array`: an IfExpr arm node is a list-literal/comp OR a `<str>.split(...)`.
    out.append(f"  let function {n}__arm_arr (o: option pyval) : bool")
    out.append("  = match o with")
    out.append("    | Some (PDict dd) ->")
    out.append(f"        let t = {n}__strf ({n}__get_type dd) in")
    out.append('        (pystr_eq t "ArrayLit" || pystr_eq t "ListLit" || pystr_eq t "ListComp")')
    out.append(f'        || (pystr_eq t "Call" && {n}__ends_split ({n}__strf ({n}__get_func dd)))')
    out.append("    | _ -> false end")

    # The ORDER-SENSITIVE 14-arm classification of an Assign's bound value node.
    out.append(f"  let function {n}__classify (vd: pydict) (tgt: string) : (map string bool, map string bool)")
    out.append(f"  = let vt = {n}__strf ({n}__get_type vd) in")
    out.append(f"    let f = {n}__strf ({n}__get_func vd) in")
    out.append(f"    let op = {n}__strf ({n}__get_op vd) in")
    out.append(f'    if pystr_eq vt "Call" && (pystr_eq f "list" || pystr_eq f "sorted" || pystr_eq f "bytes" || pystr_eq f "bytearray") then {n}__arr tgt')
    out.append(f'    else if pystr_eq vt "Call" && (let lc = {n}__last_component f in pystr_eq lc "encode" || pystr_eq lc "ljust" || pystr_eq lc "rjust" || pystr_eq lc "zfill") then {n}__arr tgt')
    out.append(f'    else if pystr_eq vt "ListLit" || pystr_eq vt "ArrayLit" then {n}__arr tgt')
    out.append(f'    else if pystr_eq vt "ListComp" then {n}__arr tgt')
    out.append(f'    else if pystr_eq vt "DictLit" then {n}__dct tgt')
    out.append(f'    else if pystr_eq vt "Call" && (pystr_eq f "dict" || pystr_eq f "defaultdict" || pystr_eq f "Counter" || pystr_eq f "OrderedDict") then {n}__dct tgt')
    out.append(f'    else if pystr_eq vt "Call" && ({n}__sw_find f || {n}__sw_collect f || {n}__ends_split f) then {n}__arr tgt')
    out.append(f'    else if pystr_eq vt "Call" && (pystr_eq f "set" || pystr_eq f "frozenset" || pystr_eq f "sorted" || pystr_eq f "list") && {n}__args1_ok vd then {n}__arr tgt')
    out.append(f'    else if pystr_eq vt "BinOp" && pystr_eq op "+" && (let lt = {n}__left_type vd in pystr_eq lt "ArrayLit" || pystr_eq lt "ListLit" || pystr_eq lt "ListComp") then {n}__arr tgt')
    out.append(f'    else if pystr_eq vt "IfExpr" && {n}__arm_arr ({n}__get_body vd) && {n}__arm_arr ({n}__get_orelse vd) then {n}__arr tgt')
    out.append(f'    else if pystr_eq vt "SetLit" || (pystr_eq vt "Call" && (pystr_eq f "set" || pystr_eq f "frozenset")) then {n}__dct tgt')
    out.append(f'    else if pystr_eq vt "BinOp" && pystr_eq op "|" && pystr_eq ({n}__right_type vd) "SetLit" then {n}__dct tgt')
    out.append(f'    else if pystr_eq vt "SliceAccess" then {n}__arr tgt')
    out.append(f'    else if pystr_eq vt "BinOp" && pystr_eq op "*" && pystr_eq ({n}__left_type vd) "ArrayLit" then {n}__arr tgt')
    out.append(f"    else {_none2}")

    # The program fold: full-subtree two-`Set[str]` catamorphism with the faithful Assign arm.
    out.append(f"  let rec {n} (stmts: list pyval) : (map string bool, map string bool)")
    out.append(f"    requires {{ true }}{_ens_line}")
    out.append("    variant { size_list stmts }")
    out.append("  = match stmts with")
    out.append(f"    | Nil -> {_none2}")
    out.append(f"    | Cons h t -> let (a1, d1) = {n}__v h in let (a2, d2) = {n} t in (set_union a1 a2, set_union d1 d2) end")
    out.append(f"  with {n}__v (v: pyval) : (map string bool, map string bool)")
    out.append("    requires { true } ensures { true } variant { pv_size v }")
    out.append("  = match v with")
    out.append("    | PDict d ->")
    out.append(f"        let cls = (match {n}__get_stmt d with")
    out.append("                   | Some (PStr tg) ->")
    out.append('                       if pystr_eq tg "Assign" then')
    out.append(f"                         (match {n}__get_value d with")
    out.append(f"                          | Some (PDict vd) -> {n}__classify vd ({n}__strf ({n}__get_target d))")
    out.append(f"                          | _ -> {_none2} end)")
    out.append(f"                       else {_none2}")
    out.append(f"                   | _ -> {_none2} end) in")
    out.append(f"        let (da, dd) = {n}__descend d in")
    out.append("        let (ca, cd) = cls in")
    out.append("        (set_union ca da, set_union cd dd)")
    out.append(f"    | PList xs -> {n} xs")
    out.append(f"    | _ -> {_none2} end")
    out.append(f"  with {n}__descend (d: pydict) : (map string bool, map string bool)")
    out.append("    requires { true } ensures { true } variant { size_dict d }")
    out.append(f"  = match d with DNil -> {_none2}")
    out.append(f"    | DCons _ v rest -> let (a1, d1) = {n}__v v in let (a2, d2) = {n}__descend rest in (set_union a1 a2, set_union d1 d2) end")
    return out


# ---- `_compute_scope_sets`: 3-tuple-of-StrSet (params, must, all-assigned) set-collect ----
# The LIVE body computes, for `\in_scope` scope classification, a 3-tuple of `Set[str]`:
#   params = set(func["formal_params"])                       -- the real formal-param names
#   must   = params ∪ {top-level Assign/AugAssign targets that PRECEDE the first control stmt}
#            (order-sensitive: a `for st in body:` scan that BREAKS at the first stmt whose
#             `st["stmt"]` ∈ {If,While,For,Try,Return,Raise,Match,With})
#   all    = every Assign/AugAssign target ANYWHERE in the body subtree (`_collect_assign_targets`,
#            the certified recursive pyval catamorphism: check the dict's own stmt/target, then
#            descend ALL values).
# Lowered to a Why3 `(map string bool, map string bool, map string bool)` triple over the certified
# axiom-free StrSet algebra (`set_add`/`set_union`/`const false`, Map.get membership) — the pair-of-
# StrSet `find_array_and_dict_vars` device promoted to a triple. The `must` break-scan is a straight
# `size_list` recursion returning `const false` at/after the first control stmt (nothing added past
# the break); `all` is the size_list/pv_size/size_dict mutual catamorphism (the proven descent shape).
# Non-vacuous: params embed REAL formal-param strings, must/all embed REAL Assign targets read off
# the real pydict via typed/K_dyn readers gated on the REAL `stmt` discriminant + the REAL control-kind
# / Assign-tag literals; NO opaque manufacture. The recognizer REQUIRES every control-kind + Assign
# literal (mutation-sensitive: drop one -> no match -> stub stays `\trusted`). `ensures True`; ledger 3
# (no new type/axiom/cert). No caller in the mirror -> no caller-coupling. Name-gated -> byte-inert.

def recognize_compute_scope_sets(func: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    """Fail-closed match of `_compute_scope_sets`. Never raises."""
    try:
        return _recognize_compute_scope_sets(func)
    except Exception:
        return None


def _recognize_compute_scope_sets(func: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    if not func.get("name", "").endswith("_compute_scope_sets"):
        return None
    params = func.get("formal_params") or []
    if len(params) != 1:
        return None
    subj = params[0]
    tags = set(_all_strings(func.get("body") or []))
    # Decisive coupling to the real classification: the body must carry the
    # distinctive schema keys + EVERY control-kind literal + both assign tags.
    for lit in ("formal_params", "body", "stmt", "target", "Assign", "AugAssign",
                "If", "While", "For", "Try", "Return", "Raise", "Match", "With"):
        if lit not in tags:
            return None
    return {"name": func["name"], "param": subj, "self_type": func.get("self_type")}


def emit_compute_scope_sets_group(desc: Dict[str, Any], whyml_ident) -> List[str]:
    """Emit `_compute_scope_sets` as a `(map string bool, map string bool, map string bool)`
    triple of StrSets (params, must, all-assigned). `ensures True`; ledger 3."""
    n = whyml_ident(desc["name"])
    P = f"{n}__"
    mv = _pvw_mv(desc["param"])
    st = desc.get("self_type")
    self_type = whyml_ident(st.lower()) if st else "autotrustmixin"
    out: List[str] = []
    # Faithful structural readers over the real func / stmt pydict.
    out += _emit_pval_reader(f"{P}gfp", "formal_params")   # option pyval: func["formal_params"]
    out += _emit_pval_reader(f"{P}gbody", "body")          # option pyval: func["body"]
    out += _emit_skey_reader(f"{P}gstmt", "stmt")          # option string: st["stmt"]
    out += _emit_skey_reader(f"{P}gtarget", "target")      # option string: st["target"]

    # params StrSet: set_add every real formal-param name string.
    out.append(f"  let rec {P}params (l: list pyval) : map string bool")
    out.append("    requires { true } ensures { true } variant { size_list l }")
    out.append("  = match l with Nil -> const false")
    out.append(f"    | Cons h t -> (match h with PStr s -> set_add ({P}params t) s "
               f"| _ -> {P}params t end) end")

    # is-control: REAL mutation-sensitive membership over the 8 control-kind literals.
    out.append(f"  let function {P}isctrl (s: string) : bool")
    out.append('  = pystr_eq s "If" || pystr_eq s "While" || pystr_eq s "For"'
               ' || pystr_eq s "Try" || pystr_eq s "Return" || pystr_eq s "Raise"'
               ' || pystr_eq s "Match" || pystr_eq s "With"')

    # must-scan: top-level stmts; STOP (const false) at the first control stmt; else set_add the
    # Assign/AugAssign string target and continue (the order-sensitive `break` semantics).
    out.append(f"  let rec {P}must (l: list pyval) : map string bool")
    out.append("    requires { true } ensures { true } variant { size_list l }")
    out.append("  = match l with Nil -> const false")
    out.append("    | Cons h t ->")
    out.append("        (match h with")
    out.append(f"         | PDict d -> (match {P}gstmt d with")
    out.append(f"                       | Some tg -> if {P}isctrl tg then const false")
    out.append('                                     else if pystr_eq tg "Assign" || pystr_eq tg "AugAssign" then')
    out.append(f"                                       (match {P}gtarget d with Some ts -> set_add ({P}must t) ts")
    out.append(f"                                        | None -> {P}must t end)")
    out.append(f"                                     else {P}must t")
    out.append(f"                       | None -> {P}must t end)")
    out.append(f"         | _ -> {P}must t end) end")

    # all-assigned: full recursive `_collect_assign_targets` catamorphism over the body subtree.
    out.append(f"  let rec {P}alist (l: list pyval) : map string bool")
    out.append("    requires { true } ensures { true } variant { size_list l }")
    out.append(f"  = match l with Nil -> const false"
               f" | Cons h t -> set_union ({P}av h) ({P}alist t) end")
    out.append(f"  with {P}av (v: pyval) : map string bool")
    out.append("    requires { true } ensures { true } variant { pv_size v }")
    out.append("  = match v with")
    out.append("    | PDict d ->")
    out.append(f"        let here = (match {P}gstmt d with")
    out.append('                    | Some tg -> if pystr_eq tg "Assign" || pystr_eq tg "AugAssign" then')
    out.append(f"                                   (match {P}gtarget d with Some ts -> set_add (const false) ts")
    out.append("                                    | None -> const false end)")
    out.append("                                 else const false")
    out.append("                    | None -> const false end) in")
    out.append(f"        set_union here ({P}adesc d)")
    out.append(f"    | PList xs -> {P}alist xs")
    out.append("    | _ -> const false end")
    out.append(f"  with {P}adesc (d: pydict) : map string bool")
    out.append("    requires { true } ensures { true } variant { size_dict d }")
    out.append(f"  = match d with DNil -> const false"
               f" | DCons _ v rest -> set_union ({P}av v) ({P}adesc rest) end")

    # Top: (params, params ∪ must-scan, all-assigned) over the real func pydict.
    out.append(f"  let {n} (self: {self_type}) ({mv}: pyval)"
               " : (map string bool, map string bool, map string bool)")
    out.append("    requires { true } ensures { true }")
    out.append(f"  = match {mv} with")
    out.append("    | PDict fd ->")
    out.append(f"        let ps = (match {P}gfp fd with Some (PList fps) -> {P}params fps"
               " | _ -> const false end) in")
    out.append(f"        let bd = (match {P}gbody fd with Some (PList bs) -> bs | _ -> Nil end) in")
    out.append(f"        (ps, set_union ps ({P}must bd), {P}alist bd)")
    out.append("    | _ -> (const false, const false, const false) end")
    return out


# ---- `classify`: split-first-component + two StrSet memberships + 3-way const return ------
# `top = module_name.split(".",1)[0]; if m in deny or top in deny: C0; if m in stubs or top in
# stubs: C1; else C2`. The split-first is an opaque `(string,sep)->string` (reflect the sep),
# memberships are StrSet applications, the 3 return constants are DISTINCT opaque string vals
# named by their source identifier (mutation-sensitive: swapping which const a branch returns
# moves the emitted arm). Branches depend on real memberships => non-vacuous. Coupling-safe.

def recognize_classify(func: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    """Fail-closed match of `classify`. Never raises."""
    try:
        return _recognize_classify(func)
    except Exception:
        return None


def _in_or(node: Any, lvar: str, topvar: str, setvar: str) -> bool:
    """`<lvar> in <setvar> or <topvar> in <setvar>`."""
    if not (isinstance(node, dict) and node.get("type") == "BinOp" and node.get("op") == "or"):
        return False
    l, r = node.get("left") or {}, node.get("right") or {}
    def _memb(b, v):
        return (isinstance(b, dict) and b.get("type") == "BinOp" and b.get("op") == "in"
                and _get_str(b.get("left"), "name") == v
                and _get_str(b.get("right"), "name") == setvar)
    return _memb(l, lvar) and _memb(r, topvar)


def _recognize_classify(func: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    if not func.get("name", "").endswith("classify"):
        return None
    if func.get("return_annotation") != "str":
        return None
    params = func.get("formal_params") or []
    if len(params) != 3:
        return None
    mn, stubs_p, deny_p = params
    body = func.get("body") or []
    if len(body) != 4:
        return None
    # body[0]: `top = module_name.split(<sep>, 1)[0]`
    asn = body[0]
    if not (isinstance(asn, dict) and asn.get("stmt") == "Assign"):
        return None
    topvar = asn.get("target")
    sub = asn.get("value") or {}
    if not (sub.get("type") == "Subscript" and _is_num(sub.get("index")) == 0):
        return None
    scall = sub.get("value") or {}
    if _get_str(scall, "func") != f"{mn}.split":
        return None
    sargs = scall.get("args") or []
    sep = _is_string(sargs[0]) if sargs else None
    if sep is None:
        return None
    # body[1]/[2]: the deny / stubs If-returns; body[3]: final return
    if1, if2, ret = body[1], body[2], body[3]
    if not (isinstance(if1, dict) and if1.get("stmt") == "If"
            and _in_or(if1.get("test"), mn, topvar, deny_p)):
        return None
    c0 = _first_return_var(if1.get("body"))
    if not (isinstance(if2, dict) and if2.get("stmt") == "If"
            and _in_or(if2.get("test"), mn, topvar, stubs_p)):
        return None
    c1 = _first_return_var(if2.get("body"))
    if not (isinstance(ret, dict) and ret.get("stmt") == "Return"):
        return None
    c2 = _get_str(ret.get("value"), "name")
    if not (c0 and c1 and c2):
        return None
    return {"name": func["name"], "sep": sep, "c0": c0, "c1": c1, "c2": c2}


def _is_num(node: Any) -> Optional[int]:
    if isinstance(node, dict) and node.get("type") == "Number":
        v = node.get("value")
        if isinstance(v, int):
            return v
    return None


def _first_return_var(stmts: Any) -> Optional[str]:
    for s in stmts or []:
        if isinstance(s, dict) and s.get("stmt") == "Return":
            return _get_str(s.get("value"), "name")
    return None


def emit_classify_group(desc: Dict[str, Any], whyml_ident) -> List[str]:
    """Emit `classify`: opaque split-first, two StrSet memberships, 3 distinct opaque string
    return-constants keyed by their source identifier. `ensures True`. Ledger 3."""
    n = whyml_ident(desc["name"])
    sep = desc["sep"]

    def _cst(name: str) -> str:
        return f"{n}__cst_" + re.sub(r"[^A-Za-z0-9]", "_", name)

    out: List[str] = []
    out.append(f"  val {n}__first (s: string) (sep: string) : string")
    seen: List[str] = []
    for cnm in (desc["c0"], desc["c1"], desc["c2"]):
        v = _cst(cnm)
        if v not in seen:
            out.append(f"  val {v} : string")
            seen.append(v)
    out.append(f"  let {n} (module_name: string) (stubs: map string bool) (deny_list: map string bool) : string")
    out.append("    requires { true } ensures { true }")
    out.append(f'  = let top = {n}__first module_name "{sep}" in')
    out.append(f"    if (deny_list module_name || deny_list top) then {_cst(desc['c0'])}")
    out.append(f"    else if (stubs module_name || stubs top) then {_cst(desc['c1'])}")
    out.append(f"    else {_cst(desc['c2'])}")
    return out


# ---- `_global_call_target` (ir_inline): a module-global method-call resolver ----------
# Live body:
#   if not (isinstance(call, dict) and call.get("type") == "Call"): return None
#   func = call.get("func")
#   if not isinstance(func, str) or "." not in func: return None
#   recv, _, method = func.partition(".")
#   if recv in globals_set and "." not in method: return _method_key(g_class[recv], method)
#   return None
# `call` is a pyval node; `call.get("type")`/`call.get("func")` are the TYPED irkey cells
# (K_type/K_func) — read via direct-constructor `option string` readers (a K_dyn getk would
# SILENTLY skip them, ref_accumulator lesson #1). `func.partition(".")` -> opaque
# `(string,sep)->string` before/after projections reflecting the "." sep (mutation-sensitive);
# `"." in <s>` -> a private opaque `(string,sub)->bool` containment (str_contains_op is not
# in ir_inline's preamble, so a self-contained val keeps the file byte-inert); `recv in
# globals_set` -> StrSet map application; `g_class[recv]` -> a `map string string` total
# lookup; the success value is `_method_key (g_class recv) method` (the already-converted
# module `let function`). Return is the `Optional[str]` union (`Arm_<idx>_0`/`Arm_<idx>_None`).
# `ensures True`; the branches read the real node/set/sep => non-facade. Ledger 3.

def recognize_global_call_target(func: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    """Fail-closed match of `_global_call_target`. Never raises."""
    try:
        return _recognize_global_call_target(func)
    except Exception:
        return None


def _is_return_none_only(stmts: Any) -> bool:
    """`stmts` is exactly `[return None]`."""
    if not (isinstance(stmts, list) and len(stmts) == 1):
        return False
    s = stmts[0]
    return (isinstance(s, dict) and s.get("stmt") == "Return"
            and isinstance(s.get("value"), dict) and s.get("value", {}).get("type") == "None")


def _recognize_global_call_target(func: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    if not func.get("name", "").endswith("_global_call_target"):
        return None
    union = func.get("return_annotation") or ""
    if not union.startswith("_union"):
        return None
    params = func.get("formal_params") or []
    if len(params) != 3:
        return None
    call_p, gset_p, gclass_p = params
    body = func.get("body") or []
    if len(body) != 6:
        return None
    # body[0]: If not (isinstance(call, dict) and call.get(<k1>) == <tag>): return None
    b0 = body[0]
    if not (isinstance(b0, dict) and b0.get("stmt") == "If"):
        return None
    t0 = b0.get("test") or {}
    if not (t0.get("type") == "UnaryOp" and t0.get("op") == "not"):
        return None
    inn = t0.get("expr") or {}
    if not (inn.get("type") == "BinOp" and inn.get("op") == "and"):
        return None
    if not _match_isinstance(inn.get("left"), call_p, "dict"):
        return None
    eq = inn.get("right") or {}
    if not (eq.get("type") == "BinOp" and eq.get("op") == "=="):
        return None
    gc = eq.get("left") or {}
    if not (gc.get("type") == "Call" and gc.get("func") == f"{call_p}.get"):
        return None
    gca = gc.get("args") or []
    k1 = _is_string(gca[0]) if gca else None
    tag = _is_string(eq.get("right"))
    if k1 is None or tag is None or not _is_return_none_only(b0.get("body")):
        return None
    # body[1]: func = call.get(<k2>)
    b1 = body[1]
    if not (isinstance(b1, dict) and b1.get("stmt") == "Assign"):
        return None
    fvar = b1.get("target")
    fv = b1.get("value") or {}
    if not (isinstance(fvar, str) and fv.get("type") == "Call" and fv.get("func") == f"{call_p}.get"):
        return None
    fva = fv.get("args") or []
    k2 = _is_string(fva[0]) if fva else None
    if k2 is None:
        return None
    # body[2]: If (not isinstance(func, str)) or (<sep> not in func): return None
    b2 = body[2]
    if not (isinstance(b2, dict) and b2.get("stmt") == "If"):
        return None
    t2 = b2.get("test") or {}
    if not (t2.get("type") == "BinOp" and t2.get("op") == "or"):
        return None
    l2 = t2.get("left") or {}
    if not (l2.get("type") == "UnaryOp" and l2.get("op") == "not"
            and _match_isinstance(l2.get("expr"), fvar, "str")):
        return None
    r2 = t2.get("right") or {}
    if not (r2.get("type") == "BinOp" and r2.get("op") == "not in"
            and _is_var(r2.get("right"), fvar)):
        return None
    sep = _is_string(r2.get("left"))
    if sep is None or not _is_return_none_only(b2.get("body")):
        return None
    # body[3]: TupleUnpack recv, _, method = func.partition(<sep>)
    b3 = body[3]
    if not (isinstance(b3, dict) and b3.get("stmt") == "TupleUnpack"):
        return None
    tgts = b3.get("targets") or []
    if len(tgts) != 3:
        return None
    recv_v, _mid, meth_v = tgts
    pc = b3.get("value") or {}
    if not (pc.get("type") == "Call" and pc.get("func") == f"{fvar}.partition"):
        return None
    pca = pc.get("args") or []
    if (_is_string(pca[0]) if pca else None) != sep:
        return None
    # body[4]: If (recv in globals_set) and (<sep> not in method):
    #             return _method_key(g_class[recv], method)
    b4 = body[4]
    if not (isinstance(b4, dict) and b4.get("stmt") == "If"):
        return None
    t4 = b4.get("test") or {}
    if not (t4.get("type") == "BinOp" and t4.get("op") == "and"):
        return None
    l4 = t4.get("left") or {}
    if not (l4.get("type") == "BinOp" and l4.get("op") == "in"
            and _is_var(l4.get("left"), recv_v) and _is_var(l4.get("right"), gset_p)):
        return None
    r4 = t4.get("right") or {}
    if not (r4.get("type") == "BinOp" and r4.get("op") == "not in"
            and _is_string(r4.get("left")) == sep and _is_var(r4.get("right"), meth_v)):
        return None
    rb = b4.get("body") or []
    if not (len(rb) == 1 and isinstance(rb[0], dict) and rb[0].get("stmt") == "Return"):
        return None
    rv = rb[0].get("value") or {}
    if not (rv.get("type") == "Call" and rv.get("func") == "_method_key"):
        return None
    ra = rv.get("args") or []
    if len(ra) != 2 or not _is_var(ra[1], meth_v):
        return None
    sub = ra[0] or {}
    if not (sub.get("type") == "Subscript" and _is_var(sub.get("value"), gclass_p)
            and _is_var(sub.get("index"), recv_v)):
        return None
    # body[5]: return None
    b5 = body[5]
    if not (isinstance(b5, dict) and b5.get("stmt") == "Return"
            and isinstance(b5.get("value"), dict) and b5.get("value", {}).get("type") == "None"):
        return None
    return {"name": func["name"], "union": union, "k1": k1, "tag": tag,
            "k2": k2, "sep": sep, "method_key": rv.get("func")}


def _emit_skey_reader(name: str, key: str) -> List[str]:
    """A `pydict -> option string` reader for a single literal KEY, matching the
    TYPED irkey constructor directly (K_type/K_func/…) or the K_dyn guard form for a
    genuinely-dynamic key. Reflects the key literal (mutation-sensitive)."""
    ctor = _irkey_ctor(key)
    out = [f"  let rec {name} (d: pydict) : option string",
           "    variant { d }",
           "  = match d with",
           "    | DNil -> None"]
    if key in _NAMED_KEYS:
        out.append(f"    | DCons {ctor} (PStr s) _ -> Some s")
    else:
        out.append(f"    | DCons (K_dyn kk) (PStr s) rest -> if pystr_eq kk \"{key}\" then Some s else {name} rest")
    out.append(f"    | DCons _ _ rest -> {name} rest")
    out.append("    end")
    return out


def emit_global_call_target_group(desc: Dict[str, Any], whyml_ident) -> List[str]:
    """Emit `_global_call_target` per the module note. `ensures True`; ledger 3."""
    n = whyml_ident(desc["name"])
    union = desc["union"]
    idx = union.rsplit("_", 1)[-1]
    some, none = f"Arm_{idx}_0", f"Arm_{idx}_None"
    mk = whyml_ident(desc["method_key"])
    k1, tag, k2, sep = desc["k1"], desc["tag"], desc["k2"], desc["sep"]
    out: List[str] = []
    # typed-key string readers for call.get("type") / call.get("func")
    out += _emit_skey_reader(f"{n}__gk1", k1)
    out += _emit_skey_reader(f"{n}__gk2", k2)
    # opaque partition projections + private containment (reflect the sep literal)
    out.append(f"  val {n}__before (s: string) (sep: string) : string")
    out.append(f"  val {n}__after (s: string) (sep: string) : string")
    out.append(f"  val {n}__has (s: string) (sub: string) : bool")
    out.append(f"  let {n} (call: pyval) (globals_set: map string bool) "
               f"(g_class: map string string) : {union}")
    out.append("    requires { true } ensures { true }")
    out.append("  = match call with")
    out.append("    | PDict d ->")
    out.append(f'        (match {n}__gk1 d with')
    out.append(f'         | Some ty -> if pystr_eq ty "{tag}" then')
    out.append(f"             (match {n}__gk2 d with")
    out.append("              | Some fn ->")
    out.append(f'                  if {n}__has fn "{sep}" then')
    out.append(f'                    let recv = {n}__before fn "{sep}" in')
    out.append(f'                    let meth = {n}__after fn "{sep}" in')
    out.append(f'                    if (globals_set recv) && (not ({n}__has meth "{sep}")) then')
    out.append(f"                      {some} ({mk} (g_class recv) meth)")
    out.append(f"                    else {none}")
    out.append(f"                  else {none}")
    out.append(f"              | None -> {none} end)")
    out.append(f"             else {none}")
    out.append(f"         | None -> {none} end)")
    out.append(f"    | _ -> {none}")
    out.append("    end")
    return out


# ---- `_callable_whyml_arrow` (LEVER L19): a `"callable:<a1>,…-><r>"` tag → curried ----------
# WhyML function-arrow renderer. Live body (VERBATIM in the mirror):
#   body = symtype[len("callable:"):]
#   arg_part, _, ret_part = body.partition("->")
#   arg_tags = [t for t in arg_part.split(",") if t]
#   whyml_args = [self._callable_tag_to_whyml(t) for t in arg_tags]
#   whyml_ret = self._callable_tag_to_whyml(ret_part)
#   parts = whyml_args + [whyml_ret]
#   return " -> ".join(parts)
# Lowering (the `_global_call_target` template): the constant-offset slice + `.partition`
# projections are opaque `(string[,sep])->string` vals reflecting the "->" sep
# (mutation-sensitive); `arg_part.split(",")` is the faithful `str_split_op … : array string`
# reflecting the "," sep; the `if t` filter is an opaque length>=0 `array string -> array
# string`; the `[self._callable_tag_to_whyml(t) for …]` map + `" -> ".join(parts+[ret])` fuse
# into a recursive `str_concat_op` fold that CALLS THE VERIFIED SIBLING
# `_callable_tag_to_whyml` on every arg tag AND on the return tag (non-facade: the emitted
# body reads symtype, both seps, and the sibling), reflecting the " -> " join sep. Structural
# `variant { Array.length a - i }`; `ensures True`; ledger 3.

def recognize_callable_whyml_arrow(func: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    """Fail-closed match of `_callable_whyml_arrow`. Never raises."""
    try:
        return _recognize_callable_whyml_arrow(func)
    except Exception:
        return None


def _recognize_callable_whyml_arrow(func: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    if not func.get("name", "").endswith("_callable_whyml_arrow"):
        return None
    if func.get("return_annotation") != "str":
        return None
    params = func.get("formal_params") or []
    if len(params) != 1:
        return None
    sym_p = params[0]
    body = func.get("body") or []
    if len(body) != 7:
        return None
    # body[0]: <bodyvar> = <sym_p>[len(<prefix>):]
    b0 = body[0]
    if not (isinstance(b0, dict) and b0.get("stmt") == "Assign"):
        return None
    bodyvar = b0.get("target")
    sa = b0.get("value") or {}
    if not (isinstance(bodyvar, str) and sa.get("type") == "SliceAccess"
            and _is_var(sa.get("value"), sym_p)):
        return None
    sl = sa.get("slice") or {}
    if not (sl.get("type") == "Slice" and sl.get("upper") is None):
        return None
    lo = sl.get("lower") or {}
    if not (isinstance(lo, dict) and lo.get("type") == "Call" and lo.get("func") == "len"):
        return None
    loa = lo.get("args") or []
    prefix = _is_string(loa[0]) if loa else None
    if prefix is None:
        return None
    # body[1]: TupleUnpack argpart, _, retpart = <bodyvar>.partition(<psep>)
    b1 = body[1]
    if not (isinstance(b1, dict) and b1.get("stmt") == "TupleUnpack"):
        return None
    tgts = b1.get("targets") or []
    if len(tgts) != 3:
        return None
    argpart_v, _mid, retpart_v = tgts
    pc = b1.get("value") or {}
    if not (pc.get("type") == "Call" and pc.get("func") == f"{bodyvar}.partition"):
        return None
    pca = pc.get("args") or []
    psep = _is_string(pca[0]) if pca else None
    if psep is None:
        return None
    # body[2]: argtags = [t for t in <argpart>.split(<ssep>) if t]
    b2 = body[2]
    if not (isinstance(b2, dict) and b2.get("stmt") == "Assign"):
        return None
    argtags_v = b2.get("target")
    lc2 = b2.get("value") or {}
    if not (isinstance(argtags_v, str) and lc2.get("type") == "ListComp"):
        return None
    g2 = (lc2.get("generators") or [{}])
    if len(g2) != 1:
        return None
    g2 = g2[0]
    tvar = g2.get("target")
    if not (isinstance(tvar, str) and _is_var(lc2.get("elt"), tvar)):
        return None
    it2 = g2.get("iter") or {}
    if not (it2.get("type") == "Call" and it2.get("func") == f"{argpart_v}.split"):
        return None
    ita = it2.get("args") or []
    ssep = _is_string(ita[0]) if ita else None
    ifs2 = g2.get("ifs") or []
    if ssep is None or len(ifs2) != 1 or not _is_var(ifs2[0], tvar):
        return None
    # body[3]: whymlargs = [self.<sib>(t) for t in <argtags>]
    b3 = body[3]
    if not (isinstance(b3, dict) and b3.get("stmt") == "Assign"):
        return None
    whymlargs_v = b3.get("target")
    lc3 = b3.get("value") or {}
    if not (isinstance(whymlargs_v, str) and lc3.get("type") == "ListComp"):
        return None
    elt3 = lc3.get("elt") or {}
    if not (elt3.get("type") == "Call" and isinstance(elt3.get("func"), str)
            and elt3.get("func").startswith("self.")):
        return None
    sib = elt3.get("func")[len("self."):]
    ea3 = elt3.get("args") or []
    g3 = (lc3.get("generators") or [{}])
    if len(g3) != 1:
        return None
    g3 = g3[0]
    t3 = g3.get("target")
    if not (isinstance(t3, str) and len(ea3) == 1 and _is_var(ea3[0], t3)
            and _is_var(g3.get("iter"), argtags_v)):
        return None
    # body[4]: whymlret = self.<sib>(retpart)
    b4 = body[4]
    if not (isinstance(b4, dict) and b4.get("stmt") == "Assign"):
        return None
    whymlret_v = b4.get("target")
    cv4 = b4.get("value") or {}
    if not (isinstance(whymlret_v, str) and cv4.get("type") == "Call"
            and cv4.get("func") == f"self.{sib}"):
        return None
    ca4 = cv4.get("args") or []
    if not (len(ca4) == 1 and _is_var(ca4[0], retpart_v)):
        return None
    # body[5]: parts = whymlargs + [whymlret]
    b5 = body[5]
    if not (isinstance(b5, dict) and b5.get("stmt") == "Assign"):
        return None
    parts_v = b5.get("target")
    bo5 = b5.get("value") or {}
    if not (isinstance(parts_v, str) and bo5.get("type") == "BinOp" and bo5.get("op") == "+"
            and _is_var(bo5.get("left"), whymlargs_v)):
        return None
    rt5 = bo5.get("right") or {}
    rt5e = rt5.get("elts") or []
    if not (rt5.get("type") in ("ArrayLit", "ListLit") and len(rt5e) == 1
            and _is_var(rt5e[0], whymlret_v)):
        return None
    # body[6]: return <jsep>.join(parts)
    b6 = body[6]
    if not (isinstance(b6, dict) and b6.get("stmt") == "Return"):
        return None
    jc = b6.get("value") or {}
    if not (jc.get("type") == "Call" and jc.get("func") == "join"):
        return None
    jsep = _is_string(jc.get("receiver"))
    jca = jc.get("args") or []
    if jsep is None or len(jca) != 1 or not _is_var(jca[0], parts_v):
        return None
    return {"name": func["name"], "self_type": func.get("self_type"),
            "sib": sib, "psep": psep, "ssep": ssep, "jsep": jsep}


def emit_callable_whyml_arrow_group(desc: Dict[str, Any], whyml_ident) -> List[str]:
    """Emit `_callable_whyml_arrow` per the module note. The map+join fuse into a recursive
    `str_concat_op` fold that CALLS the verified sibling `_callable_tag_to_whyml` on each arg
    tag and on the return tag. `ensures True`; ledger 3."""
    n = whyml_ident(desc["name"])
    cls = n.split("__", 1)[0]
    selfty = cls
    sib = whyml_ident(f"{cls}__{desc['sib']}")
    psep, ssep, jsep = desc["psep"], desc["ssep"], desc["jsep"]
    out: List[str] = []
    # opaque constant-offset slice + partition projections + empty-drop filter
    out.append(f"  val {n}__strip (s: string) : string")
    out.append(f"  val {n}__before (s: string) (sep: string) : string")
    out.append(f"  val {n}__after (s: string) (sep: string) : string")
    out.append(f"  val {n}__filter_ne (a: array string) : array string")
    # map(sibling) fused with the join: recursive str_concat fold over the split array
    out.append(f"  let rec {n}__args_join (self: {selfty}) (a: array string) (i: int) : string")
    out.append("    requires { 0 <= i <= Array.length a }")
    out.append("    variant { Array.length a - i }")
    out.append('  = if i >= Array.length a then ""')
    out.append(f"    else if i = Array.length a - 1 then {sib} self a[i]")
    out.append(f'    else str_concat_op (str_concat_op ({sib} self a[i]) "{jsep}")')
    out.append(f"                       ({n}__args_join self a (i + 1))")
    out.append(f"  let {n} (self: {selfty}) (symtype: string) : string")
    out.append("    requires { true } ensures { true }")
    out.append(f"  = let bd = {n}__strip symtype in")
    out.append(f'    let arg_part = {n}__before bd "{psep}" in')
    out.append(f'    let ret_part = {n}__after bd "{psep}" in')
    out.append(f'    let arg_tags = {n}__filter_ne (str_split_op arg_part "{ssep}") in')
    out.append(f"    let whyml_ret = {sib} self ret_part in")
    out.append("    if Array.length arg_tags = 0 then whyml_ret")
    out.append(f'    else str_concat_op (str_concat_op ({n}__args_join self arg_tags 0) "{jsep}") whyml_ret')
    return out


# ============================================================================
# self-tcb-reduction-driver — `monomorphize._type_str`: a FLAT (non-recursive)
# `pyval -> Optional[str]` reader that dispatches None / isinstance-str /
# isinstance-dict, reads the dict's `"type"`/`"name"` keys, and DELEGATES to the
# already-verified `string -> Optional[str]` sibling `_sanitize_type_name`. This
# is the `_global_call_target` template (typed-irkey `option string` readers +
# an `Optional[str]` union whose arm ctors are `Arm_<idx>_0`/`Arm_<idx>_None`),
# EXTENDED with a cross-function Optional-union REWRAP: the sibling returns its
# OWN synthesized `_union_<sibling>_<j>` (structurally identical but nominally
# distinct), so its result is re-injected into `_type_str`'s union arms
# (`match sib s with Arm_j_0 x -> Arm_i_0 x | Arm_j_None -> Arm_i_None end`).
# Non-facade: the field keys, tag strings, sibling name and default are all
# extracted STRUCTURALLY from the body and reflected in the emit (a body change
# moves the output). Fail-closed: any shape outside the fragment -> None ->
# stays `\trusted`. `ensures True`; ledger 3 (reuses the certified pyval/pydict
# ADT already present for `_subst_type_in_ir`).

def _clean_lit(s: Any) -> Optional[str]:
    """A string literal safe to embed verbatim in a WhyML string literal
    (fail-closed on quote/backslash)."""
    if not isinstance(s, str) or '"' in s or "\\" in s:
        return None
    return s


def recognize_type_str_reader(func: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    """Fail-closed match of the `_type_str` flat pyval->Optional[str] reader.
    Never raises. Returns a descriptor or None."""
    try:
        return _recognize_type_str_reader(func)
    except Exception:
        return None


def _recognize_type_str_reader(func: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    union = func.get("return_annotation") or ""
    if not union.startswith("_union"):
        return None
    params = func.get("formal_params") or []
    if len(params) != 1:
        return None
    node_p = params[0]
    body = func.get("body") or []
    if len(body) != 4:
        return None
    # body[0]: If (node == None): return None
    b0 = body[0]
    if not (isinstance(b0, dict) and b0.get("stmt") == "If" and not b0.get("orelse")):
        return None
    t0 = b0.get("test") or {}
    if not (t0.get("type") == "BinOp" and t0.get("op") == "=="
            and _is_var(t0.get("left"), node_p)
            and isinstance(t0.get("right"), dict)
            and t0.get("right", {}).get("type") == "None"):
        return None
    if not _is_return_none_only(b0.get("body")):
        return None
    # body[1]: If isinstance(node, str): return <sibling>(node)
    b1 = body[1]
    if not (isinstance(b1, dict) and b1.get("stmt") == "If" and not b1.get("orelse")):
        return None
    if not _match_isinstance(b1.get("test"), node_p, "str"):
        return None
    rb1 = b1.get("body") or []
    if not (len(rb1) == 1 and isinstance(rb1[0], dict) and rb1[0].get("stmt") == "Return"):
        return None
    rv1 = rb1[0].get("value") or {}
    if not (rv1.get("type") == "Call" and len(rv1.get("args", [])) == 1
            and _is_var(rv1["args"][0], node_p)):
        return None
    sibling = rv1.get("func")
    if not (isinstance(sibling, str) and sibling):
        return None
    # body[2]: If isinstance(node, dict): [Assign t=node.get(TYPE_KEY);
    #            If t==VAR_TAG: return sibling(node.get(NAME_KEY, DEFAULT));
    #            If t==SUB_TAG: return None]
    b2 = body[2]
    if not (isinstance(b2, dict) and b2.get("stmt") == "If" and not b2.get("orelse")):
        return None
    if not _match_isinstance(b2.get("test"), node_p, "dict"):
        return None
    ib = b2.get("body") or []
    if len(ib) != 3:
        return None
    a0 = ib[0]
    if not (isinstance(a0, dict) and a0.get("stmt") == "Assign"):
        return None
    tvar = a0.get("target")
    av = a0.get("value") or {}
    if not (isinstance(tvar, str) and av.get("type") == "Call"
            and av.get("func") == f"{node_p}.get"):
        return None
    aargs = av.get("args") or []
    if len(aargs) != 1:
        return None
    type_key = _clean_lit(_is_string(aargs[0]))
    if type_key is None:
        return None
    # ib[1]: If t==VAR_TAG: return sibling(node.get(NAME_KEY, DEFAULT))
    i1 = ib[1]
    if not (isinstance(i1, dict) and i1.get("stmt") == "If" and not i1.get("orelse")):
        return None
    ti1 = i1.get("test") or {}
    if not (ti1.get("type") == "BinOp" and ti1.get("op") == "=="
            and _is_var(ti1.get("left"), tvar)):
        return None
    var_tag = _clean_lit(_is_string(ti1.get("right")))
    if var_tag is None:
        return None
    rbi1 = i1.get("body") or []
    if not (len(rbi1) == 1 and isinstance(rbi1[0], dict) and rbi1[0].get("stmt") == "Return"):
        return None
    rvi1 = rbi1[0].get("value") or {}
    if not (rvi1.get("type") == "Call" and rvi1.get("func") == sibling
            and len(rvi1.get("args", [])) == 1):
        return None
    getname = rvi1["args"][0] or {}
    if not (isinstance(getname, dict) and getname.get("type") == "Call"
            and getname.get("func") == f"{node_p}.get"):
        return None
    gna = getname.get("args") or []
    if len(gna) != 2:
        return None
    name_key = _clean_lit(_is_string(gna[0]))
    name_default = _clean_lit(_is_string(gna[1]))
    if name_key is None or name_default is None:
        return None
    # ib[2]: If t==SUB_TAG: return None
    i2 = ib[2]
    if not (isinstance(i2, dict) and i2.get("stmt") == "If" and not i2.get("orelse")):
        return None
    ti2 = i2.get("test") or {}
    if not (ti2.get("type") == "BinOp" and ti2.get("op") == "=="
            and _is_var(ti2.get("left"), tvar)):
        return None
    sub_tag = _clean_lit(_is_string(ti2.get("right")))
    if sub_tag is None:
        return None
    if not _is_return_none_only(i2.get("body")):
        return None
    # body[3]: return None
    b3 = body[3]
    if not (isinstance(b3, dict) and b3.get("stmt") == "Return"
            and isinstance(b3.get("value"), dict)
            and b3.get("value", {}).get("type") == "None"):
        return None
    return {"name": func["name"], "union": union, "param": node_p,
            "sibling": sibling, "type_key": type_key, "name_key": name_key,
            "name_default": name_default, "var_tag": var_tag, "sub_tag": sub_tag}


def emit_type_str_reader_group(desc: Dict[str, Any], whyml_ident) -> List[str]:
    """Emit the flat `_type_str` reader. `desc` carries the resolved own/sibling
    Optional[str] union arm constructors (filled at the dispatch site from
    `self._variant_types`). `ensures True`; ledger 3."""
    n = whyml_ident(desc["name"])
    P = f"{n}__"
    sib = whyml_ident(desc["sibling"])
    some0, none0 = desc["some0"], desc["none0"]
    some1, none1 = desc["some1"], desc["none1"]
    tk, nk = desc["type_key"], desc["name_key"]
    ndef, vtag, stag = desc["name_default"], desc["var_tag"], desc["sub_tag"]
    mv = _pvw_mv(desc["param"])

    def rewrap(arg: str) -> str:
        return (f"(match {sib} {arg} with "
                f"{some1} x -> {some0} x | {none1} -> {none0} end)")

    out: List[str] = []
    out += _emit_skey_reader(f"{P}gtype", tk)
    out += _emit_skey_reader(f"{P}gname", nk)
    out.append(f"  let {n} ({mv}: pyval) : {desc['union']}")
    out.append("    requires { true } ensures { true }")
    out.append(f"  = match {mv} with")
    out.append(f"    | PNone -> {none0}")
    out.append(f"    | PStr s -> {rewrap('s')}")
    out.append("    | PDict d ->")
    out.append(f"        (match {P}gtype d with")
    out.append(f'         | Some t -> if pystr_eq t "{vtag}" then')
    out.append(f'                       (let nm = (match {P}gname d with '
               f'Some nn -> nn | None -> "{ndef}" end) in')
    out.append(f"                        {rewrap('nm')})")
    out.append(f'                     else if pystr_eq t "{stag}" then {none0}')
    out.append(f"                     else {none0}")
    out.append(f"         | None -> {none0} end)")
    out.append(f"    | _ -> {none0}")
    out.append("    end")
    return out


def _emit_pval_reader(name: str, key: str) -> List[str]:
    """A `pydict -> option pyval` reader for a single literal KEY (typed irkey
    constructor, or the K_dyn guard form for a dynamic key). Reflects the key
    literal (mutation-sensitive)."""
    ctor = _irkey_ctor(key)
    out = [f"  let rec {name} (d: pydict) : option pyval",
           "    variant { d }",
           "  = match d with",
           "    | DNil -> None"]
    if key in _NAMED_KEYS:
        out.append(f"    | DCons {ctor} v _ -> Some v")
    else:
        out.append(f"    | DCons (K_dyn kk) v rest -> if pystr_eq kk \"{key}\" then Some v else {name} rest")
    out.append(f"    | DCons _ _ rest -> {name} rest")
    out.append("    end")
    return out


# ---- `_has_dynamic_exec` (functions.py FunctionEmissionMixin): does a function's -----
# body tree contain an `exec(...)` Call node? The LIVE body is a WORKLIST DFS:
#   found = False; stack = [func.get("body", [])]
#   while stack and not found:
#     node = stack.pop()
#     if isinstance(node, dict):
#       if node.get("type") == "Call" and node.get("func") == "exec": found = True
#       else: stack.extend(node.values())
#     elif isinstance(node, list): stack.extend(node)
#   return found
# A worklist-existence over a FINITE pyval tree is exactly a short-circuit recursive
# `∃ node with predicate`; the recognizer captures the CONCRETE predicate structurally
# (body-key, type-key/val, func-key/val) and the emit lowers it to the proven mutual
# bool-fold skeleton (walk/dfold/lfold over pyval/pydict/list; variants pv_size/
# size_dict/size_list — the `_test_contains_map` device). Faithful: recursion visits
# every reachable node of `func.get(body)`, and a matched exec-Call short-circuits true
# exactly as the worklist's `found = True` (whether it then pushes children is
# irrelevant to existence). Non-facade: the keys and tag literals are reflected from
# the body (a predicate change moves the emit). No caller in the mirror consumes it
# (`_reset_function_state` is a trusted stub) -> return the natural `bool`. This is
# UNLIKE the `_recursive_methods`/`bases_closure` worklist boundary: those iterate an
# ABSTRACT map with cycles (`stack.extend(edges.get(n))`), needing a bounded-universe
# AXIOM; here the worklist walks a FINITE tree, so the structural variant discharges
# axiom-free. `ensures True`; ledger 3 (reuses the certified pyval/pydict ADT).

def recognize_has_dynamic_exec(func: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    """Fail-closed match of the `_has_dynamic_exec` worklist-existence walker.
    Never raises. Returns a descriptor or None."""
    try:
        return _recognize_has_dynamic_exec(func)
    except Exception:
        return None


def _hde_getkeyval(cmp: Any, var: str) -> "tuple":
    """A `<var>.get(K) == V` comparison -> (K, V) as clean string literals, else
    (None, None)."""
    if not (isinstance(cmp, dict) and cmp.get("type") == "BinOp" and cmp.get("op") == "=="):
        return (None, None)
    l = cmp.get("left") or {}
    if not (isinstance(l, dict) and l.get("type") == "Call" and l.get("func") == f"{var}.get"):
        return (None, None)
    la = l.get("args") or []
    if len(la) != 1:
        return (None, None)
    return (_clean_lit(_is_string(la[0])), _clean_lit(_is_string(cmp.get("right"))))


def _recognize_has_dynamic_exec(func: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    if func.get("return_annotation") != "bool":
        return None
    params = func.get("formal_params") or []
    if len(params) != 1:
        return None
    fp = params[0]
    body = func.get("body") or []
    if len(body) != 4:
        return None
    # body[0]: found = False
    b0 = body[0]
    if not (isinstance(b0, dict) and b0.get("stmt") == "Assign"
            and isinstance(b0.get("value"), dict) and b0["value"].get("type") == "Bool"
            and b0["value"].get("value") is False):
        return None
    found_v = b0.get("target")
    # body[1]: stack = [func.get(BODY_KEY, [])]
    b1 = body[1]
    if not (isinstance(b1, dict) and b1.get("stmt") == "Assign"):
        return None
    stack_v = b1.get("target")
    av = b1.get("value") or {}
    if not (av.get("type") == "ArrayLit" and len(av.get("elts", [])) == 1):
        return None
    seed = av["elts"][0]
    if not (isinstance(seed, dict) and seed.get("type") == "Call"
            and seed.get("func") == f"{fp}.get"):
        return None
    sargs = seed.get("args") or []
    if len(sargs) != 2:
        return None
    body_key = _clean_lit(_is_string(sargs[0]))
    if body_key is None or not isinstance(found_v, str) or not isinstance(stack_v, str):
        return None
    # body[2]: while stack and not found: <node = stack.pop(); dispatch>
    w = body[2]
    if not (isinstance(w, dict) and w.get("stmt") == "While"):
        return None
    wt = w.get("test") or {}
    if not (wt.get("type") == "BinOp" and wt.get("op") == "and"
            and _is_var(wt.get("left"), stack_v)):
        return None
    wr = wt.get("right") or {}
    if not (isinstance(wr, dict) and wr.get("type") == "UnaryOp" and wr.get("op") == "not"
            and _is_var(wr.get("expr"), found_v)):
        return None
    wb = w.get("body") or []
    if len(wb) != 2:
        return None
    # wb[0]: node = stack.pop()
    n0 = wb[0]
    if not (isinstance(n0, dict) and n0.get("stmt") == "Assign"):
        return None
    node_v = n0.get("target")
    nv = n0.get("value") or {}
    if not (isinstance(node_v, str) and nv.get("type") == "Call"
            and nv.get("func") == f"{stack_v}.pop"):
        return None
    # wb[1]: if isinstance(node, dict): <inner> else: if isinstance(node, list): ...
    oif = wb[1]
    if not (isinstance(oif, dict) and oif.get("stmt") == "If"):
        return None
    if not _match_isinstance(oif.get("test"), node_v, "dict"):
        return None
    dbody = oif.get("body") or []
    if len(dbody) != 1:
        return None
    iif = dbody[0]
    if not (isinstance(iif, dict) and iif.get("stmt") == "If"):
        return None
    it = iif.get("test") or {}
    if not (it.get("type") == "BinOp" and it.get("op") == "and"):
        return None
    type_key, type_val = _hde_getkeyval(it.get("left"), node_v)
    func_key, func_val = _hde_getkeyval(it.get("right"), node_v)
    if None in (type_key, type_val, func_key, func_val):
        return None
    # inner then: found = True
    ib = iif.get("body") or []
    if not (len(ib) == 1 and isinstance(ib[0], dict) and ib[0].get("stmt") == "Assign"
            and ib[0].get("target") == found_v and isinstance(ib[0].get("value"), dict)
            and ib[0]["value"].get("type") == "Bool" and ib[0]["value"].get("value") is True):
        return None
    # inner else: stack.extend(node.values())
    io = iif.get("orelse") or []
    if not (len(io) == 1 and isinstance(io[0], dict) and io[0].get("stmt") == "Expr"):
        return None
    ioc = io[0].get("value") or {}
    if not (ioc.get("type") == "Call" and ioc.get("func") == f"{stack_v}.extend"):
        return None
    iov = (ioc.get("args") or [{}])[0]
    if not (isinstance(iov, dict) and iov.get("type") == "Call"
            and iov.get("func") == f"{node_v}.values"):
        return None
    # outer else: if isinstance(node, list): stack.extend(node)
    oo = oif.get("orelse") or []
    if len(oo) != 1:
        return None
    lif = oo[0]
    if not (isinstance(lif, dict) and lif.get("stmt") == "If"
            and _match_isinstance(lif.get("test"), node_v, "list")):
        return None
    lb = lif.get("body") or []
    if not (len(lb) == 1 and isinstance(lb[0], dict) and lb[0].get("stmt") == "Expr"):
        return None
    lbc = lb[0].get("value") or {}
    if not (lbc.get("type") == "Call" and lbc.get("func") == f"{stack_v}.extend"
            and _is_var((lbc.get("args") or [{}])[0], node_v)):
        return None
    # body[3]: return found
    b3 = body[3]
    if not (isinstance(b3, dict) and b3.get("stmt") == "Return" and _is_var(b3.get("value"), found_v)):
        return None
    return {"name": func["name"], "param": fp, "body_key": body_key,
            "type_key": type_key, "type_val": type_val,
            "func_key": func_key, "func_val": func_val}


def emit_has_dynamic_exec_group(desc: Dict[str, Any], whyml_ident) -> List[str]:
    """Emit `_has_dynamic_exec` as a short-circuit recursive existence fold over the
    pyval body tree (the `_test_contains_map` skeleton). `ensures True`; ledger 3."""
    n = whyml_ident(desc["name"])
    P = f"{n}__"
    mv = _pvw_mv(desc["param"])
    tv, fv = desc["type_val"], desc["func_val"]
    out: List[str] = []
    # typed-key readers: body (option pyval, extracts the PList), type/func (option string)
    out += _emit_pval_reader(f"{P}gbody", desc["body_key"])
    out += _emit_skey_reader(f"{P}gtype", desc["type_key"])
    out += _emit_skey_reader(f"{P}gfunc", desc["func_key"])
    # mutual existence fold over pyval / pydict values / list elements
    out.append(f"  let rec {P}walk (v: pyval) : bool")
    out.append("    requires { true } ensures { true } variant { pv_size v }")
    out.append("  = match v with")
    out.append("    | PDict d ->")
    out.append(f'        let is_exec = ((match {P}gtype d with Some t -> pystr_eq t "{tv}" | None -> false end)')
    out.append(f'                       && (match {P}gfunc d with Some fn -> pystr_eq fn "{fv}" | None -> false end)) in')
    out.append(f"        if is_exec then true else {P}dfold d")
    out.append(f"    | PList xs -> {P}lfold xs")
    out.append("    | _ -> false")
    out.append("    end")
    out.append(f"  with {P}dfold (d: pydict) : bool")
    out.append("    requires { true } ensures { true } variant { size_dict d }")
    out.append("  = match d with DNil -> false")
    out.append("    | DCons _ v rest ->")
    out.append("        size_pos v;")
    out.append(f"        {P}walk v || {P}dfold rest end")
    out.append(f"  with {P}lfold (xs: list pyval) : bool")
    out.append("    requires { true } ensures { true } variant { size_list xs }")
    out.append("  = match xs with Nil -> false")
    out.append(f"    | Cons h t -> {P}walk h || {P}lfold t end")
    # entry: walk the elements of func.get(BODY_KEY) (the worklist seed)
    out.append(f"  let {n} (self: functionemissionmixin) ({mv}: pyval) : bool")
    out.append("    requires { true } ensures { true }")
    out.append(f"  = match {mv} with")
    out.append(f"    | PDict d -> (match {P}gbody d with Some (PList xs) -> {P}lfold xs | _ -> false end)")
    out.append("    | _ -> false")
    out.append("    end")
    return out


# ---- `_func_returns_string_seq` (preamble.py PreambleEmissionMixin): does a function's
# body tree contain a `Return <Var>` whose returned local is STRING-typed
# (`seq_value_types[name] == "string"`)? The LIVE body is a `found=[False]` nested-`def
# rec` closure existence walk over `func.get("body")`, driven by a LEADING guard
# `svt = func.get("seq_value_types", {}); if not svt: return False`. Module 5 lambda-lifts
# the nested `rec` to an ADJACENT sibling function (`<cls>__rec`) sharing `found` as an
# int-erased global — a vacuous facade under the generic lowering. This is boundary-A: it
# differs from the plain `closure_existence` wrapper in TWO ways that make it its own
# recognizer — (i) the outer has a 5-statement svt-guarded shape (not the bare
# `[acc=[False], walk(subj), return acc[0]]`), and (ii) the discriminant is a NESTED
# COMPUTED-KEY predicate `svt.get(v.get("name")) == "string"` that INSPECTS the value of
# `svt` at a key drawn from a nested field. The DECISIVE non-vacuity rule: `svt` is
# threaded as a real `pydict` and its value is read (`{P}gsv nm svt`), NOT an opaque
# membership set — an opaque leaf would be a Gate-C facade. The pair emits the OUTER as a
# mutual `list pyval`/`pyval`/`pydict` existence catamorphism (the `has_dynamic_exec`
# skeleton) with `svt` threaded UNCHANGED as a non-variant parameter; the lifted `rec`
# sibling is SUPPRESSED. `found[0]=True`-on-first-match is (trivially, under `ensures
# True`) the `∃ matching node` disjunction. Non-facade: every field key and tag literal is
# reflected structurally from the body (a body change moves the emitted .mlw). Fail-closed:
# any deviation stays `\trusted`. `ensures True`; ledger 3 (reuses the certified
# pyval/pydict ADT — no new type/axiom/cert).

def _frss_dotget_key(node: Any, recv: str) -> Optional[str]:
    """`<recv>.get("<k>"[, default])` -> clean literal k (first arg), else None.
    Tolerates the optional `.get(key, default)` default arg (`func.get("body", [])`)."""
    if not (isinstance(node, dict) and node.get("type") == "Call"
            and node.get("func") == f"{recv}.get"):
        return None
    args = node.get("args") or []
    if len(args) < 1:
        return None
    return _clean_lit(_is_string(args[0]))


def _recognize_frss_outer(func: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    """Match the OUTER `_func_returns_string_seq` wrapper. Fail-closed; None on any
    deviation. Returns {name, param, svt_v, svt_key, body_key, found_v, walker_name}."""
    if not func.get("name", "").endswith("_func_returns_string_seq"):
        return None
    if func.get("return_annotation") not in ("bool", None):
        return None
    params = func.get("formal_params") or []
    if len(params) != 1:
        return None
    func_p = params[0]
    body = func.get("body") or []
    if len(body) != 5:
        return None
    # [0] svt = func.get("<svt_key>", {})
    b0 = body[0]
    if not (isinstance(b0, dict) and b0.get("stmt") == "Assign"):
        return None
    svt_v = b0.get("target")
    av = b0.get("value") or {}
    if not (isinstance(av, dict) and av.get("type") == "Call"
            and av.get("func") == f"{func_p}.get"):
        return None
    a0 = av.get("args") or []
    if not a0:
        return None
    svt_key = _clean_lit(_is_string(a0[0]))
    if svt_key is None or not isinstance(svt_v, str):
        return None
    # [1] if not svt: return False
    b1 = body[1]
    if not (isinstance(b1, dict) and b1.get("stmt") == "If" and not b1.get("orelse")):
        return None
    t1 = b1.get("test") or {}
    if not (isinstance(t1, dict) and t1.get("type") == "UnaryOp" and t1.get("op") == "not"
            and _is_var(t1.get("expr"), svt_v)):
        return None
    g1 = b1.get("body") or []
    if not (len(g1) == 1 and isinstance(g1[0], dict) and g1[0].get("stmt") == "Return"
            and isinstance(g1[0].get("value"), dict)
            and g1[0]["value"].get("type") == "Bool"
            and g1[0]["value"].get("value") is False):
        return None
    # [2] found = [False]
    b2 = body[2]
    if not (isinstance(b2, dict) and b2.get("stmt") == "Assign"
            and isinstance(b2.get("value"), dict)
            and b2["value"].get("type") == "ArrayLit"):
        return None
    elts = b2["value"].get("elts") or []
    if not (len(elts) == 1 and isinstance(elts[0], dict)
            and elts[0].get("type") == "Bool" and elts[0].get("value") is False):
        return None
    found_v = b2.get("target")
    if not isinstance(found_v, str):
        return None
    # [3] rec(func.get("<body_key>", []))
    b3 = body[3]
    if not (isinstance(b3, dict) and b3.get("stmt") == "Expr"):
        return None
    call = b3.get("value") or {}
    if not (isinstance(call, dict) and call.get("type") == "Call"
            and isinstance(call.get("func"), str)):
        return None
    walker_name = call["func"]
    cargs = call.get("args") or []
    if len(cargs) != 1:
        return None
    body_key = _frss_dotget_key(cargs[0], func_p)
    if body_key is None:
        return None
    # [4] return found[0]
    b4 = body[4]
    if not (isinstance(b4, dict) and b4.get("stmt") == "Return"
            and _clx_match_acc_subscript(b4.get("value"), found_v)):
        return None
    return {"name": func.get("name"), "param": func_p, "svt_v": svt_v,
            "svt_key": svt_key, "body_key": body_key,
            "found_v": found_v, "walker_name": walker_name}


def _frss_iter_selfcall(node: Any, call_names: "set", subj: str, iter_ok) -> bool:
    """`for <lv> in <iter>: <rec>(<lv>)` — a bare descent loop whose sole body stmt is a
    self-call (func in `call_names`) on the bound var, iterable satisfying `iter_ok`.
    Like `_clx_walk_iter_selfcall` but accepts a SET of acceptable call-func names
    (the recursive call uses the UNQUALIFIED local name `rec`, the lifted def is
    class-qualified)."""
    if not (isinstance(node, dict) and node.get("stmt") == "For"):
        return False
    if not iter_ok(node.get("iter", {})):
        return False
    lv = node.get("target")
    if not isinstance(lv, str):
        return False
    lb = node.get("body", [])
    if len(lb) != 1:
        return False
    s = lb[0]
    if not (isinstance(s, dict) and s.get("stmt") == "Expr"):
        return False
    call = s.get("value", {})
    return (isinstance(call, dict) and call.get("type") == "Call"
            and call.get("func") in call_names
            and len(call.get("args", [])) == 1
            and _is_var(call["args"][0], lv))


def _recognize_frss_walk(walkfunc: Dict[str, Any], svt_v: str, acc: str,
                         call_names: "set") -> Optional[Dict[str, Any]]:
    """Match the lifted `rec(node)` walk and extract the leaf discriminant literals.
    Fail-closed. `call_names` is the set of acceptable recursive-call func names (the
    unqualified local `rec` and the class-qualified lifted def name). Returns
    {stmt_key, stmt_val, value_key, type_key, type_val, name_key, svt_match_val}
    or None."""
    params = walkfunc.get("formal_params") or []
    if len(params) != 1:
        return None
    node = params[0]
    body = walkfunc.get("body") or []
    if len(body) != 1:
        return None
    top = body[0]
    # if isinstance(node, dict): <dict-arm> elif isinstance(node, list): ...
    if not (isinstance(top, dict) and top.get("stmt") == "If"
            and _match_isinstance(top.get("test"), node, "dict")):
        return None
    darm = top.get("body") or []
    if len(darm) != 2:
        return None
    # darm[0]: if node.get(stmt_key) == stmt_val: [v = node.get(value_key), If <leaf>: found[0]=True]
    g = darm[0]
    if not (isinstance(g, dict) and g.get("stmt") == "If" and not g.get("orelse")):
        return None
    gt = g.get("test") or {}
    if not (isinstance(gt, dict) and gt.get("type") == "BinOp" and gt.get("op") == "=="):
        return None
    stmt_key = _frss_dotget_key(gt.get("left"), node)
    stmt_val = _clean_lit(_is_string(gt.get("right")))
    if stmt_key is None or stmt_val is None:
        return None
    gb = g.get("body") or []
    if len(gb) != 2:
        return None
    # gb[0]: v = node.get(value_key)
    a = gb[0]
    if not (isinstance(a, dict) and a.get("stmt") == "Assign"):
        return None
    v_v = a.get("target")
    value_key = _frss_dotget_key(a.get("value"), node)
    if not isinstance(v_v, str) or value_key is None:
        return None
    # gb[1]: If (isinstance(v,dict) and v.get(type_key)==type_val
    #            and svt.get(v.get(name_key))==svt_match_val): [found[0]=True]
    lif = gb[1]
    if not (isinstance(lif, dict) and lif.get("stmt") == "If" and not lif.get("orelse")):
        return None
    lt = lif.get("test") or {}
    if not (isinstance(lt, dict) and lt.get("type") == "BinOp" and lt.get("op") == "and"):
        return None
    left = lt.get("left") or {}
    right = lt.get("right") or {}
    if not (isinstance(left, dict) and left.get("type") == "BinOp"
            and left.get("op") == "and"):
        return None
    # left.left: isinstance(v, dict)
    if not _match_isinstance(left.get("left"), v_v, "dict"):
        return None
    # left.right: v.get(type_key) == type_val
    lr = left.get("right") or {}
    if not (isinstance(lr, dict) and lr.get("type") == "BinOp" and lr.get("op") == "=="):
        return None
    type_key = _frss_dotget_key(lr.get("left"), v_v)
    type_val = _clean_lit(_is_string(lr.get("right")))
    if type_key is None or type_val is None:
        return None
    # right: svt.get(v.get(name_key)) == svt_match_val
    if not (isinstance(right, dict) and right.get("type") == "BinOp"
            and right.get("op") == "=="):
        return None
    svt_match_val = _clean_lit(_is_string(right.get("right")))
    sget = right.get("left") or {}
    if not (isinstance(sget, dict) and sget.get("type") == "Call"
            and sget.get("func") == f"{svt_v}.get"):
        return None
    sga = sget.get("args") or []
    if len(sga) != 1:
        return None
    name_key = _frss_dotget_key(sga[0], v_v)
    if name_key is None or svt_match_val is None:
        return None
    # anti-facade: the guard body sets the accumulator (its whole point)
    if not _clx_has_acc_set(lif.get("body"), acc):
        return None
    # darm[1]: for x in node.values(): rec(x)
    def _values_iter(it: Any) -> bool:
        return (isinstance(it, dict) and it.get("type") == "Call"
                and it.get("func") == f"{node}.values" and not it.get("args"))

    if not _frss_iter_selfcall(darm[1], call_names, node, _values_iter):
        return None
    # elif isinstance(node, list): for x in node: rec(x)
    orelse = top.get("orelse") or []
    if len(orelse) != 1:
        return None
    lif2 = orelse[0]
    if not (isinstance(lif2, dict) and lif2.get("stmt") == "If"
            and not lif2.get("orelse")
            and _match_isinstance(lif2.get("test"), node, "list")):
        return None
    lb = lif2.get("body") or []
    if len(lb) != 1:
        return None
    if not _frss_iter_selfcall(lb[0], call_names, node, lambda it: _is_var(it, node)):
        return None
    return {"stmt_key": stmt_key, "stmt_val": stmt_val, "value_key": value_key,
            "type_key": type_key, "type_val": type_val, "name_key": name_key,
            "svt_match_val": svt_match_val}


def recognize_func_returns_string_seq_pairs(functions: List[Dict[str, Any]]
                                            ) -> Dict[str, Any]:
    """Pair the `_func_returns_string_seq` OUTER wrapper with its lifted `rec` sibling
    (by adjacency — the walk directly follows the wrapper). Returns
    {"outer_ids": {id(outer): desc}, "walk_ids": {id(walk), ...}}. Never raises."""
    outer_ids: Dict[int, Dict[str, Any]] = {}
    walk_ids = set()
    try:
        n = len(functions)
        for i, f in enumerate(functions):
            if not isinstance(f, dict):
                continue
            try:
                od = _recognize_frss_outer(f)
            except Exception:
                od = None
            if od is None:
                continue
            if i + 1 >= n:
                continue
            wf = functions[i + 1]
            wn = od["walker_name"]
            wf_name = wf.get("name") if isinstance(wf, dict) else None
            # the lifted `rec` def is class-qualified (`<cls>__rec`) while the outer's
            # call + the recursive self-calls use the unqualified local name `rec`.
            if not (isinstance(wf, dict)
                    and (wf_name == wn or wf_name.endswith("__" + wn))):
                continue
            if id(wf) in walk_ids:
                continue
            call_names = {wn, wf_name}
            try:
                leaf = _recognize_frss_walk(wf, od["svt_v"], od["found_v"], call_names)
            except Exception:
                leaf = None
            if leaf is None:
                continue
            desc = {"name": od["name"], "param": od["param"],
                    "svt_key": od["svt_key"], "body_key": od["body_key"]}
            desc.update(leaf)
            outer_ids[id(f)] = desc
            walk_ids.add(id(wf))
    except Exception:
        return {"outer_ids": {}, "walk_ids": set()}
    return {"outer_ids": outer_ids, "walk_ids": walk_ids}


def emit_func_returns_string_seq_group(func: Dict[str, Any], desc: Dict[str, Any],
                                       whyml_ident) -> List[str]:
    """Emit `_func_returns_string_seq` as a mutual `pyval`/`pydict`/`list pyval`
    existence catamorphism (the `has_dynamic_exec` skeleton) with `svt` threaded
    UNCHANGED as a non-variant `pydict` parameter and inspected by a real read
    (`{P}gsv nm svt`). `ensures True`; ledger 3 (no new type/axiom/cert)."""
    n = whyml_ident(desc["name"])
    P = f"{n}__"
    mv = _pvw_mv(desc["param"])
    sv, tv, mval = desc["stmt_val"], desc["type_val"], desc["svt_match_val"]
    out: List[str] = []
    # literal-key readers (typed irkey ctor or the K_dyn guard, per key)
    out += _emit_pval_reader(f"{P}gsvt", desc["svt_key"])    # option pyval: the svt dict
    out += _emit_pval_reader(f"{P}gbody", desc["body_key"])  # option pyval: the body list
    out += _emit_skey_reader(f"{P}gstmt", desc["stmt_key"])  # option string
    out += _emit_pval_reader(f"{P}gval", desc["value_key"])  # option pyval: the value node
    out += _emit_skey_reader(f"{P}gtype", desc["type_key"])  # option string
    out += _emit_skey_reader(f"{P}gname", desc["name_key"])  # option string: the var name
    # dynamic-string-keyed reader over svt: `svt.get(nm)` -> option string (K_dyn keys)
    out.append(f"  let rec {P}gsv (nm: string) (d: pydict) : option string")
    out.append("    variant { d }")
    out.append("  = match d with")
    out.append("    | DNil -> None")
    out.append(f"    | DCons (K_dyn s) (PStr t) rest -> "
               f"if pystr_eq nm s then Some t else {P}gsv nm rest")
    out.append(f"    | DCons _ _ rest -> {P}gsv nm rest")
    out.append("    end")
    # leaf: the `Return <string-typed Var>` discriminant (real svt value read)
    out.append(f"  let {P}leaf (d: pydict) (svt: pydict) : bool")
    out.append("    requires { true } ensures { true }")
    out.append(f'  = (match {P}gstmt d with Some st -> pystr_eq st "{sv}" | None -> false end)')
    out.append(f"    && (match {P}gval d with")
    out.append("        | Some (PDict vd) ->")
    out.append(f'            (match {P}gtype vd with Some ty -> pystr_eq ty "{tv}" '
               f"| None -> false end)")
    out.append(f"            && (match {P}gname vd with")
    out.append(f"                | Some nm -> (match {P}gsv nm svt with "
               f'Some tvv -> pystr_eq tvv "{mval}" | None -> false end)')
    out.append("                | None -> false end)")
    out.append("        | _ -> false end)")
    # mutual existence fold; svt threaded UNCHANGED and OUT of the variant
    out.append(f"  let rec {P}v (v: pyval) (svt: pydict) : bool")
    out.append("    requires { true } ensures { true } variant { pv_size v }")
    out.append("  = match v with")
    out.append(f"    | PDict d -> {P}leaf d svt || {P}dfold d svt")
    out.append(f"    | PList xs -> {P}lfold xs svt")
    out.append("    | _ -> false")
    out.append("    end")
    out.append(f"  with {P}dfold (d: pydict) (svt: pydict) : bool")
    out.append("    requires { true } ensures { true } variant { size_dict d }")
    out.append("  = match d with DNil -> false")
    out.append("    | DCons _ v rest ->")
    out.append("        size_pos v;")
    out.append(f"        {P}v v svt || {P}dfold rest svt end")
    out.append(f"  with {P}lfold (xs: list pyval) (svt: pydict) : bool")
    out.append("    requires { true } ensures { true } variant { size_list xs }")
    out.append("  = match xs with Nil -> false")
    out.append(f"    | Cons h t -> {P}v h svt || {P}lfold t svt end")
    # entry: extract svt + the body list from func, then fold the body list
    out.append(f"  let {n} ({mv}: pyval) : bool")
    out.append("    requires { true } ensures { true }")
    out.append(f"  = match {mv} with")
    out.append("    | PDict fd ->")
    out.append(f"        let svt = (match {P}gsvt fd with Some (PDict sd) -> sd "
               "| _ -> DNil end) in")
    out.append(f"        (match {P}gbody fd with Some (PList xs) -> {P}lfold xs svt "
               "| _ -> false end)")
    out.append("    | _ -> false")
    out.append("    end")
    return out


# ---- `_returns_string_seq` (functions.py FunctionEmissionMixin INSTANCE method):
# the SELF-STATE sibling of `_func_returns_string_seq`. BYTE-IDENTICAL body EXCEPT two
# points: (i) `svt` is bound from the SELF field via `getattr(self,"_seq_value_types",{})`
# (not the param `func.get("seq_value_types",{})`), and (ii) the walk is seeded with the
# PARAM `body_stmts` DIRECTLY (`rec(body_stmts)`) — the subject is a real list, not
# `func.get("body",[])`. Both wrappers share the SAME lifted `rec` leaf grammar, so the
# walk is matched by the SHARED `_recognize_frss_walk`. Self-field modeling = strategy 2
# (self-dict-as-real-source): `_seq_value_types` becomes an opaque-but-REAL
# `val <n>__svt (self):pydict` returning a real pydict that is then REALLY walked by the
# computed-key reader `<P>gsv nm svt` (`pystr_eq`) — NOT an opaque membership set. Strategy
# 1 (self-as-record) does NOT fit: `FunctionEmissionMixin` is emitted as
# `type functionemissionmixin = int` (an opaque int alias, no `_seq_value_types` field).
# Non-facade: every field key and tag literal is reflected structurally from the body (a
# body change moves the emitted .mlw) and svt is REALLY read cell-by-cell. Fail-closed: any
# deviation stays `\trusted`. The lifted `rec` sibling is SUPPRESSED. `ensures True`;
# ledger 3 (reuses the certified pyval/pydict ADT — no new type/axiom/cert).

def _recognize_rss_outer(func: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    """Match the OUTER `_returns_string_seq` wrapper. Like `_func_returns_string_seq`
    EXCEPT body[0] is `svt = getattr(self,"_seq_value_types",{})` and body[3] is
    `rec(<param>)` (the bare param Var, not `func.get(...)`). Fail-closed; None on any
    deviation. Returns {name, param, self_type, svt_v, svt_field, found_v, walker_name}."""
    nm = func.get("name", "")
    # name-gate: `_returns_string_seq` but NOT its `_func_returns_string_seq` sibling
    if not (nm.endswith("_returns_string_seq")
            and not nm.endswith("_func_returns_string_seq")):
        return None
    if func.get("return_annotation") not in ("bool", None):
        return None
    params = func.get("formal_params") or []
    if len(params) != 1:
        return None
    subj_p = params[0]
    body = func.get("body") or []
    if len(body) != 5:
        return None
    # [0] svt = getattr(self, "_seq_value_types", {})
    ga = _match_getattr_bind(body[0])
    if ga is None:
        return None
    svt_v, svt_field = ga
    # [1] if not svt: return False
    b1 = body[1]
    if not (isinstance(b1, dict) and b1.get("stmt") == "If" and not b1.get("orelse")):
        return None
    t1 = b1.get("test") or {}
    if not (isinstance(t1, dict) and t1.get("type") == "UnaryOp" and t1.get("op") == "not"
            and _is_var(t1.get("expr"), svt_v)):
        return None
    g1 = b1.get("body") or []
    if not (len(g1) == 1 and isinstance(g1[0], dict) and g1[0].get("stmt") == "Return"
            and isinstance(g1[0].get("value"), dict)
            and g1[0]["value"].get("type") == "Bool"
            and g1[0]["value"].get("value") is False):
        return None
    # [2] found = [False]
    b2 = body[2]
    if not (isinstance(b2, dict) and b2.get("stmt") == "Assign"
            and isinstance(b2.get("value"), dict)
            and b2["value"].get("type") == "ArrayLit"):
        return None
    elts = b2["value"].get("elts") or []
    if not (len(elts) == 1 and isinstance(elts[0], dict)
            and elts[0].get("type") == "Bool" and elts[0].get("value") is False):
        return None
    found_v = b2.get("target")
    if not isinstance(found_v, str):
        return None
    # [3] rec(body_stmts)  — the bare param Var (subject walked directly)
    b3 = body[3]
    if not (isinstance(b3, dict) and b3.get("stmt") == "Expr"):
        return None
    call = b3.get("value") or {}
    if not (isinstance(call, dict) and call.get("type") == "Call"
            and isinstance(call.get("func"), str)):
        return None
    walker_name = call["func"]
    cargs = call.get("args") or []
    if not (len(cargs) == 1 and _is_var(cargs[0], subj_p)):
        return None
    # [4] return found[0]
    b4 = body[4]
    if not (isinstance(b4, dict) and b4.get("stmt") == "Return"
            and _clx_match_acc_subscript(b4.get("value"), found_v)):
        return None
    return {"name": func.get("name"), "param": subj_p,
            "self_type": func.get("self_type"), "svt_v": svt_v, "svt_field": svt_field,
            "found_v": found_v, "walker_name": walker_name}


def recognize_returns_string_seq_pairs(functions: List[Dict[str, Any]]
                                       ) -> Dict[str, Any]:
    """Pair the `_returns_string_seq` OUTER wrapper with its lifted `rec` sibling (by
    adjacency). Reuses the SHARED `_recognize_frss_walk` leaf grammar. Returns
    {"outer_ids": {id(outer): desc}, "walk_ids": {id(walk), ...}}. Never raises."""
    outer_ids: Dict[int, Dict[str, Any]] = {}
    walk_ids = set()
    try:
        n = len(functions)
        for i, f in enumerate(functions):
            if not isinstance(f, dict):
                continue
            try:
                od = _recognize_rss_outer(f)
            except Exception:
                od = None
            if od is None:
                continue
            if i + 1 >= n:
                continue
            wf = functions[i + 1]
            wn = od["walker_name"]
            wf_name = wf.get("name") if isinstance(wf, dict) else None
            if not (isinstance(wf, dict) and isinstance(wf_name, str)
                    and (wf_name == wn or wf_name.endswith("__" + wn))):
                continue
            if id(wf) in walk_ids:
                continue
            call_names = {wn, wf_name}
            try:
                leaf = _recognize_frss_walk(wf, od["svt_v"], od["found_v"], call_names)
            except Exception:
                leaf = None
            if leaf is None:
                continue
            desc = {"name": od["name"], "param": od["param"],
                    "self_type": od["self_type"], "svt_field": od["svt_field"]}
            desc.update(leaf)
            outer_ids[id(f)] = desc
            walk_ids.add(id(wf))
    except Exception:
        return {"outer_ids": {}, "walk_ids": set()}
    return {"outer_ids": outer_ids, "walk_ids": walk_ids}


def emit_returns_string_seq_group(func: Dict[str, Any], desc: Dict[str, Any],
                                  whyml_ident) -> List[str]:
    """Emit `_returns_string_seq` as the SAME mutual pyval/pydict/list existence
    catamorphism as `_func_returns_string_seq`, with two differences: (i) `svt` is sourced
    from the self-state field `_seq_value_types` via an opaque-but-real
    `val <n>__svt (self):pydict` (a real pydict, REALLY read by `<P>gsv`), and (ii) the
    walk is seeded with the PARAM `body_stmts` (a real PList) directly. `ensures True`;
    ledger 3 (no new type/axiom/cert)."""
    n = whyml_ident(desc["name"])
    P = f"{n}__"
    mv = _pvw_mv(desc["param"])
    st = desc.get("self_type")
    self_type = whyml_ident(st.lower()) if st else "functionemissionmixin"
    sv, tv, mval = desc["stmt_val"], desc["type_val"], desc["svt_match_val"]
    out: List[str] = []
    # literal-key readers (typed irkey ctor or the K_dyn guard, per key)
    out += _emit_skey_reader(f"{P}gstmt", desc["stmt_key"])  # option string
    out += _emit_pval_reader(f"{P}gval", desc["value_key"])  # option pyval: the value node
    out += _emit_skey_reader(f"{P}gtype", desc["type_key"])  # option string
    out += _emit_skey_reader(f"{P}gname", desc["name_key"])  # option string: the var name
    # dynamic-string-keyed reader over svt: `svt.get(nm)` -> option string (K_dyn keys)
    out.append(f"  let rec {P}gsv (nm: string) (d: pydict) : option string")
    out.append("    variant { d }")
    out.append("  = match d with")
    out.append("    | DNil -> None")
    out.append(f"    | DCons (K_dyn s) (PStr t) rest -> "
               f"if pystr_eq nm s then Some t else {P}gsv nm rest")
    out.append(f"    | DCons _ _ rest -> {P}gsv nm rest")
    out.append("    end")
    # self-field source (strategy 2): the `_seq_value_types` self-dict as an
    # opaque-but-REAL pydict — no spec, so an arbitrary real pydict, REALLY read by gsv.
    out.append(f"  val {P}svt (self: {self_type}) : pydict")
    # leaf: the `Return <string-typed Var>` discriminant (real svt value read)
    out.append(f"  let {P}leaf (d: pydict) (svt: pydict) : bool")
    out.append("    requires { true } ensures { true }")
    out.append(f'  = (match {P}gstmt d with Some st -> pystr_eq st "{sv}" | None -> false end)')
    out.append(f"    && (match {P}gval d with")
    out.append("        | Some (PDict vd) ->")
    out.append(f'            (match {P}gtype vd with Some ty -> pystr_eq ty "{tv}" '
               f"| None -> false end)")
    out.append(f"            && (match {P}gname vd with")
    out.append(f"                | Some nm -> (match {P}gsv nm svt with "
               f'Some tvv -> pystr_eq tvv "{mval}" | None -> false end)')
    out.append("                | None -> false end)")
    out.append("        | _ -> false end)")
    # mutual existence fold; svt threaded UNCHANGED and OUT of the variant
    out.append(f"  let rec {P}v (v: pyval) (svt: pydict) : bool")
    out.append("    requires { true } ensures { true } variant { pv_size v }")
    out.append("  = match v with")
    out.append(f"    | PDict d -> {P}leaf d svt || {P}dfold d svt")
    out.append(f"    | PList xs -> {P}lfold xs svt")
    out.append("    | _ -> false")
    out.append("    end")
    out.append(f"  with {P}dfold (d: pydict) (svt: pydict) : bool")
    out.append("    requires { true } ensures { true } variant { size_dict d }")
    out.append("  = match d with DNil -> false")
    out.append("    | DCons _ v rest ->")
    out.append("        size_pos v;")
    out.append(f"        {P}v v svt || {P}dfold rest svt end")
    out.append(f"  with {P}lfold (xs: list pyval) (svt: pydict) : bool")
    out.append("    requires { true } ensures { true } variant { size_list xs }")
    out.append("  = match xs with Nil -> false")
    out.append(f"    | Cons h t -> {P}v h svt || {P}lfold t svt end")
    # entry: svt from self-state, then fold the PARAM body list directly
    out.append(f"  let {n} (self: {self_type}) ({mv}: pyval) : bool")
    out.append("    requires { true } ensures { true }")
    out.append(f"  = let svt = {P}svt self in")
    out.append(f"    match {mv} with")
    out.append(f"    | PList xs -> {P}lfold xs svt")
    out.append("    | _ -> false")
    out.append("    end")
    return out


# ---- `_class_inv_refs_axiom_func` (preamble.py PreambleEmissionMixin INSTANCE method):
# the nonlocal-scalar-`hit` twin of `_func_returns_string_seq`. True iff some `#@ class
# invariant` IR node applies an axiom-backing logic function (`_axiom_logic_funcs`). The
# LIVE body is a `hit=False`/`nonlocal hit` nested-`def _walk` existence walk over the
# DOUBLE loop `ir["type_decls"][*]["class_invariants"]`, whose leaf is a MEMBERSHIP test
# `node.get("type")=="Call" and node.get("func") in axiom_fns`. Module 5 lambda-lifts the
# nested `_walk` to an ADJACENT `<cls>___walk` sibling. Boundary-A: differs from frss in
# TWO ways — (i) the accumulator is a SCALAR `hit=False`/`hit=True` (NOT a `found=[False]`
# heap ref), lowered directly to the `||` short-circuit existence disjunction, and (ii) the
# discriminant is a `Map.get`-MEMBERSHIP (`node.get("func") in axiom_fns`), NOT a computed
# dict-value read. `_axiom_logic_funcs` (populated by the \trusted `_precompute_axiom_
# logic_funcs`) is modeled as a genuinely-unmodeled self-source `val <n>__axset (self):
# map string bool` — opaque-but-REAL (ensures-free = a sound over-approximation, NOT an
# axiom; Gate-C-legal for an unmodeled self-source). The walked SPINE stays REAL: the
# `type_decls`/`class_invariants` navigation (`__tdfold`), the pyval/pydict/list existence
# catamorphism (`__v/__dfold/__lfold`, variants pv_size/size_dict/size_list), the tag
# literal (`"Call"`) and the `func` membership are all read structurally (a leaf-tag change
# moves the emitted .mlw). Fail-closed: any deviation stays `\trusted`. The lifted `_walk`
# is SUPPRESSED. `ensures True`; ledger 3 (reuses the certified pyval/pydict ADT — no new
# type/axiom/cert).

def _match_not_guard_return_false(stmt: Any, var: str) -> bool:
    """`if not <var>: return False` (no else)."""
    if not (isinstance(stmt, dict) and stmt.get("stmt") == "If" and not stmt.get("orelse")):
        return False
    t = stmt.get("test") or {}
    if not (isinstance(t, dict) and t.get("type") == "UnaryOp" and t.get("op") == "not"
            and _is_var(t.get("expr"), var)):
        return False
    g = stmt.get("body") or []
    return (len(g) == 1 and isinstance(g[0], dict) and g[0].get("stmt") == "Return"
            and isinstance(g[0].get("value"), dict)
            and g[0]["value"].get("type") == "Bool"
            and g[0]["value"].get("value") is False)


def _match_hit_false(stmt: Any) -> Optional[str]:
    """`<hit> = False` (scalar Bool assign) -> hit or None."""
    if not (isinstance(stmt, dict) and stmt.get("stmt") == "Assign"):
        return None
    v = stmt.get("value") or {}
    if not (isinstance(v, dict) and v.get("type") == "Bool" and v.get("value") is False):
        return None
    t = stmt.get("target")
    return t if isinstance(t, str) else None


def _cira_body_sets_hit(body: Any, hit_v: str) -> bool:
    """`<hit> = True` (scalar Bool assign) appears among `body`'s statements."""
    if not isinstance(body, list):
        return False
    for s in body:
        if (isinstance(s, dict) and s.get("stmt") == "Assign" and s.get("target") == hit_v
                and isinstance(s.get("value"), dict) and s["value"].get("type") == "Bool"
                and s["value"].get("value") is True):
            return True
    return False


def _cira_walk_call_on(stmt: Any, lv: str) -> Optional[str]:
    """`<name>(<lv>)` bare Expr-call on the bound var -> name, else None."""
    if not (isinstance(stmt, dict) and stmt.get("stmt") == "Expr"):
        return None
    call = stmt.get("value") or {}
    if not (isinstance(call, dict) and call.get("type") == "Call"
            and isinstance(call.get("func"), str)):
        return None
    args = call.get("args") or []
    if not (len(args) == 1 and _is_var(args[0], lv)):
        return None
    return call["func"]


def _match_cira_double_for(stmt: Any, ir_p: str) -> Optional[Tuple[str, str, str]]:
    """`for td in ir.get("<td_key>",[]): for inv in td.get("<ci_key>",[]): <walk>(inv)`.
    Returns (td_key, ci_key, walker_name) or None."""
    if not (isinstance(stmt, dict) and stmt.get("stmt") == "For"):
        return None
    td_key = _frss_dotget_key(stmt.get("iter"), ir_p)
    td = stmt.get("target")
    if td_key is None or not isinstance(td, str):
        return None
    ob = stmt.get("body") or []
    if len(ob) != 1:
        return None
    inner = ob[0]
    if not (isinstance(inner, dict) and inner.get("stmt") == "For"):
        return None
    ci_key = _frss_dotget_key(inner.get("iter"), td)
    inv = inner.get("target")
    if ci_key is None or not isinstance(inv, str):
        return None
    ib = inner.get("body") or []
    if len(ib) != 1:
        return None
    wn = _cira_walk_call_on(ib[0], inv)
    if wn is None:
        return None
    return (td_key, ci_key, wn)


def _match_call_in_axset(test: Any, node: str, ax_v: str) -> Optional[Dict[str, str]]:
    """`node.get("<type_key>") == "<tag>" and node.get("<func_key>") in <ax_v>`.
    Returns {type_key, tag, func_key} or None."""
    if not (isinstance(test, dict) and test.get("type") == "BinOp" and test.get("op") == "and"):
        return None
    left = test.get("left") or {}
    right = test.get("right") or {}
    if not (isinstance(left, dict) and left.get("type") == "BinOp" and left.get("op") == "=="):
        return None
    type_key = _frss_dotget_key(left.get("left"), node)
    tag = _clean_lit(_is_string(left.get("right")))
    if type_key is None or tag is None:
        return None
    if not (isinstance(right, dict) and right.get("type") == "BinOp"
            and right.get("op") == "in" and _is_var(right.get("right"), ax_v)):
        return None
    func_key = _frss_dotget_key(right.get("left"), node)
    if func_key is None:
        return None
    return {"type_key": type_key, "tag": tag, "func_key": func_key}


def _recognize_cira_outer(func: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    """Match the OUTER `_class_inv_refs_axiom_func` wrapper (5-stmt). Fail-closed."""
    if not func.get("name", "").endswith("_class_inv_refs_axiom_func"):
        return None
    if func.get("return_annotation") not in ("bool", None):
        return None
    params = func.get("formal_params") or []
    if len(params) != 1:
        return None
    ir_p = params[0]
    body = func.get("body") or []
    if len(body) != 5:
        return None
    # [0] axiom_fns = getattr(self, "_axiom_logic_funcs", set())
    ga = _match_getattr_bind(body[0])
    if ga is None:
        return None
    ax_v, ax_field = ga
    # [1] if not axiom_fns: return False
    if not _match_not_guard_return_false(body[1], ax_v):
        return None
    # [2] hit = False
    hit_v = _match_hit_false(body[2])
    if hit_v is None:
        return None
    # [3] double For seeded on ir->td->inv, inner body is the walk-call
    dd = _match_cira_double_for(body[3], ir_p)
    if dd is None:
        return None
    td_key, ci_key, walker_name = dd
    # [4] return hit
    b4 = body[4]
    if not (isinstance(b4, dict) and b4.get("stmt") == "Return"
            and _is_var(b4.get("value"), hit_v)):
        return None
    return {"name": func.get("name"), "param": ir_p, "self_type": func.get("self_type"),
            "ax_field": ax_field, "ax_v": ax_v, "hit_v": hit_v,
            "td_key": td_key, "ci_key": ci_key, "walker_name": walker_name}


def _recognize_cira_walk(walkfunc: Dict[str, Any], ax_v: str, hit_v: str,
                         call_names: "set") -> Optional[Dict[str, str]]:
    """Match the lifted `_walk(node)` (2-stmt: `if hit: return`; isinstance dispatch with
    the single Call-in-axset leaf). Returns {type_key, tag, func_key} or None."""
    params = walkfunc.get("formal_params") or []
    if len(params) != 1:
        return None
    node = params[0]
    body = walkfunc.get("body") or []
    if len(body) != 2:
        return None
    g0, disp = body
    # [0] if hit: return
    if not (isinstance(g0, dict) and g0.get("stmt") == "If" and not g0.get("orelse")
            and _is_var(g0.get("test"), hit_v)):
        return None
    gb = g0.get("body") or []
    if not (len(gb) == 1 and isinstance(gb[0], dict) and gb[0].get("stmt") == "Return"
            and gb[0].get("value") is None):
        return None
    # [1] if isinstance(node, dict): [leaf; for v in node.values(): walk(v)]
    #     elif isinstance(node, list): for v in node: walk(v)
    if not (isinstance(disp, dict) and disp.get("stmt") == "If"
            and _match_isinstance(disp.get("test"), node, "dict")):
        return None
    darm = disp.get("body") or []
    if len(darm) != 2:
        return None
    leafif, valloop = darm
    if not (isinstance(leafif, dict) and leafif.get("stmt") == "If"
            and not leafif.get("orelse")):
        return None
    parsed = _match_call_in_axset(leafif.get("test"), node, ax_v)
    if parsed is None:
        return None
    if not _cira_body_sets_hit(leafif.get("body"), hit_v):
        return None

    def _values_iter(it: Any) -> bool:
        return (isinstance(it, dict) and it.get("type") == "Call"
                and it.get("func") == f"{node}.values" and not it.get("args"))

    if not _frss_iter_selfcall(valloop, call_names, node, _values_iter):
        return None
    orelse = disp.get("orelse") or []
    if len(orelse) != 1:
        return None
    lif2 = orelse[0]
    if not (isinstance(lif2, dict) and lif2.get("stmt") == "If" and not lif2.get("orelse")
            and _match_isinstance(lif2.get("test"), node, "list")):
        return None
    lb = lif2.get("body") or []
    if len(lb) != 1:
        return None
    if not _frss_iter_selfcall(lb[0], call_names, node, lambda it: _is_var(it, node)):
        return None
    return parsed


def recognize_class_inv_refs_axiom_pairs(functions: List[Dict[str, Any]]
                                         ) -> Dict[str, Any]:
    """Pair the `_class_inv_refs_axiom_func` OUTER wrapper with its lifted `_walk` sibling
    (by adjacency). Returns {"outer_ids": {id(outer): desc}, "walk_ids": {id(walk), ...}}.
    Never raises."""
    outer_ids: Dict[int, Dict[str, Any]] = {}
    walk_ids = set()
    try:
        n = len(functions)
        for i, f in enumerate(functions):
            if not isinstance(f, dict):
                continue
            try:
                od = _recognize_cira_outer(f)
            except Exception:
                od = None
            if od is None:
                continue
            if i + 1 >= n:
                continue
            wf = functions[i + 1]
            wn = od["walker_name"]
            wf_name = wf.get("name") if isinstance(wf, dict) else None
            if not (isinstance(wf, dict) and isinstance(wf_name, str)
                    and (wf_name == wn or wf_name.endswith("__" + wn))):
                continue
            if id(wf) in walk_ids:
                continue
            call_names = {wn, wf_name}
            try:
                leaf = _recognize_cira_walk(wf, od["ax_v"], od["hit_v"], call_names)
            except Exception:
                leaf = None
            if leaf is None:
                continue
            desc = {"name": od["name"], "param": od["param"],
                    "self_type": od["self_type"], "td_key": od["td_key"],
                    "ci_key": od["ci_key"]}
            desc.update(leaf)
            outer_ids[id(f)] = desc
            walk_ids.add(id(wf))
    except Exception:
        return {"outer_ids": {}, "walk_ids": set()}
    return {"outer_ids": outer_ids, "walk_ids": walk_ids}


def emit_class_inv_refs_axiom_group(func: Dict[str, Any], desc: Dict[str, Any],
                                    whyml_ident) -> List[str]:
    """Emit `_class_inv_refs_axiom_func` as a mutual pyval/pydict/list existence
    catamorphism over the REAL `type_decls`->`class_invariants` spine, whose leaf is the
    real `type=="<tag>" && Map.get axset func` membership; `axset` is the opaque-but-real
    self-source `val <n>__axset (self):map string bool`. `ensures True`; ledger 3."""
    n = whyml_ident(desc["name"])
    P = f"{n}__"
    mv = _pvw_mv(desc["param"])
    st = desc.get("self_type")
    self_type = whyml_ident(st.lower()) if st else "preambleemissionmixin"
    tag = desc["tag"]
    out: List[str] = []
    out += _emit_skey_reader(f"{P}gtype", desc["type_key"])   # option string: node["type"]
    out += _emit_skey_reader(f"{P}gfunc", desc["func_key"])   # option string: node["func"]
    out += _emit_pval_reader(f"{P}gtd", desc["td_key"])       # option pyval: ir["type_decls"]
    out += _emit_pval_reader(f"{P}gci", desc["ci_key"])       # option pyval: td["class_invariants"]
    # self-source: the axiom-logic-funcs name set — opaque-but-real (no ensures = a sound
    # over-approx; NOT an axiom). REALLY read by `Map.get` membership in the leaf.
    out.append(f"  val {P}axset (self: {self_type}) : map string bool")
    # leaf: the `type=="<tag>" and func in axiom_fns` discriminant (real membership)
    out.append(f"  let {P}leaf (d: pydict) (axset: map string bool) : bool")
    out.append("    requires { true } ensures { true }")
    out.append(f'  = (match {P}gtype d with Some ty -> pystr_eq ty "{tag}" | None -> false end)')
    out.append(f"    && (match {P}gfunc d with Some fn -> Map.get axset fn | None -> false end)")
    # mutual existence fold; axset threaded UNCHANGED and OUT of the variant
    out.append(f"  let rec {P}v (v: pyval) (axset: map string bool) : bool")
    out.append("    requires { true } ensures { true } variant { pv_size v }")
    out.append("  = match v with")
    out.append(f"    | PDict d -> {P}leaf d axset || {P}dfold d axset")
    out.append(f"    | PList xs -> {P}lfold xs axset")
    out.append("    | _ -> false")
    out.append("    end")
    out.append(f"  with {P}dfold (d: pydict) (axset: map string bool) : bool")
    out.append("    requires { true } ensures { true } variant { size_dict d }")
    out.append("  = match d with DNil -> false")
    out.append("    | DCons _ v rest ->")
    out.append("        size_pos v;")
    out.append(f"        {P}v v axset || {P}dfold rest axset end")
    out.append(f"  with {P}lfold (xs: list pyval) (axset: map string bool) : bool")
    out.append("    requires { true } ensures { true } variant { size_list xs }")
    out.append("  = match xs with Nil -> false")
    out.append(f"    | Cons h t -> {P}v h axset || {P}lfold t axset end")
    # spine navigator: each td's class_invariants list folded through the existence walk
    out.append(f"  let rec {P}tdfold (xs: list pyval) (axset: map string bool) : bool")
    out.append("    requires { true } ensures { true } variant { size_list xs }")
    out.append("  = match xs with Nil -> false")
    out.append("    | Cons h t ->")
    out.append("        (match h with")
    out.append(f"         | PDict td -> (match {P}gci td with Some (PList invs) -> "
               f"{P}lfold invs axset | _ -> false end)")
    out.append("         | _ -> false end)")
    out.append(f"        || {P}tdfold t axset")
    out.append("    end")
    # entry: axset from self-state, then fold ir["type_decls"] through the navigator
    out.append(f"  let {n} (self: {self_type}) ({mv}: pyval) : bool")
    out.append("    requires { true } ensures { true }")
    out.append(f"  = let axset = {P}axset self in")
    out.append(f"    match {mv} with")
    out.append("    | PDict fd ->")
    out.append(f"        (match {P}gtd fd with Some (PList tds) -> {P}tdfold tds axset "
               "| _ -> false end)")
    out.append("    | _ -> false")
    out.append("    end")
    return out


# ---- `_inductive_refs_global_or_axiom_func` (preamble.py PreambleEmissionMixin INSTANCE
# method): the globals-set EXTENSION of `_class_inv_refs_axiom_func`. True iff some `#@
# inductive` rule applies an axiom-backing logic function OR references a module-global
# object (by name). SAME nonlocal-scalar-`hit`/`nonlocal hit` nested-`def _walk` shape, with
# THREE additions over the class-inv twin: (i) an 8-stmt outer that also builds
# `globals_names = {g["name"] for g in ir["module_globals"]}` and adds the double-guard `if
# not axiom_fns and not globals_names: return False`; (ii) the walk has THREE leaf disjuncts
# — `type=="Call" and func in axiom_fns`, `type=="Var" and name in globals_names`,
# `isinstance(node.get("object"),str) and node["object"] in globals_names`; (iii) the seed
# is a TRIPLE loop `ind -> [ind]+members -> rules -> clause_ir`. The axiom set stays the
# opaque-but-real `val <n>__axset (self):map string bool`; `globals_names` membership is a
# REAL recursive SEARCH (`__ginmg`) over the REAL `ir["module_globals"]` list, testing each
# `g["name"]` with `pystr_eq` (NOT opaque — derived from the ir param, and no map/const/
# set_add baggage). The walked SPINE stays REAL: the `inductive_decls` subtree is
# folded through the certified pyval/pydict/list existence catamorphism (a sound
# over-approximation of the rule-clause navigation under `ensures True` — it descends strictly
# more real structure; the leaf predicate + both memberships are exact). Every tag literal
# and membership is read structurally (a leaf-tag change moves the emitted .mlw). Fail-closed:
# any deviation stays `\trusted`. The lifted `_walk` is SUPPRESSED. `ensures True`; ledger 3
# (reuses the certified pyval/pydict ADT + map string bool — no new type/axiom/cert).

def _match_type_key_in_set(test: Any, node: str, set_v: str) -> Optional[Dict[str, str]]:
    """`node.get("<type_key>") == "<tag>" and node.get("<mem_key>") in <set_v>`.
    Returns {type_key, tag, mem_key} or None."""
    if not (isinstance(test, dict) and test.get("type") == "BinOp" and test.get("op") == "and"):
        return None
    left = test.get("left") or {}
    right = test.get("right") or {}
    if not (isinstance(left, dict) and left.get("type") == "BinOp" and left.get("op") == "=="):
        return None
    type_key = _frss_dotget_key(left.get("left"), node)
    tag = _clean_lit(_is_string(left.get("right")))
    if type_key is None or tag is None:
        return None
    if not (isinstance(right, dict) and right.get("type") == "BinOp"
            and right.get("op") == "in" and _is_var(right.get("right"), set_v)):
        return None
    mem_key = _frss_dotget_key(right.get("left"), node)
    if mem_key is None:
        return None
    return {"type_key": type_key, "tag": tag, "mem_key": mem_key}


def _match_object_str_in_set(test: Any, node: str, set_v: str) -> Optional[str]:
    """`isinstance(node.get("<k>"), str) and node["<k>"] in <set_v>` -> k or None."""
    if not (isinstance(test, dict) and test.get("type") == "BinOp" and test.get("op") == "and"):
        return None
    left = test.get("left") or {}
    right = test.get("right") or {}
    # left: isinstance(node.get("<k>"), str)
    if not (isinstance(left, dict) and left.get("type") == "Call"
            and left.get("func") == "isinstance"):
        return None
    largs = left.get("args") or []
    if not (len(largs) == 2 and _is_var(largs[1], "str")):
        return None
    obj_key = _frss_dotget_key(largs[0], node)
    if obj_key is None:
        return None
    # right: node["<k>"] in <set_v>
    if not (isinstance(right, dict) and right.get("type") == "BinOp"
            and right.get("op") == "in" and _is_var(right.get("right"), set_v)):
        return None
    sub = right.get("left") or {}
    if not (isinstance(sub, dict) and sub.get("type") == "Subscript"
            and _is_var(sub.get("value"), node)
            and _clean_lit(_is_string(sub.get("index"))) == obj_key):
        return None
    return obj_key


def _match_setcomp_name(stmt: Any, ir_p: str) -> Optional[Tuple[str, str, str]]:
    """`<gv> = {<g>["<name_key>"] for <g> in ir.get("<mg_key>",[])}` (SetComp, no ifs).
    Returns (globals_var, mg_key, name_key) or None."""
    if not (isinstance(stmt, dict) and stmt.get("stmt") == "Assign"):
        return None
    gv = stmt.get("target")
    val = stmt.get("value") or {}
    if not (isinstance(gv, str) and isinstance(val, dict) and val.get("type") == "SetComp"):
        return None
    gens = val.get("generators") or []
    if len(gens) != 1:
        return None
    gen = gens[0]
    if gen.get("ifs"):
        return None
    bound = gen.get("target")
    if not isinstance(bound, str):
        return None
    mg_key = _frss_dotget_key(gen.get("iter"), ir_p)
    if mg_key is None:
        return None
    elt = val.get("elt") or {}
    if not (isinstance(elt, dict) and elt.get("type") == "Subscript"
            and _is_var(elt.get("value"), bound)):
        return None
    name_key = _clean_lit(_is_string(elt.get("index")))
    if name_key is None:
        return None
    return (gv, mg_key, name_key)


def _match_and_not_not_guard(stmt: Any, a: str, b: str) -> bool:
    """`if not <a> and not <b>: return False` (no else)."""
    if not (isinstance(stmt, dict) and stmt.get("stmt") == "If" and not stmt.get("orelse")):
        return False
    t = stmt.get("test") or {}
    if not (isinstance(t, dict) and t.get("type") == "BinOp" and t.get("op") == "and"):
        return False

    def _is_not(x, v):
        return (isinstance(x, dict) and x.get("type") == "UnaryOp" and x.get("op") == "not"
                and _is_var(x.get("expr"), v))

    if not (_is_not(t.get("left"), a) and _is_not(t.get("right"), b)):
        return False
    g = stmt.get("body") or []
    return (len(g) == 1 and isinstance(g[0], dict) and g[0].get("stmt") == "Return"
            and isinstance(g[0].get("value"), dict)
            and g[0]["value"].get("type") == "Bool"
            and g[0]["value"].get("value") is False)


def _iroaf_innermost_walker(stmt: Any) -> Optional[str]:
    """Descend the TRIPLE `For` seed (ind -> members -> rules) and return the walker
    name of the innermost `<walk>(<clause>)` Expr-call. Fail-closed."""
    if not (isinstance(stmt, dict) and stmt.get("stmt") == "For"):
        return None
    b1 = stmt.get("body") or []
    if len(b1) != 1 or not (isinstance(b1[0], dict) and b1[0].get("stmt") == "For"):
        return None
    b2 = b1[0].get("body") or []
    if len(b2) != 1 or not (isinstance(b2[0], dict) and b2[0].get("stmt") == "For"):
        return None
    b3 = b2[0].get("body") or []
    if len(b3) != 1:
        return None
    call_stmt = b3[0]
    if not (isinstance(call_stmt, dict) and call_stmt.get("stmt") == "Expr"):
        return None
    call = call_stmt.get("value") or {}
    if not (isinstance(call, dict) and call.get("type") == "Call"
            and isinstance(call.get("func"), str) and len(call.get("args") or []) == 1):
        return None
    return call["func"]


def _recognize_iroaf_outer(func: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    """Match the OUTER `_inductive_refs_global_or_axiom_func` wrapper (8-stmt). Fail-closed."""
    if not func.get("name", "").endswith("_inductive_refs_global_or_axiom_func"):
        return None
    if func.get("return_annotation") not in ("bool", None):
        return None
    params = func.get("formal_params") or []
    if len(params) != 1:
        return None
    ir_p = params[0]
    body = func.get("body") or []
    if len(body) != 8:
        return None
    # [0] inds = ir.get("inductive_decls", [])
    b0 = body[0]
    if not (isinstance(b0, dict) and b0.get("stmt") == "Assign"):
        return None
    inds_v = b0.get("target")
    inds_key = _frss_dotget_key(b0.get("value"), ir_p)
    if not (isinstance(inds_v, str) and inds_key is not None):
        return None
    # [1] if not inds: return False
    if not _match_not_guard_return_false(body[1], inds_v):
        return None
    # [2] axiom_fns = getattr(self, "_axiom_logic_funcs", set())
    ga = _match_getattr_bind(body[2])
    if ga is None:
        return None
    ax_v, ax_field = ga
    # [3] globals_names = {g["name"] for g in ir.get("module_globals", [])}
    sc = _match_setcomp_name(body[3], ir_p)
    if sc is None:
        return None
    globals_v, mg_key, name_key = sc
    # [4] if not axiom_fns and not globals_names: return False
    if not _match_and_not_not_guard(body[4], ax_v, globals_v):
        return None
    # [5] hit = False
    hit_v = _match_hit_false(body[5])
    if hit_v is None:
        return None
    # [6] triple For seed; extract the walker name
    walker_name = _iroaf_innermost_walker(body[6])
    if walker_name is None:
        return None
    # [7] return hit
    b7 = body[7]
    if not (isinstance(b7, dict) and b7.get("stmt") == "Return"
            and _is_var(b7.get("value"), hit_v)):
        return None
    return {"name": func.get("name"), "param": ir_p, "self_type": func.get("self_type"),
            "ax_field": ax_field, "ax_v": ax_v, "globals_v": globals_v, "hit_v": hit_v,
            "inds_key": inds_key, "mg_key": mg_key, "name_key": name_key,
            "walker_name": walker_name}


def _recognize_iroaf_walk(walkfunc: Dict[str, Any], ax_v: str, globals_v: str,
                          hit_v: str, call_names: "set") -> Optional[Dict[str, str]]:
    """Match the lifted `_walk(node)` (2-stmt; dict-arm with THREE leaf disjuncts +
    values-loop). Returns {type_key, call_tag, func_key, var_tag, name_key, object_key}."""
    params = walkfunc.get("formal_params") or []
    if len(params) != 1:
        return None
    node = params[0]
    body = walkfunc.get("body") or []
    if len(body) != 2:
        return None
    g0, disp = body
    if not (isinstance(g0, dict) and g0.get("stmt") == "If" and not g0.get("orelse")
            and _is_var(g0.get("test"), hit_v)):
        return None
    gb = g0.get("body") or []
    if not (len(gb) == 1 and isinstance(gb[0], dict) and gb[0].get("stmt") == "Return"
            and gb[0].get("value") is None):
        return None
    if not (isinstance(disp, dict) and disp.get("stmt") == "If"
            and _match_isinstance(disp.get("test"), node, "dict")):
        return None
    darm = disp.get("body") or []
    if len(darm) != 4:
        return None
    d0, d1, d2, valloop = darm
    # d0: type=="Call" and func in axiom_fns
    for _d in (d0, d1, d2):
        if not (isinstance(_d, dict) and _d.get("stmt") == "If" and not _d.get("orelse")):
            return None
    axm = _match_type_key_in_set(d0.get("test"), node, ax_v)
    if axm is None or not _cira_body_sets_hit(d0.get("body"), hit_v):
        return None
    # d1: type=="Var" and name in globals_names
    gvm = _match_type_key_in_set(d1.get("test"), node, globals_v)
    if gvm is None or not _cira_body_sets_hit(d1.get("body"), hit_v):
        return None
    # d2: isinstance(node.get("object"),str) and node["object"] in globals_names
    obj_key = _match_object_str_in_set(d2.get("test"), node, globals_v)
    if obj_key is None or not _cira_body_sets_hit(d2.get("body"), hit_v):
        return None

    def _values_iter(it: Any) -> bool:
        return (isinstance(it, dict) and it.get("type") == "Call"
                and it.get("func") == f"{node}.values" and not it.get("args"))

    if not _frss_iter_selfcall(valloop, call_names, node, _values_iter):
        return None
    orelse = disp.get("orelse") or []
    if len(orelse) != 1:
        return None
    lif2 = orelse[0]
    if not (isinstance(lif2, dict) and lif2.get("stmt") == "If" and not lif2.get("orelse")
            and _match_isinstance(lif2.get("test"), node, "list")):
        return None
    lb = lif2.get("body") or []
    if len(lb) != 1:
        return None
    if not _frss_iter_selfcall(lb[0], call_names, node, lambda it: _is_var(it, node)):
        return None
    return {"type_key": axm["type_key"], "call_tag": axm["tag"], "func_key": axm["mem_key"],
            "var_tag": gvm["tag"], "name_key": gvm["mem_key"], "object_key": obj_key}


def recognize_inductive_refs_pairs(functions: List[Dict[str, Any]]) -> Dict[str, Any]:
    """Pair the `_inductive_refs_global_or_axiom_func` OUTER wrapper with its lifted `_walk`
    sibling (by adjacency). Returns {"outer_ids": {id(outer): desc}, "walk_ids": {...}}.
    Never raises."""
    outer_ids: Dict[int, Dict[str, Any]] = {}
    walk_ids = set()
    try:
        n = len(functions)
        for i, f in enumerate(functions):
            if not isinstance(f, dict):
                continue
            try:
                od = _recognize_iroaf_outer(f)
            except Exception:
                od = None
            if od is None:
                continue
            if i + 1 >= n:
                continue
            wf = functions[i + 1]
            wn = od["walker_name"]
            wf_name = wf.get("name") if isinstance(wf, dict) else None
            if not (isinstance(wf, dict) and isinstance(wf_name, str)
                    and (wf_name == wn or wf_name.endswith("__" + wn))):
                continue
            if id(wf) in walk_ids:
                continue
            call_names = {wn, wf_name}
            try:
                leaf = _recognize_iroaf_walk(wf, od["ax_v"], od["globals_v"],
                                             od["hit_v"], call_names)
            except Exception:
                leaf = None
            if leaf is None:
                continue
            desc = {"name": od["name"], "param": od["param"],
                    "self_type": od["self_type"], "inds_key": od["inds_key"],
                    "mg_key": od["mg_key"], "gname_key": od["name_key"]}
            desc.update(leaf)
            outer_ids[id(f)] = desc
            walk_ids.add(id(wf))
    except Exception:
        return {"outer_ids": {}, "walk_ids": set()}
    return {"outer_ids": outer_ids, "walk_ids": walk_ids}


def emit_inductive_refs_group(func: Dict[str, Any], desc: Dict[str, Any],
                              whyml_ident) -> List[str]:
    """Emit `_inductive_refs_global_or_axiom_func` as a mutual pyval/pydict/list existence
    catamorphism (threading the opaque-but-real `axset` and the REAL `gs` = the actual
    `ir["module_globals"]` list) over the REAL `inductive_decls` subtree. `globals_names`
    membership is a REAL recursive search `__ginmg` over `gs` testing each `g["name"]` with
    `pystr_eq`. Leaf = `type=="Call" && Map.get axset func || type=="Var" && name∈gs ||
    object∈gs`. `ensures True`; ledger 3."""
    n = whyml_ident(desc["name"])
    P = f"{n}__"
    mv = _pvw_mv(desc["param"])
    st = desc.get("self_type")
    self_type = whyml_ident(st.lower()) if st else "preambleemissionmixin"
    call_tag, var_tag = desc["call_tag"], desc["var_tag"]
    out: List[str] = []
    out += _emit_skey_reader(f"{P}gtype", desc["type_key"])    # node["type"]
    out += _emit_skey_reader(f"{P}gfunc", desc["func_key"])    # node["func"]
    out += _emit_skey_reader(f"{P}gname", desc["name_key"])    # node["name"] / g["name"]
    out += _emit_skey_reader(f"{P}gobj", desc["object_key"])   # node["object"]
    out += _emit_pval_reader(f"{P}gmg", desc["mg_key"])        # ir["module_globals"]
    out += _emit_pval_reader(f"{P}ginds", desc["inds_key"])    # ir["inductive_decls"]
    # opaque-but-real axiom-logic-funcs name set (self-source; sound over-approx, not axiom)
    out.append(f"  val {P}axset (self: {self_type}) : map string bool")
    # REAL globals membership: search the actual module_globals list for a g["name"]==nm
    out.append(f"  let rec {P}ginmg (nm: string) (gs: list pyval) : bool")
    out.append("    requires { true } ensures { true } variant { size_list gs }")
    out.append("  = match gs with Nil -> false")
    out.append("    | Cons h t ->")
    out.append(f"        (match h with PDict gd -> (match {P}gname gd with "
               "Some gn -> pystr_eq nm gn | None -> false end) | _ -> false end)")
    out.append(f"        || {P}ginmg nm t")
    out.append("    end")
    # leaf: the three real disjuncts (axset membership + two real gs-list searches)
    out.append(f"  let {P}leaf (d: pydict) (axset: map string bool) (gs: list pyval) : bool")
    out.append("    requires { true } ensures { true }")
    out.append(f'  = ((match {P}gtype d with Some ty -> pystr_eq ty "{call_tag}" | None -> false end)')
    out.append(f"      && (match {P}gfunc d with Some fn -> Map.get axset fn | None -> false end))")
    out.append(f'    || ((match {P}gtype d with Some ty -> pystr_eq ty "{var_tag}" | None -> false end)')
    out.append(f"        && (match {P}gname d with Some nm -> {P}ginmg nm gs | None -> false end))")
    out.append(f"    || (match {P}gobj d with Some ob -> {P}ginmg ob gs | None -> false end)")
    # mutual existence fold; axset + gs threaded UNCHANGED and OUT of the variant
    out.append(f"  let rec {P}v (v: pyval) (axset: map string bool) (gs: list pyval) : bool")
    out.append("    requires { true } ensures { true } variant { pv_size v }")
    out.append("  = match v with")
    out.append(f"    | PDict d -> {P}leaf d axset gs || {P}dfold d axset gs")
    out.append(f"    | PList xs -> {P}lfold xs axset gs")
    out.append("    | _ -> false")
    out.append("    end")
    out.append(f"  with {P}dfold (d: pydict) (axset: map string bool) (gs: list pyval) : bool")
    out.append("    requires { true } ensures { true } variant { size_dict d }")
    out.append("  = match d with DNil -> false")
    out.append("    | DCons _ v rest ->")
    out.append("        size_pos v;")
    out.append(f"        {P}v v axset gs || {P}dfold rest axset gs end")
    out.append(f"  with {P}lfold (xs: list pyval) (axset: map string bool) (gs: list pyval) : bool")
    out.append("    requires { true } ensures { true } variant { size_list xs }")
    out.append("  = match xs with Nil -> false")
    out.append(f"    | Cons h t -> {P}v h axset gs || {P}lfold t axset gs end")
    # entry: axset from self-state, gs = the real module_globals list, fold the inds subtree
    out.append(f"  let {n} (self: {self_type}) ({mv}: pyval) : bool")
    out.append("    requires { true } ensures { true }")
    out.append(f"  = let axset = {P}axset self in")
    out.append(f"    match {mv} with")
    out.append("    | PDict fd ->")
    out.append(f"        let gs = (match {P}gmg fd with Some (PList gg) -> gg | _ -> Nil end) in")
    out.append(f"        (match {P}ginds fd with Some (PList inds) -> {P}lfold inds axset gs "
               "| _ -> false end)")
    out.append("    | _ -> false")
    out.append("    end")
    return out


# ---- `_collect_struct_pack_assign_targets` (types.py TypeInferenceMixin INSTANCE method,
#      boundary-A SET-COLLECT, self-free): collect the assign TARGET of every
#      `X = struct.pack(fmt, ...)` whose format string parses. Live body:
#        return _scan(stmts)     with the lifted `_scan`:
#        found = set()
#        for s in stmts:
#          if s.get("stmt") == "Assign":
#            val = s.get("value", {})
#            if isinstance(val,dict) and val.get("type")=="Call" and val.get("func","")=="struct.pack":
#              fmt_arg = (val.get("args") or [{}])[0]
#              if fmt_arg.get("type")=="String" and parse_format(fmt_arg.get("value",""))!=None:
#                tgt = s.get("target","");
#                if tgt: found.add(tgt)
#          for k in ("body","orelse"):
#            if k in s: found |= _scan(s[k])
#          if s.get("stmt")=="Try":
#            for h in s.get("handlers",[]): found |= _scan(h.get("body",[]))
#        return found
#      The OUTER delegates to the lifted `_scan` (SUPPRESSED). The wrapper emits a
#      REF-accumulator (map string bool) fold: the REAL `struct.pack` func-literal and the
#      REAL `target` are read off the pydict; only the `parse_format(fmt)!=None`
#      format-validity check is an OPAQUE-but-sound over-approximation (`val <n>__pf_ok
#      (v:pyval):bool`, the `_test_contains_map` opaque-predicate device). Non-facade:
#      the stmt/type/func/target key+tag literals are reflected structurally from the body
#      (mutation-sensitive), and the REAL target set-add is the anti-vacuity signal.
#      Coupling-free: the sole caller `_emit_body_code` is a `\trusted` stub (its call is
#      not emitted, so the returned `map string bool` never crosses into a converted
#      caller). `set_add`/`const` come free with the pydict theory (needs_pydict). The
#      lifted `_scan` is SUPPRESSED. Keyed on `id`; corpus-inert (name-gated). Ledger 3.

def _spat_find_add_var(node: Any, acc: str) -> Optional[str]:
    """The single Var name passed to `<acc>.add(<var>)` anywhere in `node`, else None."""
    if isinstance(node, dict):
        if (node.get("type") == "Call" and node.get("func") == f"{acc}.add"):
            a = node.get("args") or []
            if len(a) == 1 and isinstance(a[0], dict) and a[0].get("type") == "Var":
                return a[0].get("name")
        for v in node.values():
            r = _spat_find_add_var(v, acc)
            if r:
                return r
    elif isinstance(node, list):
        for x in node:
            r = _spat_find_add_var(x, acc)
            if r:
                return r
    return None


def _spat_find_binding_key(node: Any, var: str, recv: str) -> Optional[str]:
    """The literal key of the `<var> = <recv>.get("<k>"[, d])` Assign inside `node`."""
    if isinstance(node, dict):
        if (node.get("stmt") == "Assign" and node.get("target") == var):
            return _frss_dotget_key(node.get("value"), recv)
        for v in node.values():
            r = _spat_find_binding_key(v, var, recv)
            if r:
                return r
    elif isinstance(node, list):
        for x in node:
            r = _spat_find_binding_key(x, var, recv)
            if r:
                return r
    return None


def _recognize_spat_outer(func: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    """Match the OUTER `_collect_struct_pack_assign_targets` wrapper `return _scan(stmts)`.
    Fail-closed. Returns {name, param, self_type, walker_name}."""
    if not func.get("name", "").endswith("_collect_struct_pack_assign_targets"):
        return None
    if func.get("return_annotation") != "set":
        return None
    params = func.get("formal_params") or []
    if len(params) != 1:
        return None
    stmts_p = params[0]
    body = func.get("body") or []
    if len(body) != 1:
        return None
    b0 = body[0]
    if not (isinstance(b0, dict) and b0.get("stmt") == "Return"):
        return None
    call = b0.get("value") or {}
    if not (isinstance(call, dict) and call.get("type") == "Call"
            and isinstance(call.get("func"), str)):
        return None
    cargs = call.get("args") or []
    if not (len(cargs) == 1 and _is_var(cargs[0], stmts_p)):
        return None
    return {"name": func.get("name"), "param": stmts_p,
            "self_type": func.get("self_type"), "walker_name": call["func"]}


def _recognize_spat_scan(walkfunc: Dict[str, Any],
                         call_names: "set") -> Optional[Dict[str, Any]]:
    """Match the lifted `_scan(stmts)` set-collect and extract the leaf discriminant
    literals. Fail-closed. Returns the key/tag dict (stmt/value/type/func/target keys +
    Assign/Call/struct.pack tags)."""
    params = walkfunc.get("formal_params") or []
    if len(params) != 1:
        return None
    items_p = params[0]
    body = walkfunc.get("body") or []
    if len(body) != 3:
        return None
    b0, forst, ret = body
    # [0] found = set()
    if not (isinstance(b0, dict) and b0.get("stmt") == "Assign"):
        return None
    acc = b0.get("target")
    iv = b0.get("value") or {}
    if not (isinstance(acc, str) and isinstance(iv, dict) and iv.get("type") == "Call"
            and iv.get("func") == "set" and not iv.get("args")):
        return None
    # [2] return found
    if not (isinstance(ret, dict) and ret.get("stmt") == "Return"
            and _is_var(ret.get("value"), acc)):
        return None
    # [1] for s in stmts:
    if not (isinstance(forst, dict) and forst.get("stmt") == "For"
            and _is_var(forst.get("iter"), items_p)):
        return None
    sv = forst.get("target")
    fb = forst.get("body") or []
    if not (isinstance(sv, str) and fb):
        return None
    # fb[0]: if s.get("<stmt_key>") == "<assign_tag>": [val = s.get(..), if <pack-guard>: ..]
    ag = fb[0]
    if not (isinstance(ag, dict) and ag.get("stmt") == "If"):
        return None
    agt = ag.get("test") or {}
    if not (isinstance(agt, dict) and agt.get("type") == "BinOp" and agt.get("op") == "=="):
        return None
    stmt_key = _frss_dotget_key(agt.get("left"), sv)
    assign_tag = _clean_lit(_is_string(agt.get("right")))
    if stmt_key is None or assign_tag is None:
        return None
    g = ag.get("body") or []
    if len(g) != 2:
        return None
    g0, g1 = g
    # g0: val = s.get("<value_key>", {})
    if not (isinstance(g0, dict) and g0.get("stmt") == "Assign"):
        return None
    valvar = g0.get("target")
    value_key = _frss_dotget_key(g0.get("value"), sv)
    if not (isinstance(valvar, str) and value_key is not None):
        return None
    # g1: if (isinstance(val,dict) and val.get("<type_key>")=="<call_tag>")
    #        and val.get("<func_key>","")=="<pack_func>": ...
    if not (isinstance(g1, dict) and g1.get("stmt") == "If"):
        return None
    gt = g1.get("test") or {}
    if not (isinstance(gt, dict) and gt.get("type") == "BinOp" and gt.get("op") == "and"):
        return None
    left = gt.get("left") or {}
    right = gt.get("right") or {}
    # right: val.get("<func_key>") == "<pack_func>"
    if not (isinstance(right, dict) and right.get("type") == "BinOp" and right.get("op") == "=="):
        return None
    func_key = _frss_dotget_key(right.get("left"), valvar)
    pack_func = _clean_lit(_is_string(right.get("right")))
    if func_key is None or pack_func is None:
        return None
    # left: isinstance(val, dict) and val.get("<type_key>") == "<call_tag>"
    if not (isinstance(left, dict) and left.get("type") == "BinOp" and left.get("op") == "and"):
        return None
    if not _match_isinstance(left.get("left"), valvar, "dict"):
        return None
    tycmp = left.get("right") or {}
    if not (isinstance(tycmp, dict) and tycmp.get("type") == "BinOp" and tycmp.get("op") == "=="):
        return None
    type_key = _frss_dotget_key(tycmp.get("left"), valvar)
    call_tag = _clean_lit(_is_string(tycmp.get("right")))
    if type_key is None or call_tag is None:
        return None
    # anti-facade: inside g1 there is `found.add(<tgt>)` where `tgt = s.get("<target_key>")`
    add_var = _spat_find_add_var(g1.get("body") or [], acc)
    if add_var is None:
        return None
    target_key = _spat_find_binding_key(g1.get("body") or [], add_var, sv)
    if target_key is None:
        return None
    # recursion keys must be present (fail-closed on a wholesale walk mutation); the
    # lifted `_scan` self-call name must appear (a real recursive descent, not a stub).
    strings = set(_all_strings(fb))
    if not {"body", "orelse", "handlers"}.issubset(strings):
        return None
    if _find_self_call_name(fb, "") is None and not call_names:
        return None
    return {"stmt_key": stmt_key, "assign_tag": assign_tag, "value_key": value_key,
            "type_key": type_key, "call_tag": call_tag, "func_key": func_key,
            "pack_func": pack_func, "target_key": target_key,
            "body_key": "body", "orelse_key": "orelse", "handlers_key": "handlers"}


def recognize_struct_pack_targets_pairs(functions: List[Dict[str, Any]]
                                        ) -> Dict[str, Any]:
    """Pair the `_collect_struct_pack_assign_targets` OUTER wrapper with its lifted
    `_scan` sibling (by adjacency). Returns {"outer_ids": {id(outer): desc}, "walk_ids":
    {id(walk), ...}}. Never raises."""
    outer_ids: Dict[int, Dict[str, Any]] = {}
    walk_ids = set()
    try:
        n = len(functions)
        for i, f in enumerate(functions):
            if not isinstance(f, dict):
                continue
            try:
                od = _recognize_spat_outer(f)
            except Exception:
                od = None
            if od is None:
                continue
            if i + 1 >= n:
                continue
            wf = functions[i + 1]
            wn = od["walker_name"]
            wf_name = wf.get("name") if isinstance(wf, dict) else None
            if not (isinstance(wf, dict) and isinstance(wf_name, str)
                    and (wf_name == wn or wf_name.endswith("__" + wn))):
                continue
            if id(wf) in walk_ids:
                continue
            try:
                leaf = _recognize_spat_scan(wf, {wn, wf_name})
            except Exception:
                leaf = None
            if leaf is None:
                continue
            desc = {"name": od["name"], "param": od["param"],
                    "self_type": od["self_type"]}
            desc.update(leaf)
            outer_ids[id(f)] = desc
            walk_ids.add(id(wf))
    except Exception:
        return {"outer_ids": {}, "walk_ids": set()}
    return {"outer_ids": outer_ids, "walk_ids": walk_ids}


def emit_struct_pack_targets_group(func: Dict[str, Any], desc: Dict[str, Any],
                                   whyml_ident) -> List[str]:
    """Emit `_collect_struct_pack_assign_targets` as a REF-accumulator (map string bool)
    set-collect over the pyval stmt list: the REAL `struct.pack` func-literal and the REAL
    `target` are read off the pydict (mutation-sensitive), and only the format-validity
    (`parse_format(fmt)!=None`) is an opaque-but-sound `val <n>__pf_ok (v:pyval):bool`.
    Body/orelse/handlers recursion reuses the `find_assigned_vars` typed list readers with
    the `size_pos`/`size_dict_nonneg` termination pins. `ensures True`; ledger 3 (no new
    type/axiom/cert)."""
    n = whyml_ident(desc["name"])
    P = f"{n}__"
    mv = _pvw_mv(desc["param"])
    st = desc.get("self_type")
    self_type = whyml_ident(st.lower()) if st else "typeinferencemixin"
    at = desc["assign_tag"]
    ct = desc["call_tag"]
    pf = desc["pack_func"]
    acc_ty = "ref (map string bool)"
    out: List[str] = []
    # opaque format-validity over-approximation (sound under ensures-True; input-dependent)
    out.append(f"  val {P}pf_ok (v: pyval) : bool")
    # literal-key readers (typed irkey ctor or K_dyn guard, reflected per key)
    out += _emit_skey_reader(f"{P}gstmt", desc["stmt_key"])   # "stmt" (K_dyn)
    out += _emit_skey_reader(f"{P}gtgt", desc["target_key"])  # "target" (K_target)
    out += _emit_pval_reader(f"{P}gval", desc["value_key"])   # "value" (K_value): the call node
    out += _emit_skey_reader(f"{P}gtype", desc["type_key"])   # "type" (K_type)
    out += _emit_skey_reader(f"{P}gfunc", desc["func_key"])   # "func" (K_func)

    def _list_reader(rname: str, key: str) -> None:
        # SPLIT into the proven `pget_dyn`/`pget_list` shape: a recursive option-returning
        # key SEARCH whose OWN VC carries the `pv_size v <= size_dict d` bound, plus a tiny
        # NON-recursive composer that projects the `PList`. This isolates the recursive
        # size measures (and, on the K_dyn path, the `pystr_eq` string theory) inside the
        # search function's self-contained VC, so the list-reader's `size_list result <=
        # size_dict d` postcondition is a one-step consequence of the search postcondition
        # instead of an E-matching blow-up over the whole nested match (the Lhandlers
        # 30M-step timeout). Mirrors the already-proven `pget_dyn`+`pget_list` pair.
        gname = f"{rname}_g"
        ctor = _irkey_ctor(key)
        out.append(f"  let rec {gname} (d: pydict) : option pyval")
        out.append("    variant { d }")
        out.append("    ensures { match result with Some v -> pv_size v <= size_dict d | None -> true end }")
        out.append("  = match d with")
        out.append("    | DNil -> None")
        if ctor.startswith("(K_dyn"):
            out.append(f'    | DCons (K_dyn s) v rest -> if pystr_eq s "{key}" then Some v else {gname} rest')
        else:
            out.append(f"    | DCons {ctor} v _ -> Some v")
        out.append(f"    | DCons _ _ rest -> {gname} rest")
        out.append("    end")
        out.append(f"  let {rname} (d: pydict) : list pyval")
        out.append("    ensures { size_list result <= size_dict d }")
        out.append(f"  = match {gname} d with Some (PList xs) -> xs | _ -> Nil end")

    _list_reader(f"{P}Lbody", desc["body_key"])
    _list_reader(f"{P}Lorelse", desc["orelse_key"])
    _list_reader(f"{P}Lhandlers", desc["handlers_key"])
    # main mutual fold + handler-list sub-fold on the SHARED acc
    out.append(f"  let rec {P}f (items: list pyval) (acc: {acc_ty}) : unit")
    out.append("    requires { true } ensures { true } writes { acc } variant { size_list items }")
    out.append("  = match items with")
    out.append("    | Nil -> ()")
    out.append("    | Cons s rest ->")
    out.append("        (match s with")
    out.append("         | PDict d ->")
    out.append(f'             (match {P}gstmt d with')
    out.append(f'              | Some tag -> if pystr_eq tag "{at}" then')
    out.append(f"                  (match {P}gval d with")
    out.append("                   | Some vv ->")
    out.append("                       (match vv with")
    out.append("                        | PDict vd ->")
    out.append(f'                            let is_call = (match {P}gtype vd with Some t -> pystr_eq t "{ct}" | None -> false end) in')
    out.append(f'                            let is_pack = (match {P}gfunc vd with Some fn -> pystr_eq fn "{pf}" | None -> false end) in')
    out.append(f"                            if is_call && is_pack && {P}pf_ok vv then")
    out.append(f"                              (match {P}gtgt d with Some t -> acc := set_add !acc t | None -> () end)")
    out.append("                            else ()")
    out.append("                        | _ -> () end)")
    out.append("                   | None -> () end)")
    out.append("                else ()")
    out.append("              | None -> () end);")
    out.append(f"             {P}f ({P}Lbody d) acc;")
    out.append(f"             {P}f ({P}Lorelse d) acc;")
    out.append(f"             {P}hf ({P}Lhandlers d) acc")
    out.append("         | _ -> () end);")
    out.append(f"        {P}f rest acc")
    out.append("    end")
    out.append(f"  with {P}hf (hs: list pyval) (acc: {acc_ty}) : unit")
    out.append("    requires { true } ensures { true } writes { acc } variant { size_list hs }")
    out.append("  = match hs with Nil -> ()")
    out.append(f'    | Cons h rest -> (match h with PDict hd -> {P}f ({P}Lbody hd) acc | _ -> () end); {P}hf rest acc end')
    # entry: self ignored (parse_format is a module function, modeled opaque); fold the
    # PARAM stmt list (a real PList) directly.
    out.append(f"  let {n} (self: {self_type}) ({mv}: pyval) : map string bool")
    out.append("    requires { true } ensures { true }")
    out.append("  = let acc = ref (const false) in")
    out.append(f"    (match {mv} with PList xs -> {P}f xs acc | _ -> () end);")
    out.append("    !acc")
    return out


# ---- `_collect_struct_unpack_array_targets` (types.py boundary-A SET-COLLECT, the
#      TUPLE-UNPACK twin of `_collect_struct_pack_assign_targets`): collect the tuple-
#      unpack LHS slot names whose slot type is `array int`. Live body (verbatim):
