#                    if slot_t == "array int": found.add(tgt)
#          for k in ("body","orelse"): found |= _scan(s[k]) ; if Try: handlers…
#      Same OUTER+lifted-`_scan` adjacency pairing as the pack twin, ref-accumulator
#      `map string bool`. The NEW element is an INDEX-THREADED per-slot set-fold over the
#      REAL `targets: list pyval` spine (each target a `PStr name`), gated by an OPAQUE
#      per-index leaf `val <n>__is_slot{A,B} (v:pyval)(i:int):bool` (the struct-format
#      `.slots` parse / the cross-method tuple-type split are unmodelable — the role
#      `pf_ok` plays in the pack twin). BOTH branches (struct.unpack vs the else cross-
#      method path) are reflected structurally so a body change moves the emit (anti-
#      facade). Non-facade: the stmt/type/func/targets key+tag literals are read off the
#      body (mutation-sensitive), and the REAL target `set_add` is the anti-vacuity
#      signal. The self-calls (`_call_return_whyml_type`/`_split_tuple_type`) are modeled
#      OPAQUELY (not emitted) — no caller coupling. The lifted `_scan` is SUPPRESSED.
#      Keyed on `id`; corpus-inert (name-gated). Ledger 3 (reuses the certified
#      pyval/pydict ADT + the pack twin's typed readers; no new type/axiom/cert).

def _recognize_suat_outer(func: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    """Match the OUTER `_collect_struct_unpack_array_targets` wrapper `return _scan(stmts)`.
    Fail-closed. Returns {name, param, self_type, walker_name}."""
    if not func.get("name", "").endswith("_collect_struct_unpack_array_targets"):
        return None
    if func.get("return_annotation") != "set":
        return None
    params = func.get("formal_params") or []
    if len(params) != 1:
        return None
    stmts_p = params[0]
    body = func.get("body") or []
    if len(body) != 1:
        return None
    b0 = body[0]
    if not (isinstance(b0, dict) and b0.get("stmt") == "Return"):
        return None
    call = b0.get("value") or {}
    if not (isinstance(call, dict) and call.get("type") == "Call"
            and isinstance(call.get("func"), str)):
        return None
    cargs = call.get("args") or []
    if not (len(cargs) == 1 and _is_var(cargs[0], stmts_p)):
        return None
    return {"name": func.get("name"), "param": stmts_p,
            "self_type": func.get("self_type"), "walker_name": call["func"]}


def _recognize_suat_scan(walkfunc: Dict[str, Any],
                         call_names: "set") -> Optional[Dict[str, Any]]:
    """Match the lifted `_scan` tuple-unpack set-collect and extract the leaf discriminant
    literals. Fail-closed. Returns the key/tag dict (stmt/value/type/func/targets keys +
    TupleUnpack/Call/struct.unpack tags)."""
    params = walkfunc.get("formal_params") or []
    if len(params) != 1:
        return None
    items_p = params[0]
    body = walkfunc.get("body") or []
    if len(body) != 3:
        return None
    b0, forst, ret = body
    # [0] found = set()
    if not (isinstance(b0, dict) and b0.get("stmt") == "Assign"):
        return None
    acc = b0.get("target")
    iv = b0.get("value") or {}
    if not (isinstance(acc, str) and isinstance(iv, dict) and iv.get("type") == "Call"
            and iv.get("func") == "set" and not iv.get("args")):
        return None
    # [2] return found
    if not (isinstance(ret, dict) and ret.get("stmt") == "Return"
            and _is_var(ret.get("value"), acc)):
        return None
    # [1] for s in stmts:
    if not (isinstance(forst, dict) and forst.get("stmt") == "For"
            and _is_var(forst.get("iter"), items_p)):
        return None
    sv = forst.get("target")
    fb = forst.get("body") or []
    if not (isinstance(sv, str) and fb):
        return None
    # fb[0]: if s.get("<stmt_key>") == "<unpack_tag>":
    ag = fb[0]
    if not (isinstance(ag, dict) and ag.get("stmt") == "If"):
        return None
    agt = ag.get("test") or {}
    if not (isinstance(agt, dict) and agt.get("type") == "BinOp" and agt.get("op") == "=="):
        return None
    stmt_key = _frss_dotget_key(agt.get("left"), sv)
    unpack_tag = _clean_lit(_is_string(agt.get("right")))
    if stmt_key is None or unpack_tag is None:
        return None
    g = ag.get("body") or []
    if len(g) != 2:
        return None
    g0, g1 = g
    # g0: val = s.get("<value_key>", {})
    if not (isinstance(g0, dict) and g0.get("stmt") == "Assign"):
        return None
    valvar = g0.get("target")
    value_key = _frss_dotget_key(g0.get("value"), sv)
    if not (isinstance(valvar, str) and value_key is not None):
        return None
    # g1: if isinstance(val, dict) and val.get("<type_key>") == "<call_tag>":
    if not (isinstance(g1, dict) and g1.get("stmt") == "If"):
        return None
    gt = g1.get("test") or {}
    if not (isinstance(gt, dict) and gt.get("type") == "BinOp" and gt.get("op") == "and"):
        return None
    if not _match_isinstance(gt.get("left"), valvar, "dict"):
        return None
    tycmp = gt.get("right") or {}
    if not (isinstance(tycmp, dict) and tycmp.get("type") == "BinOp" and tycmp.get("op") == "=="):
        return None
    type_key = _frss_dotget_key(tycmp.get("left"), valvar)
    call_tag = _clean_lit(_is_string(tycmp.get("right")))
    if type_key is None or call_tag is None:
        return None
    # g1.body: [fn = val.get("<func_key>",""), targets = s.get("<targets_key>",[]),
    #           if fn == "<unpack_func>": <branchA> else: <branchB>]
    gb = g1.get("body") or []
    if len(gb) != 3:
        return None
    a_fn, a_tg, iff = gb
    if not (isinstance(a_fn, dict) and a_fn.get("stmt") == "Assign"):
        return None
    fnvar = a_fn.get("target")
    func_key = _frss_dotget_key(a_fn.get("value"), valvar)
    if not (isinstance(fnvar, str) and func_key is not None):
        return None
    if not (isinstance(a_tg, dict) and a_tg.get("stmt") == "Assign"):
        return None
    tgtsvar = a_tg.get("target")
    targets_key = _frss_dotget_key(a_tg.get("value"), sv)
    if not (isinstance(tgtsvar, str) and targets_key is not None):
        return None
    # iff: if fn == "<unpack_func>": <branchA> else: <branchB>  (BOTH branches required)
    if not (isinstance(iff, dict) and iff.get("stmt") == "If"):
        return None
    it = iff.get("test") or {}
    if not (isinstance(it, dict) and it.get("type") == "BinOp" and it.get("op") == "=="):
        return None
    if not _is_var(it.get("left"), fnvar):
        return None
    unpack_func = _clean_lit(_is_string(it.get("right")))
    if unpack_func is None:
        return None
    branch_a = iff.get("body") or []
    branch_b = iff.get("orelse") or []
    if not (branch_a and branch_b):
        return None
    # anti-facade: `found.add(<tgt>)` present in BOTH branches; the `array int`
    # slot-type discriminant present in BOTH (a body that drops either fails to match).
    if _spat_find_add_var(branch_a, acc) is None:
        return None
    if _spat_find_add_var(branch_b, acc) is None:
        return None
    if "array int" not in set(_all_strings(branch_a)):
        return None
    if "array int" not in set(_all_strings(branch_b)):
        return None
    # recursion keys must be present (fail-closed on a wholesale walk mutation); the
    # lifted `_scan` self-call name must appear (a real recursive descent, not a stub).
    strings = set(_all_strings(fb))
    if not {"body", "orelse", "handlers"}.issubset(strings):
        return None
    if _find_self_call_name(fb, "") is None and not call_names:
        return None
    return {"stmt_key": stmt_key, "unpack_tag": unpack_tag, "value_key": value_key,
            "type_key": type_key, "call_tag": call_tag, "func_key": func_key,
            "targets_key": targets_key, "unpack_func": unpack_func,
            "body_key": "body", "orelse_key": "orelse", "handlers_key": "handlers"}


def recognize_struct_unpack_targets_pairs(functions: List[Dict[str, Any]]
                                          ) -> Dict[str, Any]:
    """Pair the `_collect_struct_unpack_array_targets` OUTER wrapper with its lifted
    `_scan` sibling (by adjacency). Returns {"outer_ids": {id(outer): desc}, "walk_ids":
    {id(walk), ...}}. Never raises."""
    outer_ids: Dict[int, Dict[str, Any]] = {}
    walk_ids = set()
    try:
        n = len(functions)
        for i, f in enumerate(functions):
            if not isinstance(f, dict):
                continue
            try:
                od = _recognize_suat_outer(f)
            except Exception:
                od = None
            if od is None:
                continue
            # FORWARD-SEARCH (not strict i+1): the mirror has TWO nested `def _scan`
            # siblings (the pack twin's + this one) that BOTH lift to the identical
            # name `<class>___scan`. Adjacency alone is order-fragile, so scan forward
            # for the FIRST name-matching, not-yet-claimed sibling whose body passes
            # `_recognize_suat_scan` — the leaf recognizer disambiguates (the pack
            # twin's `_scan` is an `Assign`/`struct.pack` single-branch shape and fails
            # this TupleUnpack/two-branch match), so we never steal the pack sibling.
            wn = od["walker_name"]
            leaf = None
            wf = None
            for j in range(i + 1, n):
                cand = functions[j]
                cand_name = cand.get("name") if isinstance(cand, dict) else None
                if not (isinstance(cand, dict) and isinstance(cand_name, str)
                        and (cand_name == wn or cand_name.endswith("__" + wn))):
                    continue
                if id(cand) in walk_ids:
                    continue
                try:
                    cl = _recognize_suat_scan(cand, {wn, cand_name})
                except Exception:
                    cl = None
                if cl is not None:
                    leaf = cl
                    wf = cand
                    break
            if leaf is None or wf is None:
                continue
            desc = {"name": od["name"], "param": od["param"],
                    "self_type": od["self_type"]}
            desc.update(leaf)
            outer_ids[id(f)] = desc
            walk_ids.add(id(wf))
    except Exception:
        return {"outer_ids": {}, "walk_ids": set()}
    return {"outer_ids": outer_ids, "walk_ids": walk_ids}


def emit_struct_unpack_targets_group(func: Dict[str, Any], desc: Dict[str, Any],
                                     whyml_ident) -> List[str]:
    """Emit `_collect_struct_unpack_array_targets` as a REF-accumulator (map string bool)
    set-collect over the pyval stmt list: the REAL stmt/type/func/targets literals are read
    off the pydict (mutation-sensitive), the REAL tuple-unpack `targets` spine is walked by
    index, and the REAL target name is `set_add`ed; only the per-slot `array int` decision
    is an opaque-but-sound `val <n>__is_slot{A,B} (v:pyval)(i:int):bool`. BOTH branches
    (struct.unpack / cross-method else) are emitted. Body/orelse/handlers recursion reuses
    the pack twin's typed list readers with the `size_pos`/`size_dict_nonneg` termination
    pins. `ensures True`; ledger 3 (no new type/axiom/cert)."""
    n = whyml_ident(desc["name"])
    P = f"{n}__"
    mv = _pvw_mv(desc["param"])
    st = desc.get("self_type")
    self_type = whyml_ident(st.lower()) if st else "typeinferencemixin"
    ut = desc["unpack_tag"]
    ct = desc["call_tag"]
    uf = desc["unpack_func"]
    acc_ty = "ref (map string bool)"
    out: List[str] = []
    # two OPAQUE per-index slot gates: branch A = struct.unpack format `.slots`,
    # branch B = the cross-method `_split_tuple_type` slots (both unmodelable).
    out.append(f"  val {P}is_slotA (v: pyval) (i: int) : bool")
    out.append(f"  val {P}is_slotB (v: pyval) (i: int) : bool")
    # literal-key readers (typed irkey ctor or K_dyn guard, reflected per key)
    out += _emit_skey_reader(f"{P}gstmt", desc["stmt_key"])   # "stmt" (K_dyn)
    out += _emit_pval_reader(f"{P}gval", desc["value_key"])   # "value": the call node
    out += _emit_skey_reader(f"{P}gtype", desc["type_key"])   # "type" (K_type)
    out += _emit_skey_reader(f"{P}gfunc", desc["func_key"])   # "func" (K_func)

    def _list_reader(rname: str, key: str) -> None:
        # SPLIT into the proven `pget_dyn`/`pget_list` shape (see the pack twin).
        gname = f"{rname}_g"
        ctor = _irkey_ctor(key)
        out.append(f"  let rec {gname} (d: pydict) : option pyval")
        out.append("    variant { d }")
        out.append("    ensures { match result with Some v -> pv_size v <= size_dict d | None -> true end }")
        out.append("  = match d with")
        out.append("    | DNil -> None")
        if ctor.startswith("(K_dyn"):
            out.append(f'    | DCons (K_dyn s) v rest -> if pystr_eq s "{key}" then Some v else {gname} rest')
        else:
            out.append(f"    | DCons {ctor} v _ -> Some v")
        out.append(f"    | DCons _ _ rest -> {gname} rest")
        out.append("    end")
        out.append(f"  let {rname} (d: pydict) : list pyval")
        out.append("    ensures { size_list result <= size_dict d }")
        out.append(f"  = match {gname} d with Some (PList xs) -> xs | _ -> Nil end")

    _list_reader(f"{P}Ltargets", desc["targets_key"])
    _list_reader(f"{P}Lbody", desc["body_key"])
    _list_reader(f"{P}Lorelse", desc["orelse_key"])
    _list_reader(f"{P}Lhandlers", desc["handlers_key"])
    # THE NEW ELEMENT: two INDEX-THREADED per-slot set-folds over the REAL `targets`
    # spine (one per branch), each `set_add`ing the REAL PStr target name when the
    # OPAQUE per-index slot-gate holds.
    for suf in ("A", "B"):
        out.append(f"  let rec {P}tgts{suf} (tgts: list pyval) (v: pyval) (i: int) (acc: {acc_ty}) : unit")
        out.append("    requires { true } ensures { true } writes { acc } variant { tgts }")
        out.append("  = match tgts with")
        out.append("    | Nil -> ()")
        out.append("    | Cons t rest ->")
        out.append(f"        (match t with PStr name -> if {P}is_slot{suf} v i then acc := set_add !acc name else () | _ -> () end);")
        out.append(f"        {P}tgts{suf} rest v (i + 1) acc")
        out.append("    end")
    # main mutual fold + handler-list sub-fold on the SHARED acc (pack shape)
    out.append(f"  let rec {P}f (items: list pyval) (acc: {acc_ty}) : unit")
    out.append("    requires { true } ensures { true } writes { acc } variant { size_list items }")
    out.append("  = match items with")
    out.append("    | Nil -> ()")
    out.append("    | Cons s rest ->")
    out.append("        (match s with")
    out.append("         | PDict d ->")
    out.append(f'             (match {P}gstmt d with')
    out.append(f'              | Some tag -> if pystr_eq tag "{ut}" then')
    out.append(f"                  (match {P}gval d with")
    out.append("                   | Some vv ->")
    out.append("                       (match vv with")
    out.append("                        | PDict vd ->")
    out.append(f'                            let is_call = (match {P}gtype vd with Some t -> pystr_eq t "{ct}" | None -> false end) in')
    out.append(f'                            let is_unpack = (match {P}gfunc vd with Some fn -> pystr_eq fn "{uf}" | None -> false end) in')
    out.append("                            if is_call then")
    out.append(f"                              (if is_unpack then {P}tgtsA ({P}Ltargets d) vv 0 acc")
    out.append(f"                               else {P}tgtsB ({P}Ltargets d) vv 0 acc)")
    out.append("                            else ()")
    out.append("                        | _ -> () end)")
    out.append("                   | None -> () end)")
    out.append("                else ()")
    out.append("              | None -> () end);")
    out.append(f"             {P}f ({P}Lbody d) acc;")
    out.append(f"             {P}f ({P}Lorelse d) acc;")
    out.append(f"             {P}hf ({P}Lhandlers d) acc")
    out.append("         | _ -> () end);")
    out.append(f"        {P}f rest acc")
    out.append("    end")
    out.append(f"  with {P}hf (hs: list pyval) (acc: {acc_ty}) : unit")
    out.append("    requires { true } ensures { true } writes { acc } variant { size_list hs }")
    out.append("  = match hs with Nil -> ()")
    out.append(f'    | Cons h rest -> (match h with PDict hd -> {P}f ({P}Lbody hd) acc | _ -> () end); {P}hf rest acc end')
    # entry: self ignored (the cross-method type lookups are modeled opaque); fold the
    # PARAM stmt list (a real PList) directly.
    out.append(f"  let {n} (self: {self_type}) ({mv}: pyval) : map string bool")
    out.append("    requires { true } ensures { true }")
    out.append("  = let acc = ref (const false) in")
    out.append(f"    (match {mv} with PList xs -> {P}f xs acc | _ -> () end);")
    out.append("    !acc")
    return out


# ---- `_contract_referenced_names` (ir_resolve.py, boundary-A SET-COLLECT sibling of
#      `_func_returns_string_seq`): collect every callee name applied inside the
#      contracts (`requires`/`ensures`) of the injected dependency stubs. Live body:
#        referenced: Set[str] = set()
#        def _walk(node):
#          if isinstance(node, dict):
#            if node.get("type") == "Call" and isinstance(node.get("func"), str):
#              referenced.add(node["func"])
#            for v in node.values(): _walk(v)
#          elif isinstance(node, (list, tuple)):
#            for v in node: _walk(v)
#        for func in dep_funcs:
#          contracts = func.get("contracts", {}) or {}
#          _walk(contracts.get("requires", [])); _walk(contracts.get("ensures", []))
#        return referenced
#      Same OUTER+lifted-`_walk` adjacency pairing as `_func_returns_string_seq`, but the
#      accumulator is a `Set[str]` (returned `map string bool`), not a `found=[False]`
#      bool. The wrapper emits a mutual `pyval`/`pydict`/`list pyval` set-UNION
#      catamorphism (`set_union` in place of `||`, `const false` the empty base) whose
#      leaf reads the REAL `node["func"]` string off the real PDict and `set_add`s it
#      (`isinstance(...,str)` -> `Some (PStr s)`); the OUTER folds `dep_funcs`, reading
#      each func's `contracts` sub-dict and unioning the walk of its `requires`/`ensures`
#      lists. Non-facade (tags/keys read off the body, mutation-sensitive; the set-add of
#      the real func string is the anti-vacuity signal). `set_add`/`set_union`/`const`
#      come free with the pydict theory (needs_pydict). The lifted `_walk` is SUPPRESSED.
#      Keyed on `id`; corpus-inert (name-gated `_contract_referenced_names`). Ledger 3.

def _match_isinstance_tuple(test: Any, subj: str, classes: Tuple[str, ...]) -> bool:
    """`isinstance(<subj>, (<c0>, <c1>, ...))` — isinstance whose second arg is a
    literal Tuple of bare class-name Vars, matched positionally against `classes`."""
    if not (isinstance(test, dict) and test.get("type") == "Call"
            and test.get("func") == "isinstance"):
        return False
    args = test.get("args") or []
    if len(args) != 2 or not _is_var(args[0], subj):
        return False
    tup = args[1]
    if not (isinstance(tup, dict) and tup.get("type") == "Tuple"):
        return False
    elts = tup.get("elts") or []
    names = [e.get("name") for e in elts
             if isinstance(e, dict) and e.get("type") == "Var"]
    return tuple(names) == tuple(classes)


def _recognize_crn_outer(func: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    """Match the OUTER `_contract_referenced_names` wrapper. Fail-closed; None on any
    deviation. Returns {name, param, acc, contracts_key, requires_key, ensures_key,
    walker_name}."""
    if not func.get("name", "").endswith("_contract_referenced_names"):
        return None
    if func.get("return_annotation") != "set":
        return None
    params = func.get("formal_params") or []
    if len(params) != 1:
        return None
    dep_p = params[0]
    body = func.get("body") or []
    if len(body) != 3:
        return None
    b0, b1, b2 = body
    # [0] referenced = set()
    if not (isinstance(b0, dict) and b0.get("stmt") == "Assign"):
        return None
    acc = b0.get("target")
    iv = b0.get("value") or {}
    if not (isinstance(acc, str) and isinstance(iv, dict) and iv.get("type") == "Call"
            and iv.get("func") == "set" and not iv.get("args")):
        return None
    # [2] return referenced
    if not (isinstance(b2, dict) and b2.get("stmt") == "Return"
            and _is_var(b2.get("value"), acc)):
        return None
    # [1] for func in dep_funcs: contracts = func.get("<ck>",{}) or {};
    #     _walk(contracts.get("<rk>",[])); _walk(contracts.get("<ek>",[]))
    if not (isinstance(b1, dict) and b1.get("stmt") == "For"
            and _is_var(b1.get("iter"), dep_p)):
        return None
    lv = b1.get("target")
    if not isinstance(lv, str):
        return None
    fb = b1.get("body") or []
    if len(fb) != 3:
        return None
    fa, fw1, fw2 = fb
    # contracts = func.get("<ck>", {}) or {}
    if not (isinstance(fa, dict) and fa.get("stmt") == "Assign"):
        return None
    cvar = fa.get("target")
    orexpr = fa.get("value") or {}
    if not (isinstance(cvar, str) and isinstance(orexpr, dict)
            and orexpr.get("type") == "BinOp" and orexpr.get("op") == "or"):
        return None
    contracts_key = _frss_dotget_key(orexpr.get("left"), lv)
    if contracts_key is None:
        return None

    def _walkcall_key(stmt: Any):
        if not (isinstance(stmt, dict) and stmt.get("stmt") == "Expr"):
            return None, None
        call = stmt.get("value") or {}
        if not (isinstance(call, dict) and call.get("type") == "Call"
                and isinstance(call.get("func"), str)):
            return None, None
        cargs = call.get("args") or []
        if len(cargs) != 1:
            return None, None
        return call["func"], _frss_dotget_key(cargs[0], cvar)

    wn1, rk = _walkcall_key(fw1)
    wn2, ek = _walkcall_key(fw2)
    if rk is None or ek is None or wn1 is None or wn1 != wn2:
        return None
    return {"name": func.get("name"), "param": dep_p, "acc": acc,
            "contracts_key": contracts_key, "requires_key": rk,
            "ensures_key": ek, "walker_name": wn1}


def _recognize_crn_walk(walkfunc: Dict[str, Any], acc: str,
                        call_names: "set") -> Optional[Dict[str, Any]]:
    """Match the lifted `_walk(node)` set-collect walk and extract the leaf
    discriminant literals. Fail-closed. Returns {type_key, type_val, func_key}."""
    params = walkfunc.get("formal_params") or []
    if len(params) != 1:
        return None
    node = params[0]
    body = walkfunc.get("body") or []
    if len(body) != 1:
        return None
    top = body[0]
    if not (isinstance(top, dict) and top.get("stmt") == "If"
            and _match_isinstance(top.get("test"), node, "dict")):
        return None
    darm = top.get("body") or []
    if len(darm) != 2:
        return None
    # darm[0]: if node.get("<tk>")=="<tv>" and isinstance(node.get("<fk>"),str):
    #              referenced.add(node["<fk>"])
    g = darm[0]
    if not (isinstance(g, dict) and g.get("stmt") == "If" and not g.get("orelse")):
        return None
    gt = g.get("test") or {}
    if not (isinstance(gt, dict) and gt.get("type") == "BinOp" and gt.get("op") == "and"):
        return None
    left = gt.get("left") or {}
    right = gt.get("right") or {}
    if not (isinstance(left, dict) and left.get("type") == "BinOp"
            and left.get("op") == "=="):
        return None
    type_key = _frss_dotget_key(left.get("left"), node)
    type_val = _clean_lit(_is_string(left.get("right")))
    if type_key is None or type_val is None:
        return None
    if not (isinstance(right, dict) and right.get("type") == "Call"
            and right.get("func") == "isinstance"):
        return None
    rargs = right.get("args") or []
    if len(rargs) != 2 or not _is_var(rargs[1], "str"):
        return None
    func_key = _frss_dotget_key(rargs[0], node)
    if func_key is None:
        return None
    # anti-facade: the guard body set_adds the REAL subscript read node["<fk>"]
    gb = g.get("body") or []
    if len(gb) != 1:
        return None
    addst = gb[0]
    if not (isinstance(addst, dict) and addst.get("stmt") == "Expr"):
        return None
    addcall = addst.get("value") or {}
    if not (isinstance(addcall, dict) and addcall.get("type") == "Call"
            and addcall.get("func") == f"{acc}.add"):
        return None
    aargs = addcall.get("args") or []
    if len(aargs) != 1:
        return None
    sub = aargs[0]
    if not (isinstance(sub, dict) and sub.get("type") == "Subscript"
            and _is_var(sub.get("value"), node)
            and _clean_lit(_is_string(sub.get("index"))) == func_key):
        return None
    # darm[1]: for x in node.values(): _walk(x)
    def _values_iter(it: Any) -> bool:
        return (isinstance(it, dict) and it.get("type") == "Call"
                and it.get("func") == f"{node}.values" and not it.get("args"))

    if not _frss_iter_selfcall(darm[1], call_names, node, _values_iter):
        return None
    # orelse: elif isinstance(node, (list, tuple)): for x in node: _walk(x)
    orelse = top.get("orelse") or []
    if len(orelse) != 1:
        return None
    lif2 = orelse[0]
    if not (isinstance(lif2, dict) and lif2.get("stmt") == "If"
            and not lif2.get("orelse")
            and _match_isinstance_tuple(lif2.get("test"), node, ("list", "tuple"))):
        return None
    lb = lif2.get("body") or []
    if len(lb) != 1:
        return None
    if not _frss_iter_selfcall(lb[0], call_names, node, lambda it: _is_var(it, node)):
        return None
    return {"type_key": type_key, "type_val": type_val, "func_key": func_key}


def recognize_contract_referenced_names_pairs(functions: List[Dict[str, Any]]
                                              ) -> Dict[str, Any]:
    """Pair the `_contract_referenced_names` OUTER wrapper with its lifted `_walk`
    sibling (by adjacency). Returns {"outer_ids": {id(outer): desc}, "walk_ids":
    {id(walk), ...}}. Never raises."""
    outer_ids: Dict[int, Dict[str, Any]] = {}
    walk_ids = set()
    try:
        n = len(functions)
        for i, f in enumerate(functions):
            if not isinstance(f, dict):
                continue
            try:
                od = _recognize_crn_outer(f)
            except Exception:
                od = None
            if od is None:
                continue
            if i + 1 >= n:
                continue
            wf = functions[i + 1]
            wn = od["walker_name"]
            wf_name = wf.get("name") if isinstance(wf, dict) else None
            if not (isinstance(wf, dict) and wf_name is not None
                    and (wf_name == wn or wf_name.endswith("__" + wn))):
                continue
            if id(wf) in walk_ids:
                continue
            call_names = {wn, wf_name}
            try:
                leaf = _recognize_crn_walk(wf, od["acc"], call_names)
            except Exception:
                leaf = None
            if leaf is None:
                continue
            desc = {"name": od["name"], "param": od["param"],
                    "contracts_key": od["contracts_key"],
                    "requires_key": od["requires_key"],
                    "ensures_key": od["ensures_key"]}
            desc.update(leaf)
            outer_ids[id(f)] = desc
            walk_ids.add(id(wf))
    except Exception:
        return {"outer_ids": {}, "walk_ids": set()}
    return {"outer_ids": outer_ids, "walk_ids": walk_ids}


def emit_contract_referenced_names_group(func: Dict[str, Any], desc: Dict[str, Any],
                                         whyml_ident) -> List[str]:
    """Emit `_contract_referenced_names` as a mutual `pyval`/`pydict`/`list pyval`
    set-UNION catamorphism (the `_func_returns_string_seq` skeleton with `set_union`
    for `||`, `const false` the empty base, `map string bool` the result). The leaf
    reads the real `node["func"]` string and `set_add`s it when `type=="Call"`; the
    OUTER folds `dep_funcs`, unioning the walk of each func's `contracts`'
    `requires`/`ensures` lists. `ensures True`; ledger 3 (no new type/axiom/cert)."""
    n = whyml_ident(desc["name"])
    P = f"{n}__"
    mv = _pvw_mv(desc["param"])
    tk, tv, fk = desc["type_key"], desc["type_val"], desc["func_key"]
    ck, rk, ek = desc["contracts_key"], desc["requires_key"], desc["ensures_key"]
    out: List[str] = []
    # literal-key readers
    out += _emit_skey_reader(f"{P}gtype", tk)       # option string: node["type"]
    out += _emit_pval_reader(f"{P}gfunc", fk)       # option pyval: node["func"]
    out += _emit_pval_reader(f"{P}gcontracts", ck)  # option pyval: func["contracts"]
    out += _emit_pval_reader(f"{P}grequires", rk)   # option pyval: contracts["requires"]
    out += _emit_pval_reader(f"{P}gensures", ek)    # option pyval: contracts["ensures"]
    # leaf: set_add node["func"] when type=="Call" and func is a string
    out.append(f"  let {P}leaf (d: pydict) : map string bool")
    out.append("    requires { true } ensures { true }")
    out.append(f"  = match {P}gtype d with")
    out.append(f'    | Some ty -> if pystr_eq ty "{tv}" then')
    out.append(f"                   (match {P}gfunc d with "
               "Some (PStr s) -> set_add (const false) s | _ -> const false end)")
    out.append("                 else const false")
    out.append("    | None -> const false end")
    # mutual set-union existence catamorphism over the pyval spine
    out.append(f"  let rec {P}v (v: pyval) : map string bool")
    out.append("    requires { true } ensures { true } variant { pv_size v }")
    out.append("  = match v with")
    out.append(f"    | PDict d -> set_union ({P}leaf d) ({P}dfold d)")
    out.append(f"    | PList xs -> {P}lfold xs")
    out.append("    | _ -> const false")
    out.append("    end")
    out.append(f"  with {P}dfold (d: pydict) : map string bool")
    out.append("    requires { true } ensures { true } variant { size_dict d }")
    out.append("  = match d with DNil -> const false")
    out.append("    | DCons _ v rest ->")
    out.append("        size_pos v;")
    out.append(f"        set_union ({P}v v) ({P}dfold rest) end")
    out.append(f"  with {P}lfold (xs: list pyval) : map string bool")
    out.append("    requires { true } ensures { true } variant { size_list xs }")
    out.append("  = match xs with Nil -> const false")
    out.append(f"    | Cons h t -> set_union ({P}v h) ({P}lfold t) end")
    # per-func: read the contracts sub-dict, union the walk of requires + ensures
    out.append(f"  let {P}perfunc (f: pyval) : map string bool")
    out.append("    requires { true } ensures { true }")
    out.append("  = match f with")
    out.append("    | PDict fd ->")
    out.append(f"        (match {P}gcontracts fd with")
    out.append("         | Some (PDict cd) ->")
    out.append("             set_union")
    out.append(f"               (match {P}grequires cd with "
               f"Some (PList rs) -> {P}lfold rs | _ -> const false end)")
    out.append(f"               (match {P}gensures cd with "
               f"Some (PList es) -> {P}lfold es | _ -> const false end)")
    out.append("         | _ -> const false end)")
    out.append("    | _ -> const false end")
    # fold over the dep_funcs list
    out.append(f"  let rec {P}ffold (fs: list pyval) : map string bool")
    out.append("    requires { true } ensures { true } variant { size_list fs }")
    out.append("  = match fs with Nil -> const false")
    out.append(f"    | Cons h t -> set_union ({P}perfunc h) ({P}ffold t) end")
    # entry: fold dep_funcs
    out.append(f"  let {n} ({mv}: pyval) : map string bool")
    out.append("    requires { true } ensures { true }")
    out.append(f"  = match {mv} with PList fs -> {P}ffold fs | _ -> const false end")
    return out


# ---- `_collect_field_decode_str_locals` (statements.py StatementEmissionMixin,
#      Module5 lambda-lift capture-threading SET-COLLECT sibling of
#      `_contract_referenced_names`): collect every local assigned the
#      null-terminated-field NAME-decode idiom. Live body:
#        out: Set[str] = set()
#        def rec(node):
#          if isinstance(node, dict):
#            if node.get("stmt") == "Assign" and isinstance(node.get("target"), str):
#              v = node.get("value", {})
#              if (isinstance(v, dict) and v.get("type") == "Call"
#                      and v.get("func") == "decode"
#                      and self._match_field_decode_idiom(v) is not None):
#                out.add(node["target"])
#            for x in node.values(): rec(x)
#          elif isinstance(node, list):
#            for x in node: rec(x)
#        rec(body_stmts); <dead getattr-reflect block>; return out
#      Same OUTER+lifted-`rec` adjacency pairing as `_contract_referenced_names`,
#      but the nested `def rec` captures a single mutable `out: Set[str]` (re-expressed
#      as a returned `map string bool` set-UNION catamorphism — NEVER a by-ref mutable
#      effect) + the immutable `self` (the idiom self-call is modeled OPAQUE). Module5
#      already hoists the nested `rec` to `<class>__rec` (its own `\trusted` marker keeps
#      it a bodyless `val` — harmless/unused; the outer's group-emit is self-contained).
#      The leaf set_adds the REAL `node["target"]` string under the concrete gate
#      (`stmt`=="Assign" & `target` is str & `value.type`=="Call" & `value.func`=="decode"
#      & the opaque `_match_field_decode_idiom(value)`). The idiom self-call becomes the
#      OPAQUE-BUT-REAL `val <n>__fdi (v:pyval):bool` (ensures-free = sound over-approx of
#      `is not None`, NOT an axiom — Gate-C-legal unmodeled self-source; the callee is
#      itself `\trusted`). Non-facade (every tag/key literal read off the body,
#      mutation-sensitive; the set-add of the real `target` string is the anti-vacuity
#      signal). The trailing `getattr(self,"_current_symbol_table",...)` reflection is dead
#      (getattr degenerates) and IGNORED by the self-contained emit -> `assigns \nothing`.
#      `set_add`/`set_union`/`const`/`pystr_eq` come free with the pydict theory. Keyed on
#      `id`; corpus-inert (name-gated; sole caller `_typed_local_vars` is `\trusted` ->
#      coupling-free). Ledger 3 (reuses the certified pyval/pydict ADT + set-union).

def _fdsl_flatten_and(node: Any) -> List[Any]:
    """Flatten a left-assoc `and` BinOp chain into its conjunct list."""
    if (isinstance(node, dict) and node.get("type") == "BinOp"
            and node.get("op") == "and"):
        return _fdsl_flatten_and(node.get("left")) + _fdsl_flatten_and(node.get("right"))
    return [node]


def _recognize_fdsl_outer(func: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    """Match the OUTER `_collect_field_decode_str_locals` wrapper. Fail-closed;
    None on any deviation. Returns {name, param, acc, walker_name}. The dead
    reflection block ([2],[3]) is not inspected (name-gated + emit-ignored)."""
    if not func.get("name", "").endswith("_collect_field_decode_str_locals"):
        return None
    if func.get("return_annotation") != "set":
        return None
    params = func.get("formal_params") or []
    if len(params) != 1:
        return None
    subj = params[0]
    body = func.get("body") or []
    if len(body) != 5:
        return None
    b0, b1, _b2, _b3, b4 = body
    # [0] out = set()
    if not (isinstance(b0, dict) and b0.get("stmt") == "Assign"):
        return None
    acc = b0.get("target")
    iv = b0.get("value") or {}
    if not (isinstance(acc, str) and isinstance(iv, dict) and iv.get("type") == "Call"
            and iv.get("func") == "set" and not iv.get("args")):
        return None
    # [1] Expr: rec(body_stmts)
    if not (isinstance(b1, dict) and b1.get("stmt") == "Expr"):
        return None
    call = b1.get("value") or {}
    if not (isinstance(call, dict) and call.get("type") == "Call"
            and isinstance(call.get("func"), str)):
        return None
    cargs = call.get("args") or []
    if len(cargs) != 1 or not _is_var(cargs[0], subj):
        return None
    walker_name = call["func"]
    # [4] return out
    if not (isinstance(b4, dict) and b4.get("stmt") == "Return"
            and _is_var(b4.get("value"), acc)):
        return None
    return {"name": func.get("name"), "param": subj, "acc": acc,
            "walker_name": walker_name}


def _recognize_fdsl_walk(walkfunc: Dict[str, Any], acc: str,
                         call_names: "set") -> Optional[Dict[str, Any]]:
    """Match the lifted `rec(node)` set-collect walk and extract every leaf
    discriminant literal. Fail-closed. Returns the discriminant descriptor."""
    params = walkfunc.get("formal_params") or []
    if len(params) != 1:
        return None
    node = params[0]
    body = walkfunc.get("body") or []
    if len(body) != 1:
        return None
    top = body[0]
    if not (isinstance(top, dict) and top.get("stmt") == "If"
            and _match_isinstance(top.get("test"), node, "dict")):
        return None
    darm = top.get("body") or []
    if len(darm) != 2:
        return None
    # darm[0]: if node.get(stmt_key)==stmt_val and isinstance(node.get(target_key),str):
    g = darm[0]
    if not (isinstance(g, dict) and g.get("stmt") == "If" and not g.get("orelse")):
        return None
    gt = g.get("test") or {}
    if not (isinstance(gt, dict) and gt.get("type") == "BinOp" and gt.get("op") == "and"):
        return None
    left = gt.get("left") or {}
    right = gt.get("right") or {}
    if not (isinstance(left, dict) and left.get("type") == "BinOp"
            and left.get("op") == "=="):
        return None
    stmt_key = _frss_dotget_key(left.get("left"), node)
    stmt_val = _clean_lit(_is_string(left.get("right")))
    if stmt_key is None or stmt_val is None:
        return None
    if not (isinstance(right, dict) and right.get("type") == "Call"
            and right.get("func") == "isinstance"):
        return None
    rargs = right.get("args") or []
    if len(rargs) != 2 or not _is_var(rargs[1], "str"):
        return None
    target_key = _frss_dotget_key(rargs[0], node)
    if target_key is None:
        return None
    # g.body: [ v = node.get(value_key, {}) ; if <4-conjunct>: out.add(node[target_key]) ]
    gb = g.get("body") or []
    if len(gb) != 2:
        return None
    va, gif = gb
    if not (isinstance(va, dict) and va.get("stmt") == "Assign"):
        return None
    vloc = va.get("target")
    value_key = _frss_dotget_key(va.get("value"), node)
    if not (isinstance(vloc, str) and value_key is not None):
        return None
    if not (isinstance(gif, dict) and gif.get("stmt") == "If" and not gif.get("orelse")):
        return None
    conj = _fdsl_flatten_and(gif.get("test") or {})
    if len(conj) != 4:
        return None
    c_isinst, c_type, c_func, c_idiom = conj
    if not _match_isinstance(c_isinst, vloc, "dict"):
        return None
    if not (isinstance(c_type, dict) and c_type.get("type") == "BinOp"
            and c_type.get("op") == "=="):
        return None
    vtype_key = _frss_dotget_key(c_type.get("left"), vloc)
    vtype_val = _clean_lit(_is_string(c_type.get("right")))
    if vtype_key is None or vtype_val is None:
        return None
    if not (isinstance(c_func, dict) and c_func.get("type") == "BinOp"
            and c_func.get("op") == "=="):
        return None
    vfunc_key = _frss_dotget_key(c_func.get("left"), vloc)
    vfunc_val = _clean_lit(_is_string(c_func.get("right")))
    if vfunc_key is None or vfunc_val is None:
        return None
    # c_idiom: self.<method>(v) != None  (the opaque field-decode-idiom self-call)
    if not (isinstance(c_idiom, dict) and c_idiom.get("type") == "BinOp"
            and c_idiom.get("op") == "!="):
        return None
    ic = c_idiom.get("left") or {}
    rn = c_idiom.get("right") or {}
    if not (isinstance(rn, dict) and rn.get("type") == "None"):
        return None
    if not (isinstance(ic, dict) and ic.get("type") == "Call"
            and isinstance(ic.get("func"), str)):
        return None
    iargs = ic.get("args") or []
    if len(iargs) != 1 or not _is_var(iargs[0], vloc):
        return None
    # anti-facade: the guard body set_adds the REAL subscript read node[target_key]
    ib = gif.get("body") or []
    if len(ib) != 1:
        return None
    addst = ib[0]
    if not (isinstance(addst, dict) and addst.get("stmt") == "Expr"):
        return None
    addcall = addst.get("value") or {}
    if not (isinstance(addcall, dict) and addcall.get("type") == "Call"
            and addcall.get("func") == f"{acc}.add"):
        return None
    aargs = addcall.get("args") or []
    if len(aargs) != 1:
        return None
    sub = aargs[0]
    if not (isinstance(sub, dict) and sub.get("type") == "Subscript"
            and _is_var(sub.get("value"), node)
            and _clean_lit(_is_string(sub.get("index"))) == target_key):
        return None
    # darm[1]: for x in node.values(): rec(x)
    def _values_iter(it: Any) -> bool:
        return (isinstance(it, dict) and it.get("type") == "Call"
                and it.get("func") == f"{node}.values" and not it.get("args"))

    if not _frss_iter_selfcall(darm[1], call_names, node, _values_iter):
        return None
    # orelse: elif isinstance(node, list): for x in node: rec(x)
    orelse = top.get("orelse") or []
    if len(orelse) != 1:
        return None
    lif2 = orelse[0]
    if not (isinstance(lif2, dict) and lif2.get("stmt") == "If"
            and not lif2.get("orelse")
            and _match_isinstance(lif2.get("test"), node, "list")):
        return None
    lb = lif2.get("body") or []
    if len(lb) != 1:
        return None
    if not _frss_iter_selfcall(lb[0], call_names, node, lambda it: _is_var(it, node)):
        return None
    return {"stmt_key": stmt_key, "stmt_val": stmt_val, "target_key": target_key,
            "value_key": value_key, "vtype_key": vtype_key, "vtype_val": vtype_val,
            "vfunc_key": vfunc_key, "vfunc_val": vfunc_val}


def recognize_field_decode_str_locals_pairs(functions: List[Dict[str, Any]]
                                            ) -> Dict[str, Any]:
    """Pair the `_collect_field_decode_str_locals` OUTER wrapper with its lifted
    `rec` sibling (by adjacency). Returns {"outer_ids": {id(outer): desc},
    "walk_ids": {id(rec), ...}}. Never raises."""
    outer_ids: Dict[int, Dict[str, Any]] = {}
    walk_ids = set()
    try:
        n = len(functions)
        for i, f in enumerate(functions):
            if not isinstance(f, dict):
                continue
            try:
                od = _recognize_fdsl_outer(f)
            except Exception:
                od = None
            if od is None:
                continue
            if i + 1 >= n:
                continue
            wf = functions[i + 1]
            wn = od["walker_name"]
            wf_name = wf.get("name") if isinstance(wf, dict) else None
            if not (isinstance(wf, dict) and wf_name is not None
                    and (wf_name == wn or wf_name.endswith("__" + wn))):
                continue
            if id(wf) in walk_ids:
                continue
            call_names = {wn, wf_name}
            try:
                leaf = _recognize_fdsl_walk(wf, od["acc"], call_names)
            except Exception:
                leaf = None
            if leaf is None:
                continue
            desc = {"name": od["name"], "param": od["param"]}
            desc.update(leaf)
            outer_ids[id(f)] = desc
            walk_ids.add(id(wf))
    except Exception:
        return {"outer_ids": {}, "walk_ids": set()}
    return {"outer_ids": outer_ids, "walk_ids": walk_ids}


def emit_field_decode_str_locals_group(func: Dict[str, Any], desc: Dict[str, Any],
                                       whyml_ident) -> List[str]:
    """Emit `_collect_field_decode_str_locals` as a mutual `pyval`/`pydict`/
    `list pyval` set-UNION catamorphism (the `_contract_referenced_names` skeleton).
    The leaf reads the real `node["target"]` string and `set_add`s it under the
    concrete field-decode gate (`stmt`=="Assign" & `target` is str & `value.type`==
    "Call" & `value.func`=="decode" & the OPAQUE `<n>__fdi value`). The mutable `out`
    accumulator is the returned set; the immutable `self` idiom-call is the opaque
    val. `ensures True`; ledger 3 (no new type/axiom/cert)."""
    n = whyml_ident(desc["name"])
    P = f"{n}__"
    mv = _pvw_mv(desc["param"])
    sv = desc["stmt_val"]
    vtv, vfv = desc["vtype_val"], desc["vfunc_val"]
    out: List[str] = []
    # literal-key readers (each reflects its key -> mutation-sensitive)
    out += _emit_skey_reader(f"{P}gstmt", desc["stmt_key"])    # node["stmt"] : opt string
    out += _emit_pval_reader(f"{P}gtarget", desc["target_key"])  # node["target"] : opt pyval
    out += _emit_pval_reader(f"{P}gvalue", desc["value_key"])    # node["value"] : opt pyval
    out += _emit_skey_reader(f"{P}gvtype", desc["vtype_key"])   # value["type"] : opt string
    out += _emit_skey_reader(f"{P}gvfunc", desc["vfunc_key"])   # value["func"] : opt string
    # opaque field-decode-idiom predicate == `self._match_field_decode_idiom(v) is not None`
    out.append(f"  val {P}fdi (v: pyval) : bool")
    # leaf: set_add node["target"] when the full concrete gate holds
    out.append(f"  let {P}leaf (d: pydict) : map string bool")
    out.append("    requires { true } ensures { true }")
    out.append(f"  = match {P}gstmt d with")
    out.append(f'    | Some st -> if pystr_eq st "{sv}" then')
    out.append(f"                   (match {P}gtarget d with")
    out.append("                    | Some (PStr tname) ->")
    out.append(f"                        (match {P}gvalue d with")
    out.append("                         | Some (PDict vd) ->")
    out.append(f"                             (match {P}gvtype vd with")
    out.append(f'                              | Some vt -> if pystr_eq vt "{vtv}" then')
    out.append(f"                                  (match {P}gvfunc vd with")
    out.append(f'                                   | Some vf ->')
    out.append(f'                                       if (pystr_eq vf "{vfv}") && ({P}fdi (PDict vd)) then')
    out.append("                                         set_add (const false) tname")
    out.append("                                       else const false")
    out.append("                                   | None -> const false end)")
    out.append("                                else const false")
    out.append("                              | None -> const false end)")
    out.append("                         | _ -> const false end)")
    out.append("                    | _ -> const false end)")
    out.append("                 else const false")
    out.append("    | None -> const false end")
    # mutual set-union existence catamorphism over the pyval spine
    out.append(f"  let rec {P}v (v: pyval) : map string bool")
    out.append("    requires { true } ensures { true } variant { pv_size v }")
    out.append("  = match v with")
    out.append(f"    | PDict d -> set_union ({P}leaf d) ({P}dfold d)")
    out.append(f"    | PList xs -> {P}lfold xs")
    out.append("    | _ -> const false")
    out.append("    end")
    out.append(f"  with {P}dfold (d: pydict) : map string bool")
    out.append("    requires { true } ensures { true } variant { size_dict d }")
    out.append("  = match d with DNil -> const false")
    out.append("    | DCons _ v rest ->")
    out.append("        size_pos v;")
    out.append(f"        set_union ({P}v v) ({P}dfold rest) end")
    out.append(f"  with {P}lfold (xs: list pyval) : map string bool")
    out.append("    requires { true } ensures { true } variant { size_list xs }")
    out.append("  = match xs with Nil -> const false")
    out.append(f"    | Cons h t -> set_union ({P}v h) ({P}lfold t) end")
    # entry: descend the whole argument through the catamorphism
    out.append(f"  let {n} ({mv}: pyval) : map string bool")
    out.append("    requires { true } ensures { true }")
    out.append(f"  = {P}v {mv}")
    return out


# ---- `_collect_string_elem_read_locals` (statements.py, TWO-SEQUENTIAL-CATAMORPHISM
#      SET-COLLECT sibling of `_collect_field_decode_str_locals`): the outer wraps the SAME
#      lambda-lifted `rec` adjacency, but the nested walk carries a CROSS-ACCUMULATOR
#      dependency between two sets. Live body:
#        ssf = getattr(self, "_module_string_seq_funcs", set())
#        if not ssf: return set()
#        str_arrays = set(); elem_reads = set()
